REPLACE INTO kb_case_type_rules (case_type, rules_json, updated_at) VALUES ('劳动', '{"name": "劳动人事争议", "keywords": ["工资", "欠薪", "拖欠", "劳动合同", "辞退", "解雇", "解除劳动", "用人单位", "员工", "经济补偿", "赔偿金", "双倍工资", "二倍工资", "社保", "工伤", "加班"], "elements": [["劳动关系与入职时间", ["入职", "用工", "工作满", "工作了", "年限", "年"], "确认建立劳动关系的具体日期（用工之日）及已工作年限"], ["书面劳动合同情况", ["未签", "没签", "签订", "书面劳动合同", "劳动合同"], "确认是否已签订书面劳动合同，以及未签合同持续的月数"], ["工资支付与违约事实", ["拖欠", "欠薪", "未足额", "未及时", "社保", "克扣", "辞退"], "确认用人单位是否存在未及时足额支付劳动报酬、未缴社保或违法解除等法定情形及证据"], ["当前在职/离职状态与时间", ["离职", "在职", "解除", "辞职", "开除"], "确认目前仍在职还是已解除劳动关系，以及解除通知的送达时间（关系到1年仲裁时效起算）"], ["用工所在地", ["北京", "上海", "天津", "重庆", "广东", "深圳", "广州", "浙江", "杭州", "江苏", "南京", "苏州", "山东", "四川", "成都", "湖北", "武汉"], "确认实际用工所在地（不同省市最低工资、社平工资及地方性劳动法规存在差异）"]], "procedural_notes": ["【程序前置】依《劳动争议调解仲裁法》第5条、第79条，劳动争议实行「仲裁前置」，当事人须先向有管辖权的劳动人事争议仲裁委员会申请仲裁，对仲裁裁决不服方可向人民法院起诉。", "【仲裁时效】依《劳动争议调解仲裁法》第27条，劳动争议申请仲裁的时效期间为 1 年（自知道或者应当知道权利被侵害之日起算）；拖欠劳动报酬争议在劳动关系存续期间不受 1 年限制，但劳动关系终止的，应当自终止之日起 1 年内提出。", "【二倍工资时效】主张未订立书面劳动合同二倍工资差额（最长期限11个月，自用工满1个月的次日至满1年的前一日）亦受 1 年仲裁时效限制。"]}', '2026-11-07T08:31:27.548681+00:00');
REPLACE INTO kb_case_type_rules (case_type, rules_json, updated_at) VALUES ('合同', '{"name": "民商事合同纠纷", "keywords": ["合同", "违约", "违约金", "解除合同", "继续履行", "赔偿损失", "定金", "押金", "货款", "付款", "交货", "逾期", "欺诈", "撤销"], "elements": [["合同订立与履行时间", ["年", "月", "日", "签订", "订立", "到期"], "确认合同成立/生效时间及约定的履行期限（决定适用《民法典》还是旧《合同法》）"], ["违约具体情形与催告情况", ["不履行", "逾期", "迟延", "催告", "拒绝", "瑕疵", "违约"], "确认对方违约的具体表现，若属迟延履行主要债务，确认是否已发出催告函并给予合理期限"], ["损失金额与违约金约定", ["损失", "违约金", "赔偿", "金额", "元", "万"], "确认合同约定的违约金计算标准及守约方实际遭受的直接损失与可得利益损失"]], "procedural_notes": ["【诉讼时效】依《民法典》第188条，向人民法院请求保护民事权利的普通诉讼时效期间为 3 年，自知道或者应当知道权利受到损害以及义务人之日起计算。", "【除斥期间】若主张受欺诈/胁迫请求撤销合同（《民法典》第148条、第152条），应当自知道或者应当知道撤销事由之日起 1 年内行使撤销权（该期间为除斥期间，不适用中止、中断）。", "【违约金调整】依《民法典合同编通则解释》第65条，约定违约金超过造成损失 30% 的，一般可认定为「过分高于造成的损失」，违约方（恶意违约除外）可请求法院或仲裁机构予以适当减少。"]}', '2026-11-07T08:31:27.548681+00:00');
REPLACE INTO kb_case_type_rules (case_type, rules_json, updated_at) VALUES ('公司', '{"name": "公司与股东出资纠纷", "keywords": ["公司", "股东", "出资", "认缴", "实缴", "注册资本", "抽逃出资", "股东会", "董事会", "分红", "利润分配", "连带责任", "法人人格否认"], "elements": [["公司设立与出资行为时间", ["年", "月", "成立", "设立", "章程"], "确认公司设立日期、章程约定的认缴出资期限及争议行为发生日（2024-07-01 新《公司法》施行前后规则不同）"], ["认缴与实缴明细", ["认缴", "实缴", "未缴", "出资额"], "确认股东认缴出资额、已实缴金额及是否届满认缴期限"], ["债权受损与滥用权利事实", ["不能清偿", "逃避债务", "混同", "严重损害"], "若主张股东对公司债务承担连带责任或出资加速到期，需确认公司是否已不能清偿到期债务或存在财产混同"]], "procedural_notes": ["【新旧法衔接】2023年修订《公司法》自 2024-07-01 起施行，规定有限责任公司认缴出资额须自成立之日起 5 年内缴足（第47条），存量公司适用国务院过渡期规定。", "【出资加速到期】依新《公司法》第54条，公司不能清偿到期债务的，公司或者已到期债权的债权人有权要求已认缴出资但未届出资期限的股东提前缴纳出资。"]}', '2026-11-07T08:31:27.548681+00:00');
REPLACE INTO kb_case_type_rules (case_type, rules_json, updated_at) VALUES ('侵权', '{"name": "侵权与交通事故责任纠纷", "keywords": ["撞伤", "交通事故", "侵权", "损害赔偿", "送货途中", "执行工作任务", "劳务派遣", "医疗费", "伤残", "过错", "行人", "机动车"], "elements": [["侵权发生时间与地点", ["年", "月", "日", "途中"], "确认侵权行为/事故发生的具体时间与地点"], ["行为人身份与职务关系", ["员工", "工作人员", "执行工作", "送货", "劳务派遣"], "确认侵权行为人是否系用人单位员工或劳务派遣人员，以及行为发生时是否在执行工作任务"], ["事故责任认定与保险情况", ["交警", "责任认定", "全责", "主责", "交强险", "商业险"], "确认交通事故责任认定书划分的过错比例，以及车辆交强险、商业三者险投保情况"]], "procedural_notes": ["【诉讼时效】依《民法典》第188条，侵权损害赔偿请求权诉讼时效为 3 年，自知道或应当知道权利受损及义务人之日起算。", "【赔付顺位】机动车交通事故损害先由保险公司在交强险限额内予以赔偿；不足部分按商业三者险及侵权责任比例分担；属职务行为的由用人单位承担侵权责任（单位担责后可向有故意或重大过失的员工追偿）。"]}', '2026-11-07T08:31:27.548681+00:00');
REPLACE INTO kb_case_type_rules (case_type, rules_json, updated_at) VALUES ('消费', '{"name": "消费者权益保护纠纷", "keywords": ["消费者", "商家", "经营者", "退一赔三", "三倍赔偿", "假货", "虚假宣传", "格式条款", "霸王条款", "店堂告示"], "elements": [["购买时间与交易凭证", ["年", "月", "购买", "订单", "发票"], "确认购买商品或接受服务的时间、消费金额及付款/订单凭证"], ["消费目的与欺诈事实", ["自用", "欺诈", "虚假", "格式条款"], "确认是否属于生活消费需要，以及经营者是否存在故意告知虚假情况或隐瞒真实情况的欺诈行为"]], "procedural_notes": ["【维权途径与时效】依《消费者权益保护法》第39条，可通过协商、消协调解、行政投诉（12315）、仲裁或诉讼解决；民事诉讼时效为 3 年。"]}', '2026-11-07T08:31:27.548681+00:00');
REPLACE INTO kb_case_type_rules (case_type, rules_json, updated_at) VALUES ('行政', '{"name": "行政处罚与行政救济争议", "keywords": ["行政处罚", "罚款", "吊销", "行政机关", "行政复议", "行政诉讼", "违法行为轻微", "初次违法", "首违不罚", "听证", "陈述", "申辩"], "elements": [["违法行为与处罚决定时间", ["年", "月", "日", "决定书", "收到"], "确认违法行为发生时间及收到《行政处罚决定书》的具体日期"], ["违法情节与主观过错", ["轻微", "初次", "及时改正", "没有造成危害", "主观过错"], "确认是否属于初次违法、危害后果轻微并及时改正，或是否有证据证明无主观过错"], ["行政程序合法性", ["告知", "听证", "陈述", "申辩"], "确认行政机关作出处罚前是否依法告知拟处罚内容、理由、依据及陈述申辩/听证权利"]], "procedural_notes": ["【行政复议期限】依《行政复议法》（2023修订）第20条，公民、法人或者其他组织认为行政行为侵犯其合法权益的，可以自知道或者应当知道该行政行为之日起 60 日内提出行政复议申请。", "【行政诉讼期限】依《行政诉讼法》第46条，直接向人民法院提起诉讼的，应当自知道或者应当知道作出行政行为之日起 6 个月内提出；经复议的，自收到复议决定书之日起 15 日内提起诉讼。"]}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO kb_certainty_patterns (pattern, replacement, updated_at) VALUES ('必然胜诉', '在证据充分前提下有较大可能获得支持', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO kb_certainty_patterns (pattern, replacement, updated_at) VALUES ('一定能(?:够)?获得', '在符合法定要件前提下倾向于可主张', '2026-11-07T08:31:27.548681+00:00');
