INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民法典', '主席令第45号', '法律', '', '', '2020-05-28', '2021-01-01', '', '现行有效', '', '第143条', '', '具备下列条件的民事法律行为有效：（一）行为人具有相应的民事行为能力；（二）意思表示真实；（三）不违反法律、行政法规的强制性规定，不违背公序良俗。', '全国人民代表大会', '民事', '一般', 0, '', 0, 1, '', '2021-01-01', 'substantive', '{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第143条", "paragraph": "", "content": "具备下列条件的民事法律行为有效：（一）行为人具有相应的民事行为能力；（二）意思表示真实；（三）不违反法律、行政法规的强制性规定，不违背公序良俗。", "source": "全国人民代表大会", "category": "民事", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2021-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民法典', '主席令第45号', '法律', '', '', '2020-05-28', '2021-01-01', '', '现行有效', '', '第153条', '', '违反法律、行政法规的强制性规定的民事法律行为无效。但是，该强制性规定不导致该民事法律行为无效的除外。违背公序良俗的民事法律行为无效。', '全国人民代表大会', '民事', '一般', 0, '', 0, 1, '', '2021-01-01', 'substantive', '{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第153条", "paragraph": "", "content": "违反法律、行政法规的强制性规定的民事法律行为无效。但是，该强制性规定不导致该民事法律行为无效的除外。违背公序良俗的民事法律行为无效。", "source": "全国人民代表大会", "category": "民事", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2021-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民法典', '主席令第45号', '法律', '', '', '2020-05-28', '2021-01-01', '', '现行有效', '', '第509条', '', '当事人应当按照约定全面履行自己的义务。当事人应当遵循诚信原则，根据合同的性质、目的和交易习惯履行通知、协助、保密等义务。', '全国人民代表大会', '合同', '一般', 0, '', 0, 1, '', '2021-01-01', 'substantive', '{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第509条", "paragraph": "", "content": "当事人应当按照约定全面履行自己的义务。当事人应当遵循诚信原则，根据合同的性质、目的和交易习惯履行通知、协助、保密等义务。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2021-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民法典', '主席令第45号', '法律', '', '', '2020-05-28', '2021-01-01', '', '现行有效', '', '第563条', '', '有下列情形之一的，当事人可以解除合同：（一）因不可抗力致使不能实现合同目的；（二）在履行期限届满前，当事人一方明确表示或者以自己的行为表明不履行主要债务；（三）当事人一方迟延履行主要债务，经催告后在合理期限内仍未履行；（四）当事人一方迟延履行债务或者有其他违约行为致使不能实现合同目的；（五）法律规定的其他情形。', '全国人民代表大会', '合同', '一般', 0, '', 0, 1, '', '2021-01-01', 'substantive', '{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第563条", "paragraph": "", "content": "有下列情形之一的，当事人可以解除合同：（一）因不可抗力致使不能实现合同目的；（二）在履行期限届满前，当事人一方明确表示或者以自己的行为表明不履行主要债务；（三）当事人一方迟延履行主要债务，经催告后在合理期限内仍未履行；（四）当事人一方迟延履行债务或者有其他违约行为致使不能实现合同目的；（五）法律规定的其他情形。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2021-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民法典', '主席令第45号', '法律', '', '', '2020-05-28', '2021-01-01', '', '现行有效', '', '第577条', '', '当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。', '全国人民代表大会', '合同', '一般', 0, '', 0, 1, '', '2021-01-01', 'substantive', '{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第577条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2021-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民法典', '主席令第45号', '法律', '', '', '2020-05-28', '2021-01-01', '', '现行有效', '', '第584条', '', '当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。', '全国人民代表大会', '合同', '一般', 0, '', 0, 1, '', '2021-01-01', 'substantive', '{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第584条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2021-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民法典', '主席令第45号', '法律', '', '', '2020-05-28', '2021-01-01', '', '现行有效', '', '第148条', '', '一方以欺诈手段，使对方在违背真实意思的情况下实施的民事法律行为，受欺诈方有权请求人民法院或者仲裁机构予以撤销。', '全国人民代表大会', '民事', '一般', 0, '', 0, 1, '', '2021-01-01', 'substantive', '{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第148条", "paragraph": "", "content": "一方以欺诈手段，使对方在违背真实意思的情况下实施的民事法律行为，受欺诈方有权请求人民法院或者仲裁机构予以撤销。", "source": "全国人民代表大会", "category": "民事", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2021-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民法典', '主席令第45号', '法律', '', '', '2020-05-28', '2021-01-01', '', '现行有效', '', '第1165条', '', '行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。依照法律规定推定行为人有过错，其不能证明自己没有过错的，应当承担侵权责任。', '全国人民代表大会', '侵权', '一般', 0, '', 0, 1, '', '2021-01-01', 'substantive', '{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第1165条", "paragraph": "", "content": "行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。依照法律规定推定行为人有过错，其不能证明自己没有过错的，应当承担侵权责任。", "source": "全国人民代表大会", "category": "侵权", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2021-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民法典', '主席令第45号', '法律', '', '', '2020-05-28', '2021-01-01', '', '现行有效', '', '第1191条', '', '用人单位的工作人员因执行工作任务造成他人损害，由用人单位承担侵权责任。用人单位承担侵权责任后，可以向有故意或者重大过失的工作人员追偿。劳务派遣期间，被派遣的工作人员因执行工作任务造成他人损害的，由接受劳务派遣的用工单位承担侵权责任；劳务派遣单位有过错的，承担相应的责任。', '全国人民代表大会', '侵权', '一般', 0, '', 0, 1, '', '2021-01-01', 'substantive', '{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第1191条", "paragraph": "", "content": "用人单位的工作人员因执行工作任务造成他人损害，由用人单位承担侵权责任。用人单位承担侵权责任后，可以向有故意或者重大过失的工作人员追偿。劳务派遣期间，被派遣的工作人员因执行工作任务造成他人损害的，由接受劳务派遣的用工单位承担侵权责任；劳务派遣单位有过错的，承担相应的责任。", "source": "全国人民代表大会", "category": "侵权", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2021-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民法典', '主席令第45号', '法律', '', '', '2020-05-28', '2021-01-01', '', '现行有效', '', '第188条', '', '向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。诉讼时效期间自权利人知道或者应当知道权利受到损害以及义务人之日起计算。但是，自权利受到损害之日起超过二十年的，人民法院不予保护。', '全国人民代表大会', '民事', '一般', 0, '', 0, 1, '', '2021-01-01', 'substantive', '{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第188条", "paragraph": "", "content": "向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。诉讼时效期间自权利人知道或者应当知道权利受到损害以及义务人之日起计算。但是，自权利受到损害之日起超过二十年的，人民法院不予保护。", "source": "全国人民代表大会", "category": "民事", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2021-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民法典', '主席令第45号', '法律', '', '', '2020-05-28', '2021-01-01', '', '现行有效', '', '第985条', '', '得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付；（二）债务到期之前的清偿；（三）明知无给付义务而进行的债务清偿。', '全国人民代表大会', '民事', '一般', 0, '', 0, 1, '', '2021-01-01', 'substantive', '{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第985条", "paragraph": "", "content": "得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付；（二）债务到期之前的清偿；（三）明知无给付义务而进行的债务清偿。", "source": "全国人民代表大会", "category": "民事", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2021-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国劳动合同法', '主席令第73号（2012年修正）', '法律', '', '', '2007-06-29', '2013-07-01', '', '现行有效', '', '第10条', '', '建立劳动关系，应当订立书面劳动合同。已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。', '全国人民代表大会常务委员会', '劳动', '特别', 0, '', 0, 1, '', '2008-01-01', 'substantive', '{"law_name": "中华人民共和国劳动合同法", "document_number": "主席令第73号（2012年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2007-06-29", "effective_date": "2013-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第10条", "paragraph": "", "content": "建立劳动关系，应当订立书面劳动合同。已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。", "source": "全国人民代表大会常务委员会", "category": "劳动", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2008-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国劳动合同法', '主席令第73号（2012年修正）', '法律', '', '', '2007-06-29', '2013-07-01', '', '现行有效', '', '第38条', '', '用人单位有下列情形之一的，劳动者可以解除劳动合同：（一）未按照劳动合同约定提供劳动保护或者劳动条件的；（二）未及时足额支付劳动报酬的；（三）未依法为劳动者缴纳社会保险费的；（四）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的；（五）因本法第二十六条第一款规定的情形致使劳动合同无效的；（六）法律、行政法规规定劳动者可以解除劳动合同的其他情形。', '全国人民代表大会常务委员会', '劳动', '特别', 0, '', 0, 1, '', '2008-01-01', 'substantive', '{"law_name": "中华人民共和国劳动合同法", "document_number": "主席令第73号（2012年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2007-06-29", "effective_date": "2013-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第38条", "paragraph": "", "content": "用人单位有下列情形之一的，劳动者可以解除劳动合同：（一）未按照劳动合同约定提供劳动保护或者劳动条件的；（二）未及时足额支付劳动报酬的；（三）未依法为劳动者缴纳社会保险费的；（四）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的；（五）因本法第二十六条第一款规定的情形致使劳动合同无效的；（六）法律、行政法规规定劳动者可以解除劳动合同的其他情形。", "source": "全国人民代表大会常务委员会", "category": "劳动", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2008-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国劳动合同法', '主席令第73号（2012年修正）', '法律', '', '', '2007-06-29', '2013-07-01', '', '现行有效', '', '第47条', '', '经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。劳动者月工资高于本地区上年度职工月平均工资三倍的，向其支付经济补偿的标准按职工月平均工资三倍的数额支付，向其支付经济补偿的年限最高不超过十二年。', '全国人民代表大会常务委员会', '劳动', '特别', 0, '', 0, 1, '', '2008-01-01', 'substantive', '{"law_name": "中华人民共和国劳动合同法", "document_number": "主席令第73号（2012年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2007-06-29", "effective_date": "2013-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第47条", "paragraph": "", "content": "经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。劳动者月工资高于本地区上年度职工月平均工资三倍的，向其支付经济补偿的标准按职工月平均工资三倍的数额支付，向其支付经济补偿的年限最高不超过十二年。", "source": "全国人民代表大会常务委员会", "category": "劳动", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2008-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国劳动合同法', '主席令第73号（2012年修正）', '法律', '', '', '2007-06-29', '2013-07-01', '', '现行有效', '', '第82条', '', '用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。', '全国人民代表大会常务委员会', '劳动', '特别', 0, '', 0, 1, '', '2008-01-01', 'substantive', '{"law_name": "中华人民共和国劳动合同法", "document_number": "主席令第73号（2012年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2007-06-29", "effective_date": "2013-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第82条", "paragraph": "", "content": "用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。", "source": "全国人民代表大会常务委员会", "category": "劳动", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2008-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国劳动合同法', '主席令第73号（2012年修正）', '法律', '', '', '2007-06-29', '2013-07-01', '', '现行有效', '', '第87条', '', '用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。', '全国人民代表大会常务委员会', '劳动', '特别', 0, '', 0, 1, '', '2008-01-01', 'substantive', '{"law_name": "中华人民共和国劳动合同法", "document_number": "主席令第73号（2012年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2007-06-29", "effective_date": "2013-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第87条", "paragraph": "", "content": "用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。", "source": "全国人民代表大会常务委员会", "category": "劳动", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2008-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国消费者权益保护法', '主席令第7号（2013年修正）', '法律', '', '', '1993-10-31', '2014-03-15', '', '现行有效', '', '第26条', '', '经营者在经营活动中使用格式条款的，应当以显著方式提请消费者注意与消费者有重大利害关系的内容，并按照消费者的要求予以说明。经营者不得以格式条款、通知、声明、店堂告示等方式，作出排除或者限制消费者权利、减轻或者免除经营者责任、加重消费者责任等对消费者不公平、不合理的规定。含有前述内容的，其内容无效。', '全国人民代表大会常务委员会', '消费', '特别', 0, '', 0, 1, '', '2014-03-15', 'substantive', '{"law_name": "中华人民共和国消费者权益保护法", "document_number": "主席令第7号（2013年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "1993-10-31", "effective_date": "2014-03-15", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第26条", "paragraph": "", "content": "经营者在经营活动中使用格式条款的，应当以显著方式提请消费者注意与消费者有重大利害关系的内容，并按照消费者的要求予以说明。经营者不得以格式条款、通知、声明、店堂告示等方式，作出排除或者限制消费者权利、减轻或者免除经营者责任、加重消费者责任等对消费者不公平、不合理的规定。含有前述内容的，其内容无效。", "source": "全国人民代表大会常务委员会", "category": "消费", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2014-03-15", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国消费者权益保护法', '主席令第7号（2013年修正）', '法律', '', '', '1993-10-31', '2014-03-15', '', '现行有效', '', '第39条', '', '消费者和经营者发生消费者权益争议的，可以通过下列途径解决：（一）与经营者协商和解；（二）请求消费者协会或者依法成立的其他调解组织调解；（三）向有关行政部门投诉；（四）根据与经营者达成的仲裁协议提请仲裁机构仲裁；（五）向人民法院提起诉讼。', '全国人民代表大会常务委员会', '消费', '特别', 0, '', 0, 1, '', '1994-01-01', 'substantive', '{"law_name": "中华人民共和国消费者权益保护法", "document_number": "主席令第7号（2013年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "1993-10-31", "effective_date": "2014-03-15", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第39条", "paragraph": "", "content": "消费者和经营者发生消费者权益争议的，可以通过下列途径解决：（一）与经营者协商和解；（二）请求消费者协会或者依法成立的其他调解组织调解；（三）向有关行政部门投诉；（四）根据与经营者达成的仲裁协议提请仲裁机构仲裁；（五）向人民法院提起诉讼。", "source": "全国人民代表大会常务委员会", "category": "消费", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "1994-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国消费者权益保护法', '主席令第7号（2013年修正）', '法律', '', '', '1993-10-31', '2014-03-15', '', '现行有效', '', '第55条', '', '经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。', '全国人民代表大会常务委员会', '消费', '特别', 0, '', 0, 1, '', '2014-03-15', 'substantive', '{"law_name": "中华人民共和国消费者权益保护法", "document_number": "主席令第7号（2013年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "1993-10-31", "effective_date": "2014-03-15", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第55条", "paragraph": "", "content": "经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。", "source": "全国人民代表大会常务委员会", "category": "消费", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2014-03-15", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国道路交通安全法', '主席令第47号（2011年修正）', '法律', '', '', '2003-10-28', '2011-05-01', '', '现行有效', '', '第76条', '', '机动车发生交通事故造成人身伤亡、财产损失的，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿；不足的部分，机动车之间发生交通事故的，由有过错的一方承担赔偿责任；双方都有过错的，按照各自过错的比例分担责任。机动车与非机动车驾驶人、行人之间发生交通事故，非机动车驾驶人、行人没有过错的，由机动车一方承担赔偿责任；有证据证明非机动车驾驶人、行人有过错的，根据过错程度适当减轻机动车一方的赔偿责任；机动车一方没有过错的，承担不超过百分之十的赔偿责任。', '全国人民代表大会常务委员会', '交通', '特别', 0, '', 0, 1, '', '2008-05-01', 'substantive', '{"law_name": "中华人民共和国道路交通安全法", "document_number": "主席令第47号（2011年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2003-10-28", "effective_date": "2011-05-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第76条", "paragraph": "", "content": "机动车发生交通事故造成人身伤亡、财产损失的，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿；不足的部分，机动车之间发生交通事故的，由有过错的一方承担赔偿责任；双方都有过错的，按照各自过错的比例分担责任。机动车与非机动车驾驶人、行人之间发生交通事故，非机动车驾驶人、行人没有过错的，由机动车一方承担赔偿责任；有证据证明非机动车驾驶人、行人有过错的，根据过错程度适当减轻机动车一方的赔偿责任；机动车一方没有过错的，承担不超过百分之十的赔偿责任。", "source": "全国人民代表大会常务委员会", "category": "交通", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "article_effective_date": "2008-05-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民事诉讼法', '主席令第106号（2021年修正）', '法律', '', '', '1991-04-09', '2022-01-01', '', '现行有效', '', '第67条', '', '当事人对自己提出的主张，有责任提供证据。当事人及其诉讼代理人因客观原因不能自行收集的证据，或者人民法院认为审理案件需要的证据，人民法院应当调查收集。人民法院应当按照法定程序，全面地、客观地审查核实证据。', '全国人民代表大会常务委员会', '诉讼', '一般', 0, '', 0, 1, '', '1991-04-09', 'procedural', '{"law_name": "中华人民共和国民事诉讼法", "document_number": "主席令第106号（2021年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "1991-04-09", "effective_date": "2022-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第67条", "paragraph": "", "content": "当事人对自己提出的主张，有责任提供证据。当事人及其诉讼代理人因客观原因不能自行收集的证据，或者人民法院认为审理案件需要的证据，人民法院应当调查收集。人民法院应当按照法定程序，全面地、客观地审查核实证据。", "source": "全国人民代表大会常务委员会", "category": "诉讼", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "procedural", "article_effective_date": "1991-04-09"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国公司法', '主席令第15号（2023年修订）', '法律', '', '', '2023-12-29', '2024-07-01', '', '现行有效', '', '第3条', '', '公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。有限责任公司的股东以其认缴的出资额为限对公司承担责任；股份有限公司的股东以其认购的股份为限对公司承担责任。', '全国人民代表大会常务委员会', '公司', '特别', 0, '', 0, 1, '', '2024-07-01', 'substantive', '{"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第3条", "paragraph": "", "content": "公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。有限责任公司的股东以其认缴的出资额为限对公司承担责任；股份有限公司的股东以其认购的股份为限对公司承担责任。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "substantive", "article_effective_date": "2024-07-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国公司法', '主席令第15号（2023年修订）', '法律', '', '', '2023-12-29', '2024-07-01', '', '现行有效', '', '第4条', '', '公司股东对公司依法享有资产收益、参与重大决策和选择管理者等权利。', '全国人民代表大会常务委员会', '公司', '特别', 0, '', 0, 1, '', '2024-07-01', 'substantive', '{"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第4条", "paragraph": "", "content": "公司股东对公司依法享有资产收益、参与重大决策和选择管理者等权利。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "substantive", "article_effective_date": "2024-07-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国公司法', '主席令第15号（2023年修订）', '法律', '', '', '2023-12-29', '2024-07-01', '', '现行有效', '', '第20条', '', '公司股东应当遵守法律、行政法规和公司章程，依法行使股东权利，不得滥用股东权利损害公司或者其他股东的利益；不得滥用公司法人独立地位和股东有限责任损害公司债权人的利益。公司股东滥用公司法人独立地位和股东有限责任，逃避债务，严重损害公司债权人利益的，应当对公司债务承担连带责任。', '全国人民代表大会常务委员会', '公司', '特别', 0, '', 0, 1, '', '2024-07-01', 'substantive', '{"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第20条", "paragraph": "", "content": "公司股东应当遵守法律、行政法规和公司章程，依法行使股东权利，不得滥用股东权利损害公司或者其他股东的利益；不得滥用公司法人独立地位和股东有限责任损害公司债权人的利益。公司股东滥用公司法人独立地位和股东有限责任，逃避债务，严重损害公司债权人利益的，应当对公司债务承担连带责任。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "substantive", "article_effective_date": "2024-07-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国公司法', '主席令第15号（2023年修订）', '法律', '', '', '2023-12-29', '2024-07-01', '', '现行有效', '', '第54条', '', '公司不能清偿到期债务的，公司或者已到期债权的债权人有权要求已认缴出资但未届出资期限的股东提前缴纳出资。', '全国人民代表大会常务委员会', '公司', '特别', 0, '', 0, 1, '2023年修订新增股东出资加速到期规则，自2024-07-01起施行。', '2024-07-01', 'substantive', '{"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第54条", "paragraph": "", "content": "公司不能清偿到期债务的，公司或者已到期债权的债权人有权要求已认缴出资但未届出资期限的股东提前缴纳出资。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "2023年修订新增股东出资加速到期规则，自2024-07-01起施行。", "norm_type": "substantive", "article_effective_date": "2024-07-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国公司法', '主席令第15号（2023年修订）', '法律', '', '', '2023-12-29', '2024-07-01', '', '现行有效', '', '第59条', '', '股东会行使下列职权：（一）选举和更换董事、监事，决定有关董事、监事的报酬事项；（二）审议批准董事会的报告；（三）审议批准监事会的报告；（四）审议批准公司的利润分配方案和弥补亏损方案；（五）对公司增加或者减少注册资本作出决议；（六）对发行公司债券作出决议；（七）对公司合并、分立、解散、清算或者变更公司形式作出决议；（八）修改公司章程；（九）公司章程规定的其他职权。', '全国人民代表大会常务委员会', '公司', '特别', 0, '', 0, 1, '', '2024-07-01', 'substantive', '{"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第59条", "paragraph": "", "content": "股东会行使下列职权：（一）选举和更换董事、监事，决定有关董事、监事的报酬事项；（二）审议批准董事会的报告；（三）审议批准监事会的报告；（四）审议批准公司的利润分配方案和弥补亏损方案；（五）对公司增加或者减少注册资本作出决议；（六）对发行公司债券作出决议；（七）对公司合并、分立、解散、清算或者变更公司形式作出决议；（八）修改公司章程；（九）公司章程规定的其他职权。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "substantive", "article_effective_date": "2024-07-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国公司法', '主席令第15号（2023年修订）', '法律', '', '', '2023-12-29', '2024-07-01', '', '现行有效', '', '第210条', '', '公司弥补亏损和提取公积金后所余税后利润，有限责任公司按照股东实缴的出资比例分配利润，全体股东约定不按照出资比例分配利润的除外；股份有限公司按照股东所持有的股份比例分配利润，公司章程另有规定的除外。', '全国人民代表大会常务委员会', '公司', '特别', 0, '', 0, 1, '', '2024-07-01', 'substantive', '{"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第210条", "paragraph": "", "content": "公司弥补亏损和提取公积金后所余税后利润，有限责任公司按照股东实缴的出资比例分配利润，全体股东约定不按照出资比例分配利润的除外；股份有限公司按照股东所持有的股份比例分配利润，公司章程另有规定的除外。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "substantive", "article_effective_date": "2024-07-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国行政诉讼法', '主席令第71号（2017年修正）', '法律', '', '', '1989-04-04', '2017-07-01', '', '现行有效', '', '第12条', '', '人民法院受理公民、法人或者其他组织提起的下列诉讼：（一）对行政拘留、罚款、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、警告等行政处罚不服的；（二）对限制人身自由或者对财产的查封、扣押、冻结等行政强制措施和行政强制执行不服的；（三）申请行政许可，行政机关拒绝或者在法定期限内不予答复，或者对行政机关作出的有关行政许可的其他决定不服的；（四）对行政机关作出的关于确认土地、矿藏、水流、森林、山岭、草原、荒地、滩涂、海域等自然资源的所有权或者使用权的决定不服的；（五）对征收、征用决定及其补偿决定不服的；（六）申请行政机关履行保护人身权、财产权等合法权益的法定职责，行政机关拒绝履行或者不予答复的；（七）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权的；（八）认为行政机关滥用行政权力排除或者限制竞争的；（九）认为行政机关违法集资、摊派费用或者违法要求履行其他义务的；（十）认为行政机关没有依法支付抚恤金、最低生活保障待遇或者社会保险待遇的；（十一）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议的；（十二）认为行政机关侵犯其他人身权、财产权等合法权益的。', '全国人民代表大会常务委员会', '行政', '一般', 0, '', 0, 1, '', '2015-05-01', 'procedural', '{"law_name": "中华人民共和国行政诉讼法", "document_number": "主席令第71号（2017年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "1989-04-04", "effective_date": "2017-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第12条", "paragraph": "", "content": "人民法院受理公民、法人或者其他组织提起的下列诉讼：（一）对行政拘留、罚款、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、警告等行政处罚不服的；（二）对限制人身自由或者对财产的查封、扣押、冻结等行政强制措施和行政强制执行不服的；（三）申请行政许可，行政机关拒绝或者在法定期限内不予答复，或者对行政机关作出的有关行政许可的其他决定不服的；（四）对行政机关作出的关于确认土地、矿藏、水流、森林、山岭、草原、荒地、滩涂、海域等自然资源的所有权或者使用权的决定不服的；（五）对征收、征用决定及其补偿决定不服的；（六）申请行政机关履行保护人身权、财产权等合法权益的法定职责，行政机关拒绝履行或者不予答复的；（七）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权的；（八）认为行政机关滥用行政权力排除或者限制竞争的；（九）认为行政机关违法集资、摊派费用或者违法要求履行其他义务的；（十）认为行政机关没有依法支付抚恤金、最低生活保障待遇或者社会保险待遇的；（十一）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议的；（十二）认为行政机关侵犯其他人身权、财产权等合法权益的。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "procedural", "article_effective_date": "2015-05-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国行政诉讼法', '主席令第71号（2017年修正）', '法律', '', '', '1989-04-04', '2017-07-01', '', '现行有效', '', '第70条', '', '行政行为有下列情形之一的，人民法院判决撤销或者部分撤销，并可以判决被告重新作出行政行为：（一）主要证据不足的；（二）适用法律、法规错误的；（三）违反法定程序的；（四）超越职权的；（五）滥用职权的；（六）明显不当的。', '全国人民代表大会常务委员会', '行政', '一般', 0, '', 0, 1, '', '2015-05-01', 'procedural', '{"law_name": "中华人民共和国行政诉讼法", "document_number": "主席令第71号（2017年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "1989-04-04", "effective_date": "2017-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第70条", "paragraph": "", "content": "行政行为有下列情形之一的，人民法院判决撤销或者部分撤销，并可以判决被告重新作出行政行为：（一）主要证据不足的；（二）适用法律、法规错误的；（三）违反法定程序的；（四）超越职权的；（五）滥用职权的；（六）明显不当的。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "procedural", "article_effective_date": "2015-05-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国行政诉讼法', '主席令第71号（2017年修正）', '法律', '', '', '1989-04-04', '2017-07-01', '', '现行有效', '', '第89条', '', '人民法院审理上诉案件，按照下列情形，分别处理：（一）原判决、裁定认定事实清楚，适用法律、法规正确的，判决或者裁定驳回上诉，维持原判决、裁定；（二）原判决、裁定认定事实错误或者适用法律、法规错误的，依法改判、撤销或者变更；（三）原判决认定基本事实不清、证据不足的，发回原审人民法院重审，或者查清事实后改判；（四）原判决遗漏当事人或者违法缺席判决等严重违反法定程序的，裁定撤销原判决，发回原审人民法院重审。', '全国人民代表大会常务委员会', '行政', '一般', 0, '', 0, 1, '', '2015-05-01', 'procedural', '{"law_name": "中华人民共和国行政诉讼法", "document_number": "主席令第71号（2017年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "1989-04-04", "effective_date": "2017-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第89条", "paragraph": "", "content": "人民法院审理上诉案件，按照下列情形，分别处理：（一）原判决、裁定认定事实清楚，适用法律、法规正确的，判决或者裁定驳回上诉，维持原判决、裁定；（二）原判决、裁定认定事实错误或者适用法律、法规错误的，依法改判、撤销或者变更；（三）原判决认定基本事实不清、证据不足的，发回原审人民法院重审，或者查清事实后改判；（四）原判决遗漏当事人或者违法缺席判决等严重违反法定程序的，裁定撤销原判决，发回原审人民法院重审。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "procedural", "article_effective_date": "2015-05-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国行政处罚法', '主席令第70号（2021年修订）', '法律', '', '', '1996-03-17', '2021-07-15', '', '现行有效', '', '第4条', '', '公民、法人或者其他组织违反行政管理秩序的行为，应当给予行政处罚的，依照本法由法律、法规、规章规定，并由行政机关依照本法规定的程序实施。设定和实施行政处罚必须以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当。对违法行为给予行政处罚的规定必须公布；未经公布的，不得作为行政处罚的依据。', '全国人民代表大会常务委员会', '行政', '一般', 0, '', 0, 1, '', '1996-10-01', 'administrative_penalty', '{"law_name": "中华人民共和国行政处罚法", "document_number": "主席令第70号（2021年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "1996-03-17", "effective_date": "2021-07-15", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第4条", "paragraph": "", "content": "公民、法人或者其他组织违反行政管理秩序的行为，应当给予行政处罚的，依照本法由法律、法规、规章规定，并由行政机关依照本法规定的程序实施。设定和实施行政处罚必须以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当。对违法行为给予行政处罚的规定必须公布；未经公布的，不得作为行政处罚的依据。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "administrative_penalty", "article_effective_date": "1996-10-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国行政处罚法', '主席令第70号（2021年修订）', '法律', '', '', '1996-03-17', '2021-07-15', '', '现行有效', '', '第33条', '', '违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。', '全国人民代表大会常务委员会', '行政', '一般', 0, '', 0, 1, '', '2021-07-15', 'administrative_penalty', '{"law_name": "中华人民共和国行政处罚法", "document_number": "主席令第70号（2021年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "1996-03-17", "effective_date": "2021-07-15", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第33条", "paragraph": "", "content": "违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "administrative_penalty", "article_effective_date": "2021-07-15"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国行政处罚法', '主席令第70号（2021年修订）', '法律', '', '', '1996-03-17', '2021-07-15', '', '现行有效', '', '第44条', '', '行政机关在作出行政处罚决定之前，应当告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人依法享有的陈述、申辩、要求听证等权利。', '全国人民代表大会常务委员会', '行政', '一般', 0, '', 0, 1, '', '1996-10-01', 'administrative_penalty', '{"law_name": "中华人民共和国行政处罚法", "document_number": "主席令第70号（2021年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "1996-03-17", "effective_date": "2021-07-15", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第44条", "paragraph": "", "content": "行政机关在作出行政处罚决定之前，应当告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人依法享有的陈述、申辩、要求听证等权利。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "administrative_penalty", "article_effective_date": "1996-10-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国行政复议法', '主席令第9号（2023年修订）', '法律', '', '', '1999-04-29', '2024-01-01', '', '现行有效', '', '第11条', '', '有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；（二）对行政机关作出的行政强制措施、行政强制执行决定不服；（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；（四）对行政机关作出的征收征用决定及其补偿决定不服；（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；（八）认为行政机关在政府信息公开工作中侵犯其合法权益；（九）认为行政机关滥用行政权力排除或者限制竞争；（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。', '全国人民代表大会常务委员会', '行政', '一般', 0, '', 0, 1, '', '2024-01-01', 'procedural', '{"law_name": "中华人民共和国行政复议法", "document_number": "主席令第9号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "1999-04-29", "effective_date": "2024-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第11条", "paragraph": "", "content": "有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；（二）对行政机关作出的行政强制措施、行政强制执行决定不服；（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；（四）对行政机关作出的征收征用决定及其补偿决定不服；（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；（八）认为行政机关在政府信息公开工作中侵犯其合法权益；（九）认为行政机关滥用行政权力排除或者限制竞争；（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "procedural", "article_effective_date": "2024-01-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国个人信息保护法', '主席令第91号', '法律', '', '', '2021-08-20', '2021-11-01', '', '现行有效', '', '第13条', '', '符合下列情形之一的，个人信息处理者方可处理个人信息：（一）取得个人的同意；（二）为订立、履行个人作为一方当事人的合同所必需，或者按照依法制定的劳动规章制度和依法签订的集体合同实施人力资源管理所必需；（三）为履行法定职责或者法定义务所必需；（四）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需；（五）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息；（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息；（七）法律、行政法规规定的其他情形。', '全国人民代表大会常务委员会', '数据合规', '特别', 0, '', 0, 1, '', '2021-11-01', 'substantive', '{"law_name": "中华人民共和国个人信息保护法", "document_number": "主席令第91号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2021-08-20", "effective_date": "2021-11-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第13条", "paragraph": "", "content": "符合下列情形之一的，个人信息处理者方可处理个人信息：（一）取得个人的同意；（二）为订立、履行个人作为一方当事人的合同所必需，或者按照依法制定的劳动规章制度和依法签订的集体合同实施人力资源管理所必需；（三）为履行法定职责或者法定义务所必需；（四）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需；（五）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息；（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息；（七）法律、行政法规规定的其他情形。", "source": "全国人民代表大会常务委员会", "category": "数据合规", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "substantive", "article_effective_date": "2021-11-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国个人信息保护法', '主席令第91号', '法律', '', '', '2021-08-20', '2021-11-01', '', '现行有效', '', '第44条', '', '个人对其个人信息的处理享有知情权、决定权，有权限制或者拒绝他人对其个人信息进行处理；法律、行政法规另有规定的除外。', '全国人民代表大会常务委员会', '数据合规', '特别', 0, '', 0, 1, '', '2021-11-01', 'substantive', '{"law_name": "中华人民共和国个人信息保护法", "document_number": "主席令第91号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2021-08-20", "effective_date": "2021-11-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第44条", "paragraph": "", "content": "个人对其个人信息的处理享有知情权、决定权，有权限制或者拒绝他人对其个人信息进行处理；法律、行政法规另有规定的除外。", "source": "全国人民代表大会常务委员会", "category": "数据合规", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "substantive", "article_effective_date": "2021-11-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国合同法', '主席令第15号', '法律', '', '', '1999-03-15', '1999-10-01', '', '已废止', '《中华人民共和国民法典》合同编（2021-01-01 废止）', '第107条', '', '当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。', '全国人民代表大会常务委员会', '合同', '一般', 0, '', 0, 1, '', '1999-10-01', 'substantive', '{"law_name": "中华人民共和国合同法", "document_number": "主席令第15号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "1999-03-15", "effective_date": "1999-10-01", "effective_to": "", "validity": "已废止", "superseded_by": "《中华人民共和国民法典》合同编（2021-01-01 废止）", "article": "第107条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。", "source": "全国人民代表大会常务委员会", "category": "合同", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "norm_type": "substantive", "article_effective_date": "1999-10-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国公司法（2018年修正）', '主席令第15号（2018修正）', '法律', '', '', '2018-10-26', '2018-10-26', '2024-06-30', '已被修订', '《中华人民共和国公司法》（2023年修订，2024-07-01施行）第47条', '第26条', '', '有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额。法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。', '全国人民代表大会常务委员会', '公司', '特别', 0, '', 0, 1, '2023年修订的《公司法》自2024-07-01施行；行为发生日在该日之前的，适用本条。', '2018-10-26', 'substantive', '{"law_name": "中华人民共和国公司法（2018年修正）", "document_number": "主席令第15号（2018修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2018-10-26", "effective_date": "2018-10-26", "effective_to": "2024-06-30", "validity": "已被修订", "superseded_by": "《中华人民共和国公司法》（2023年修订，2024-07-01施行）第47条", "article": "第26条", "paragraph": "", "content": "有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额。法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "2023年修订的《公司法》自2024-07-01施行；行为发生日在该日之前的，适用本条。", "norm_type": "substantive", "article_effective_date": "2018-10-26"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国公司法', '主席令第15号（2023修订）', '法律', '', '', '2023-12-29', '2024-07-01', '', '现行有效', '', '第47条', '', '有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。', '全国人民代表大会常务委员会', '公司', '特别', 0, '', 0, 1, '2023-12-29修订通过、2024-07-01施行；行为发生日早于施行日的不得适用本条（法不溯及既往）。', '2024-07-01', 'substantive', '{"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第47条", "paragraph": "", "content": "有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "2023-12-29修订通过、2024-07-01施行；行为发生日早于施行日的不得适用本条（法不溯及既往）。", "norm_type": "substantive", "article_effective_date": "2024-07-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释', '法释〔2023〕13号', '司法解释', '中华人民共和国民法典', '法律', '2023-12-04', '2023-12-05', '', '现行有效', '', '第65条', '', '当事人主张约定的违约金过分高于违约造成的损失，请求予以适当减少的，人民法院应当以民法典第五百八十四条规定的损失为基础，兼顾合同主体、交易类型、合同的履行情况、当事人的过错程度、履约背景等因素，遵循公平原则和诚信原则进行衡量，并作出裁判。约定的违约金超过造成损失的百分之三十的，人民法院一般可以认定为过分高于造成的损失。恶意违约的当事人一方请求减少违约金的，人民法院一般不予支持。', '最高人民法院', '合同', '', 0, '', 0, 1, '位阶依附于《民法典》（法律+0.5）；原文据最高人民法院公告核实。', '2023-12-05', 'judicial_interpretation', '{"law_name": "最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释", "document_number": "法释〔2023〕13号", "hierarchy": "司法解释", "host_law": "中华人民共和国民法典", "host_hierarchy": "法律", "promulgation_date": "2023-12-04", "effective_date": "2023-12-05", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第65条", "paragraph": "", "content": "当事人主张约定的违约金过分高于违约造成的损失，请求予以适当减少的，人民法院应当以民法典第五百八十四条规定的损失为基础，兼顾合同主体、交易类型、合同的履行情况、当事人的过错程度、履约背景等因素，遵循公平原则和诚信原则进行衡量，并作出裁判。约定的违约金超过造成损失的百分之三十的，人民法院一般可以认定为过分高于造成的损失。恶意违约的当事人一方请求减少违约金的，人民法院一般不予支持。", "source": "最高人民法院", "category": "合同", "scope": "", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "位阶依附于《民法典》（法律+0.5）；原文据最高人民法院公告核实。", "norm_type": "judicial_interpretation", "host_effective_date": "2021-01-01", "article_effective_date": "2023-12-05"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释', '法释〔2023〕13号', '司法解释', '中华人民共和国民法典', '法律', '2023-12-04', '2023-12-05', '', '现行有效', '', '第3条', '', '当事人对合同是否成立存在争议，人民法院能够确定当事人姓名或者名称、标的和数量的，一般应当认定合同成立。但是，法律另有规定或者当事人另有约定的除外。', '最高人民法院', '合同', '', 0, '', 0, 1, '位阶依附于《民法典》；原文据最高人民法院公告核实。', '2023-12-05', 'judicial_interpretation', '{"law_name": "最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释", "document_number": "法释〔2023〕13号", "hierarchy": "司法解释", "host_law": "中华人民共和国民法典", "host_hierarchy": "法律", "promulgation_date": "2023-12-04", "effective_date": "2023-12-05", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第3条", "paragraph": "", "content": "当事人对合同是否成立存在争议，人民法院能够确定当事人姓名或者名称、标的和数量的，一般应当认定合同成立。但是，法律另有规定或者当事人另有约定的除外。", "source": "最高人民法院", "category": "合同", "scope": "", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "位阶依附于《民法典》；原文据最高人民法院公告核实。", "norm_type": "judicial_interpretation", "host_effective_date": "2021-01-01", "article_effective_date": "2023-12-05"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('工资支付暂行规定', '劳部发〔1994〕489号', '部门规章', '', '', '1994-12-06', '1995-01-01', '', '现行有效', '', '第7条', '', '【待核验·示例】工资必须在用人单位与劳动者约定的日期支付。', '劳动部', '劳动', '特别', 0, '', 1, 0, '暂行规定，效力稳定性较低；条文原文须以官方文本核验后方可进入自动对外通道。本条目用于验证部门规章位阶与「地方性法规 vs 部门规章」不可比裁决路径。', '1995-01-01', 'substantive', '{"law_name": "工资支付暂行规定", "document_number": "劳部发〔1994〕489号", "hierarchy": "部门规章", "host_law": "", "host_hierarchy": "", "promulgation_date": "1994-12-06", "effective_date": "1995-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第7条", "paragraph": "", "content": "【待核验·示例】工资必须在用人单位与劳动者约定的日期支付。", "source": "劳动部", "category": "劳动", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": true, "verified": false, "note": "暂行规定，效力稳定性较低；条文原文须以官方文本核验后方可进入自动对外通道。本条目用于验证部门规章位阶与「地方性法规 vs 部门规章」不可比裁决路径。", "norm_type": "substantive", "article_effective_date": "1995-01-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('上海市劳动合同条例', '上海市人大常委会公告（2001）', '地方性法规', '', '', '2001-11-15', '2002-05-01', '', '现行有效', '', '第1条', '', '【待核验·示例】本条例用于验证地方性法规位阶，以及与部门规章冲突时的不可比裁决路径。', '上海市人民代表大会常务委员会', '劳动', '特别', 0, '', 0, 0, '示例条目，正式库接入前须替换为真实条文并经核验。', '2002-05-01', 'substantive', '{"law_name": "上海市劳动合同条例", "document_number": "上海市人大常委会公告（2001）", "hierarchy": "地方性法规", "host_law": "", "host_hierarchy": "", "promulgation_date": "2001-11-15", "effective_date": "2002-05-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第1条", "paragraph": "", "content": "【待核验·示例】本条例用于验证地方性法规位阶，以及与部门规章冲突时的不可比裁决路径。", "source": "上海市人民代表大会常务委员会", "category": "劳动", "scope": "特别", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": false, "note": "示例条目，正式库接入前须替换为真实条文并经核验。", "norm_type": "substantive", "article_effective_date": "2002-05-01"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国民法典', '主席令第45号', '法律', '', '', '2020-05-28', '2021-01-01', '', '现行有效', '', '第985条', '第（一）项', '得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付。', '全国人民代表大会', '民事', '一般', 0, '', 0, 1, '款项级引用演示：不当得利返还的除外情形之一。', '2021-01-01', 'substantive', '{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第985条", "paragraph": "第（一）项", "content": "得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付。", "source": "全国人民代表大会", "category": "民事", "scope": "一般", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "款项级引用演示：不当得利返还的除外情形之一。", "article_effective_date": "2021-01-01", "norm_type": "substantive"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国劳动合同法', '主席令第73号（2012年修正）', '法律', '', '', '2007-06-29', '2013-07-01', '', '现行有效', '', '第46条', '', '有下列情形之一的，用人单位应当向劳动者支付经济补偿：（一）劳动者依照本法第三十八条规定解除劳动合同的；（二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的；（三）用人单位依照本法第四十条规定解除劳动合同的；（四）用人单位依照本法第四十一条第一款规定解除劳动合同的；（五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的。', '全国人民代表大会常务委员会', '劳动', '特别', 0, '', 0, 1, '与第38条（被迫解除）、第47条（经济补偿标准）构成完整引致链。', '2008-01-01', 'substantive', '{"law_name": "中华人民共和国劳动合同法", "document_number": "主席令第73号（2012年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2007-06-29", "effective_date": "2013-07-01", "article_effective_date": "2008-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第46条", "paragraph": "", "content": "有下列情形之一的，用人单位应当向劳动者支付经济补偿：（一）劳动者依照本法第三十八条规定解除劳动合同的；（二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的；（三）用人单位依照本法第四十条规定解除劳动合同的；（四）用人单位依照本法第四十一条第一款规定解除劳动合同的；（五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的。", "source": "全国人民代表大会常务委员会", "category": "劳动", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "与第38条（被迫解除）、第47条（经济补偿标准）构成完整引致链。"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('中华人民共和国劳动争议调解仲裁法', '主席令第80号', '法律', '', '', '2007-12-29', '2008-05-01', '', '现行有效', '', '第27条', '', '劳动争议申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出。', '全国人民代表大会常务委员会', '劳动', '特别', 0, '', 0, 1, '劳动争议仲裁时效核心条文。', '2008-05-01', 'procedural', '{"law_name": "中华人民共和国劳动争议调解仲裁法", "document_number": "主席令第80号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "promulgation_date": "2007-12-29", "effective_date": "2008-05-01", "article_effective_date": "2008-05-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第27条", "paragraph": "", "content": "劳动争议申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出。", "source": "全国人民代表大会常务委员会", "category": "劳动", "scope": "特别", "norm_type": "procedural", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "劳动争议仲裁时效核心条文。"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('最高人民法院关于审理劳动争议案件适用法律问题的解释（一）', '法释〔2020〕26号', '司法解释', '中华人民共和国劳动合同法', '法律', '2020-12-29', '2021-01-01', '', '现行有效', '', '第44条', '', '因用人单位作出的开除、除名、辞退、解除劳动合同、减少劳动报酬、计算劳动者工作年限等决定而发生的劳动争议，用人单位负举证责任。', '最高人民法院', '劳动', '特别', 0, '', 0, 1, '位阶依附于《劳动合同法》（法律+0.5），明确劳动争议举证责任倒置规则。', '2021-01-01', 'judicial_interpretation', '{"law_name": "最高人民法院关于审理劳动争议案件适用法律问题的解释（一）", "document_number": "法释〔2020〕26号", "hierarchy": "司法解释", "host_law": "中华人民共和国劳动合同法", "host_hierarchy": "法律", "host_effective_date": "2008-01-01", "promulgation_date": "2020-12-29", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第44条", "paragraph": "", "content": "因用人单位作出的开除、除名、辞退、解除劳动合同、减少劳动报酬、计算劳动者工作年限等决定而发生的劳动争议，用人单位负举证责任。", "source": "最高人民法院", "category": "劳动", "scope": "特别", "norm_type": "judicial_interpretation", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "位阶依附于《劳动合同法》（法律+0.5），明确劳动争议举证责任倒置规则。"}', '2026-11-07T08:31:27.548681+00:00');
INSERT INTO sample_laws (law_name, document_number, hierarchy, host_law, host_hierarchy, promulgation_date, effective_date, effective_to, validity, superseded_by, article, paragraph, content, source, category, scope, partially_invalid, invalid_parts, trial, verified, note, article_effective_date, norm_type, metadata_json, created_at) VALUES ('最高人民法院关于适用《中华人民共和国民法典》时间效力的若干规定', '法释〔2020〕15号', '司法解释', '中华人民共和国民法典', '法律', '2020-12-29', '2021-01-01', '', '现行有效', '', '第1条', '', '民法典施行后的法律事实引起的民事纠纷案件，适用民法典的规定。民法典施行前的法律事实引起的民事纠纷案件，适用当时的法律、司法解释的规定，但是法律、司法解释另有规定的除外。民法典施行前产生的民事关系，持续至民法典施行后，该民事关系产生的民事纠纷案件，适用民法典的规定，但是法律、司法解释另有规定的除外。', '最高人民法院', '民事', '一般', 0, '', 0, 1, '明确法不溯及既往原则与持续性法律事实跨法从新规则。', '2021-01-01', 'judicial_interpretation', '{"law_name": "最高人民法院关于适用《中华人民共和国民法典》时间效力的若干规定", "document_number": "法释〔2020〕15号", "hierarchy": "司法解释", "host_law": "中华人民共和国民法典", "host_hierarchy": "法律", "host_effective_date": "2021-01-01", "promulgation_date": "2020-12-29", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第1条", "paragraph": "", "content": "民法典施行后的法律事实引起的民事纠纷案件，适用民法典的规定。民法典施行前的法律事实引起的民事纠纷案件，适用当时的法律、司法解释的规定，但是法律、司法解释另有规定的除外。民法典施行前产生的民事关系，持续至民法典施行后，该民事关系产生的民事纠纷案件，适用民法典的规定，但是法律、司法解释另有规定的除外。", "source": "最高人民法院", "category": "民事", "scope": "一般", "norm_type": "judicial_interpretation", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "明确法不溯及既往原则与持续性法律事实跨法从新规则。"}', '2026-11-07T08:31:27.548681+00:00');
