REPLACE INTO session_snapshots (thread_id, updated_at, status, query, act_date, region, confidence, review_level, state_json) VALUES ('9abef7c5-1f93-4ccd-be15-98e162c9b2cb', '2026-11-03T15:24:54.359538+00:00', 'needs_review', '对方不履行合同义务，我可以要求继续履行并赔偿损失吗？', '2026-11-03', '', 'B', 'must', '{"query": "对方不履行合同义务，我可以要求继续履行并赔偿损失吗？", "act_date": "2026-11-03", "region": "", "answer_confidence": "B", "rule_plan": {"mode": "llm_assisted", "confidence": "B", "review": "must", "llm_callable": true, "prompt_constraints": ["只能引用给定候选条文；不得生成任何未出现的条文号、法规名称或文号", "禁止使用“必然/一定/肯定/应当”等确定性表述；改用“在……前提下/倾向于/需进一步确认”", "必须显式说明：规则未覆盖的具体原因、不确定性来源、以及结论成立所需的前提", "必须给出至少一项建议核实或补证事项（如行为发生日期、制定机关、事实细节）", "本结论标记为兜底结果，不得进入自动对外通道，必须经人工审核后方可使用"], "verify_actions": ["向当事人核实法律事实发生的具体日期（或持续起止期间）", "法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）", "确认合同成立/生效时间及约定的履行期限（决定适用《民法典》还是旧《合同法》）"], "reason": "当事人未提供法律事实发生日期，暂按当前日期（2026-11-03）定位现行有效法；若系历史纠纷，适用依据可能不同；行为发生日 2026-11-03 不早于施行日 2021-01-01，且该条现行有效；《中华人民共和国行政复议法》第11条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-03）适用现行有效规定；行为发生日 2026-11-03 不早于施行日 2021-07-15，且该条现行有效；行为发生日 2026-11-03 不早于施行日 2023-12-05，且该条现行有效"}, "final_output": {"citations": [{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第577条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］", "score": 80.4806, "rerank_score": 0.2543, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第584条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 62.3483, "rerank_score": 0.1443, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第985条", "paragraph": "", "content": "得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付；（二）债务到期之前的清偿；（三）明知无给付义务而进行的债务清偿。", "source": "全国人民代表大会", "category": "民事", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 28.4974, "rerank_score": 0.1268, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第985条", "paragraph": "第（一）项", "content": "得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付。", "source": "全国人民代表大会", "category": "民事", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "款项级引用演示：不当得利返还的除外情形之一。", "score": 29.1108, "rerank_score": 0.1153, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第563条", "paragraph": "", "content": "有下列情形之一的，当事人可以解除合同：（一）因不可抗力致使不能实现合同目的；（二）在履行期限届满前，当事人一方明确表示或者以自己的行为表明不履行主要债务；（三）当事人一方迟延履行主要债务，经催告后在合理期限内仍未履行；（四）当事人一方迟延履行债务或者有其他违约行为致使不能实现合同目的；（五）法律规定的其他情形。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 34.2756, "rerank_score": 0.0996, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国行政复议法", "document_number": "主席令第9号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1999-04-29", "effective_date": "2024-01-01", "article_effective_date": "2024-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第11条", "paragraph": "", "content": "有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；（二）对行政机关作出的行政强制措施、行政强制执行决定不服；（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；（四）对行政机关作出的征收征用决定及其补偿决定不服；（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；（八）认为行政机关在政府信息公开工作中侵犯其合法权益；（九）认为行政机关滥用行政权力排除或者限制竞争；（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "norm_type": "procedural", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 26.387, "rerank_score": 0.0589, "applicable_at": true, "applicable_note": "适用：程序法遵循「程序从新」原则，适用现行有效程序规定"}, {"law_name": "中华人民共和国行政处罚法", "document_number": "主席令第70号（2021年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1996-03-17", "effective_date": "2021-07-15", "article_effective_date": "2021-07-15", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第33条", "paragraph": "", "content": "违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "norm_type": "administrative_penalty", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 23.5322, "rerank_score": 0.0442, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释", "document_number": "法释〔2023〕13号", "hierarchy": "司法解释", "host_law": "中华人民共和国民法典", "host_hierarchy": "法律", "host_effective_date": "2021-01-01", "promulgation_date": "2023-12-04", "effective_date": "2023-12-05", "article_effective_date": "2023-12-05", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第65条", "paragraph": "", "content": "当事人主张约定的违约金过分高于违约造成的损失，请求予以适当减少的，人民法院应当以民法典第五百八十四条规定的损失为基础，兼顾合同主体、交易类型、合同的履行情况、当事人的过错程度、履约背景等因素，遵循公平原则和诚信原则进行衡量，并作出裁判。约定的违约金超过造成损失的百分之三十的，人民法院一般可以认定为过分高于造成的损失。恶意违约的当事人一方请求减少违约金的，人民法院一般不予支持。", "source": "最高人民法院", "category": "合同", "scope": "", "norm_type": "judicial_interpretation", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "位阶依附于《民法典》（法律+0.5）；原文据最高人民法院公告核实。", "score": 23.6199, "rerank_score": 0.0747, "applicable_at": true, "applicable_note": "适用：现行有效"}], "answer": "【一、争议焦点与事实前提】\\n· 时间前提声明：因未提供具体法律事实发生时间，本意见在**假设争议事实发生于现行法有效期内（暂以 2026-11-03 为基准日）**的前提下推演；若事实发生在旧法期间，须按行为时旧法重新定位。\\n· 争议焦点 1：对方不履行合同义务，我可以要求继续履行并赔偿损失吗\\n\\n【二、适用法规与效力要旨（大前提）】\\n· 《中华人民共和国民法典》第577条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。\\n  ↳ 效力说明：适用：现行有效\\n  ↳ 关联说明：［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］\\n· 《中华人民共和国民法典》第584条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国民法典》第985条（法律·现行有效）：得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付；（二）债务到期之前的清偿；（三）明知无给付义务而进行的债务清偿。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国民法典》第985条第（一）项（法律·现行有效）：得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国民法典》第563条（法律·现行有效）：有下列情形之一的，当事人可以解除合同：（一）因不可抗力致使不能实现合同目的；（二）在履行期限届满前，当事人一方明确表示或者以自己的行为表明不履行主要债务；（三）当事人一方迟延履行主要债务，经催告后在合理期限内仍未履行；（四）当事人一方迟延履行债务或者有其他违约行为致使不能实现合同目的；（五）法律规定的其他情形。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国行政复议法》第11条（法律·现行有效）：有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；（二）对行政机关作出的行政强制措施、行政强制执行决定不服；（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；（四）对行政机关作出的征收征用决定及其补偿决定不服；（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；（八）认为行政机关在政府信息公开工作中侵犯其合法权益；（九）认为行政机关滥用行政权力排除或者限制竞争；（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。\\n  ↳ 效力说明：适用：程序法遵循「程序从新」原则，适用现行有效程序规定\\n· 《中华人民共和国行政处罚法》第33条（法律·现行有效）：违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。\\n  ↳ 效力说明：适用：现行有效\\n· 《最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释》第65条（司法解释·现行有效）：当事人主张约定的违约金过分高于违约造成的损失，请求予以适当减少的，人民法院应当以民法典第五百八十四条规定的损失为基础，兼顾合同主体、交易类型、合同的履行情况、当事人的过错程度、履约背景等因素，遵循公平原则和诚信原则进行衡量，并作出裁判。约定的违约金超过造成损失的百分之三十的，人民法院一般可以认定为过分高于造成的损失。恶意违约的当事人一方请求减少违约金的，人民法院一般不予支持。\\n  ↳ 效力说明：适用：现行有效\\n\\n【规范竞合与法理涵摄推演要求（法律适用关系未配置时的兜底约束）】\\n- 法律解释学涵摄：若涉及跨部门法或多部法律规范竞合且无绝对位阶排他，须严格遵循法律解释学（文义解释、体系解释、立法目的解释），将案件具体事实逐项对应代入规范要件进行涵摄推演；\\n- 审慎抗辩与双向争议提示：明确向用户披露潜在的法律适用分歧点与司法裁决倾向，禁止给出单向绝对化胜诉承诺，提供审慎的诉辩应对策略。\\n\\n【三、涵摄分析与初步结论（小前提推演）】\\n在现有候选依据范围内，结合《中华人民共和国民法典》第577条、《中华人民共和国民法典》第584条、《中华人民共和国民法典》第985条、《中华人民共和国民法典》第985条第（一）项、《中华人民共和国民法典》第563条之规定，倾向于按上述条文界定的构成要件与法律后果处理；但鉴于部分事实要件或时空要素尚待核实，上述结论成立需以下列「待核实关键事实」属实为前提，需进一步确认后方可定论。\\n\\n【四、待核实关键事实与补证建议】\\n- 法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）\\n- 确认合同成立/生效时间及约定的履行期限（决定适用《民法典》还是旧《合同法》）\\n\\n【五、诉讼/仲裁时效与程序路径提示】\\n- 【诉讼时效】依《民法典》第188条，向人民法院请求保护民事权利的普通诉讼时效期间为 3 年，自知道或者应当知道权利受到损害以及义务人之日起计算。\\n- 【除斥期间】若主张受欺诈/胁迫请求撤销合同（《民法典》第148条、第152条），应当自知道或者应当知道撤销事由之日起 1 年内行使撤销权（该期间为除斥期间，不适用中止、中断）。\\n- 【违约金调整】依《民法典合同编通则解释》第65条，约定违约金超过造成损失 30% 的，一般可认定为「过分高于造成的损失」，违约方（恶意违约除外）可请求法院或仲裁机构予以适当减少。\\n\\n（受限兜底模式：本结论包含待确认前提，不得进入自动对外通道，必须经执业律师人工审核后方可使用）", "sentence_traces": [{"sentence_idx": 4, "sentence_text": "· 争议焦点 1：对方不履行合同义务，我可以要求继续履行并赔偿损失吗", "matched_law": "中华人民共和国民法典", "matched_article": "第577条", "confidence_score": 0.1445, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 6, "sentence_text": "· 《中华人民共和国民法典》第577条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。", "matched_law": "中华人民共和国民法典", "matched_article": "第577条", "confidence_score": 1.0, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任", "trace_source": "explicit_anchor"}, {"sentence_idx": 8, "sentence_text": "↳ 关联说明：［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］", "matched_law": "中华人民共和国民法典", "matched_article": "第577条", "confidence_score": 0.3707, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任", "trace_source": "explicit_anchor"}, {"sentence_idx": 9, "sentence_text": "· 《中华人民共和国民法典》第584条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 1.0, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 10, "sentence_text": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 1.0, "highlight_snippet": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失", "trace_source": "ngram_overlap"}, {"sentence_idx": 12, "sentence_text": "· 《中华人民共和国民法典》第985条（法律·现行有效）：得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付；", "matched_law": "中华人民共和国民法典", "matched_article": "第985条", "confidence_score": 1.0, "highlight_snippet": "得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付", "trace_source": "explicit_anchor"}, {"sentence_idx": 13, "sentence_text": "（二）债务到期之前的清偿；", "matched_law": "中华人民共和国民法典", "matched_article": "第985条", "confidence_score": 1.0, "highlight_snippet": "（二）债务到期之前的清偿", "trace_source": "ngram_overlap"}, {"sentence_idx": 14, "sentence_text": "（三）明知无给付义务而进行的债务清偿。", "matched_law": "中华人民共和国民法典", "matched_article": "第985条", "confidence_score": 1.0, "highlight_snippet": "（三）明知无给付义务而进行的债务清偿", "trace_source": "ngram_overlap"}, {"sentence_idx": 16, "sentence_text": "· 《中华人民共和国民法典》第985条第（一）项（法律·现行有效）：得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付。", "matched_law": "中华人民共和国民法典", "matched_article": "第985条", "confidence_score": 1.0, "highlight_snippet": "得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付", "trace_source": "explicit_anchor"}, {"sentence_idx": 18, "sentence_text": "· 《中华人民共和国民法典》第563条（法律·现行有效）：有下列情形之一的，当事人可以解除合同：（一）因不可抗力致使不能实现合同目的；", "matched_law": "中华人民共和国民法典", "matched_article": "第563条", "confidence_score": 1.0, "highlight_snippet": "有下列情形之一的，当事人可以解除合同：（一）因不可抗力致使不能实现合同目的", "trace_source": "explicit_anchor"}, {"sentence_idx": 19, "sentence_text": "（二）在履行期限届满前，当事人一方明确表示或者以自己的行为表明不履行主要债务；", "matched_law": "中华人民共和国民法典", "matched_article": "第563条", "confidence_score": 1.0, "highlight_snippet": "（二）在履行期限届满前，当事人一方明确表示或者以自己的行为表明不履行主要债务", "trace_source": "ngram_overlap"}, {"sentence_idx": 20, "sentence_text": "（三）当事人一方迟延履行主要债务，经催告后在合理期限内仍未履行；", "matched_law": "中华人民共和国民法典", "matched_article": "第563条", "confidence_score": 1.0, "highlight_snippet": "（三）当事人一方迟延履行主要债务，经催告后在合理期限内仍未履行", "trace_source": "ngram_overlap"}, {"sentence_idx": 21, "sentence_text": "（四）当事人一方迟延履行债务或者有其他违约行为致使不能实现合同目的；", "matched_law": "中华人民共和国民法典", "matched_article": "第563条", "confidence_score": 1.0, "highlight_snippet": "（四）当事人一方迟延履行债务或者有其他违约行为致使不能实现合同目的", "trace_source": "ngram_overlap"}, {"sentence_idx": 22, "sentence_text": "（五）法律规定的其他情形。", "matched_law": "中华人民共和国民法典", "matched_article": "第563条", "confidence_score": 1.0, "highlight_snippet": "（五）法律规定的其他情形", "trace_source": "ngram_overlap"}, {"sentence_idx": 24, "sentence_text": "· 《中华人民共和国行政复议法》第11条（法律·现行有效）：有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服", "trace_source": "explicit_anchor"}, {"sentence_idx": 25, "sentence_text": "（二）对行政机关作出的行政强制措施、行政强制执行决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（二）对行政机关作出的行政强制措施、行政强制执行决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 26, "sentence_text": "（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 27, "sentence_text": "（四）对行政机关作出的征收征用决定及其补偿决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（四）对行政机关作出的征收征用决定及其补偿决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 28, "sentence_text": "（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（五）对行政机关作出的赔偿决定或者不予赔偿决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 29, "sentence_text": "（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 30, "sentence_text": "（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议", "trace_source": "ngram_overlap"}, {"sentence_idx": 31, "sentence_text": "（八）认为行政机关在政府信息公开工作中侵犯其合法权益；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（八）认为行政机关在政府信息公开工作中侵犯其合法权益", "trace_source": "ngram_overlap"}, {"sentence_idx": 32, "sentence_text": "（九）认为行政机关滥用行政权力排除或者限制竞争；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（九）认为行政机关滥用行政权力排除或者限制竞争", "trace_source": "ngram_overlap"}, {"sentence_idx": 33, "sentence_text": "（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务", "trace_source": "ngram_overlap"}, {"sentence_idx": 34, "sentence_text": "（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复", "trace_source": "ngram_overlap"}, {"sentence_idx": 35, "sentence_text": "（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付", "trace_source": "ngram_overlap"}, {"sentence_idx": 36, "sentence_text": "（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议", "trace_source": "ngram_overlap"}, {"sentence_idx": 37, "sentence_text": "（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权", "trace_source": "ngram_overlap"}, {"sentence_idx": 38, "sentence_text": "（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十五）认为行政机关侵犯其他人身权、财产权等合法权益的", "trace_source": "ngram_overlap"}, {"sentence_idx": 40, "sentence_text": "· 《中华人民共和国行政处罚法》第33条（法律·现行有效）：违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚", "trace_source": "explicit_anchor"}, {"sentence_idx": 41, "sentence_text": "初次违法且危害后果轻微并及时改正的，可以不予行政处罚。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "初次违法且危害后果轻微并及时改正的，可以不予行政处罚", "trace_source": "ngram_overlap"}, {"sentence_idx": 42, "sentence_text": "当事人有证据足以证明没有主观过错的，不予行政处罚。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "当事人有证据足以证明没有主观过错的，不予行政处罚", "trace_source": "ngram_overlap"}, {"sentence_idx": 43, "sentence_text": "法律、行政法规另有规定的，从其规定。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "法律、行政法规另有规定的，从其规定", "trace_source": "ngram_overlap"}, {"sentence_idx": 44, "sentence_text": "对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育", "trace_source": "ngram_overlap"}, {"sentence_idx": 46, "sentence_text": "· 《最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释》第65条（司法解释·现行有效）：当事人主张约定的违约金过分高于违约造成的损失，请求予以适当减少的，人民法院应当以民法典第五百八十四条规定的损失为基础，兼顾合同主体、交易类型、合同的履行情况、当事人的过错程度、履约背景等因素，遵循公平原则和诚信原则进行衡量，并作出裁判。", "matched_law": "最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释", "matched_article": "第65条", "confidence_score": 1.0, "highlight_snippet": "当事人主张约定的违约金过分高于违约造成的损失，请求予以适当减少的，人民法院应当以民法典第五百八十四条规定的损失为基础，兼顾合同主体、交易类型、合同的履行情况、当事人的过错程度、履约背景等因素，遵循公平原则和诚信原则进行衡量，并作出裁判", "trace_source": "explicit_anchor"}, {"sentence_idx": 47, "sentence_text": "约定的违约金超过造成损失的百分之三十的，人民法院一般可以认定为过分高于造成的损失。", "matched_law": "最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释", "matched_article": "第65条", "confidence_score": 1.0, "highlight_snippet": "约定的违约金超过造成损失的百分之三十的，人民法院一般可以认定为过分高于造成的损失", "trace_source": "ngram_overlap"}, {"sentence_idx": 48, "sentence_text": "恶意违约的当事人一方请求减少违约金的，人民法院一般不予支持。", "matched_law": "最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释", "matched_article": "第65条", "confidence_score": 1.0, "highlight_snippet": "恶意违约的当事人一方请求减少违约金的，人民法院一般不予支持", "trace_source": "ngram_overlap"}, {"sentence_idx": 54, "sentence_text": "在现有候选依据范围内，结合《中华人民共和国民法典》第577条、《中华人民共和国民法典》第584条、《中华人民共和国民法典》第985条、《中华人民共和国民法典》第985条第（一）项、《中华人民共和国民法典》第563条之规定，倾向于按上述条文界定的构成要件与法律后果处理；", "matched_law": "中华人民共和国民法典", "matched_article": "第563条", "confidence_score": 0.3583, "highlight_snippet": "（五）法律规定的其他情形", "trace_source": "explicit_anchor"}, {"sentence_idx": 58, "sentence_text": "- 确认合同成立/生效时间及约定的履行期限（决定适用《民法典》还是旧《合同法》）", "matched_law": "中华人民共和国民法典", "matched_article": "第563条", "confidence_score": 0.3786, "highlight_snippet": "（二）在履行期限届满前，当事人一方明确表示或者以自己的行为表明不履行主要债务", "trace_source": "explicit_anchor"}, {"sentence_idx": 60, "sentence_text": "- 【诉讼时效】依《民法典》第188条，向人民法院请求保护民事权利的普通诉讼时效期间为 3 年，自知道或者应当知道权利受到损害以及义务人之日起计算。", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 0.3692, "highlight_snippet": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失", "trace_source": "explicit_anchor"}, {"sentence_idx": 61, "sentence_text": "- 【除斥期间】若主张受欺诈/胁迫请求撤销合同（《民法典》第148条、第152条），应当自知道或者应当知道撤销事由之日起 1 年内行使撤销权（该期间为除斥期间，不适用中止、中断）。", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 0.3699, "highlight_snippet": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失", "trace_source": "explicit_anchor"}, {"sentence_idx": 62, "sentence_text": "- 【违约金调整】依《民法典合同编通则解释》第65条，约定违约金超过造成损失 30% 的，一般可认定为「过分高于造成的损失」，违约方（恶意违约除外）可请求法院或仲裁机构予以适当减少。", "matched_law": "最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释", "matched_article": "第65条", "confidence_score": 0.5458, "highlight_snippet": "约定的违约金超过造成损失的百分之三十的，人民法院一般可以认定为过分高于造成的损失", "trace_source": "explicit_anchor"}], "structured_queries": {"focus": ["对方不履行合 同义务 我可以要求继 构成要件 适用规定"], "exception": ["对方不履行合 同义务 我可以要求继 除外情形 免责事由 不适用", "对方不履行合 同义务 我可以要求继 禁止性规定 排除适用"], "consequence": ["对方不履行合 同义务 我可以要求继 法律后果 法律责任 效力认定", "对方不履行合 同义务 我可以要求继 违约损害赔偿 追偿与补救措施"]}, "missing_facts": ["法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）", "确认合同成立/生效时间及约定的履行期限（决定适用《民法典》还是旧《合同法》）"], "clarification_questions": ["请问该争议事实发生的具体时间（或持续起止期间）是什么时候？", "请补充说明：确认合同成立/生效时间及约定的履行期限（决定适用《民法典》还是旧《合同法》）？"], "procedural_notes": ["【诉讼时效】依《民法典》第188条，向人民法院请求保护民事权利的普通诉讼时效期间为 3 年，自知道或者应当知道权利受到损害以及义务人之日起计算。", "【除斥期间】若主张受欺诈/胁迫请求撤销合同（《民法典》第148条、第152条），应当自知道或者应当知道撤销事由之日起 1 年内行使撤销权（该期间为除斥期间，不适用中止、中断）。", "【违约金调整】依《民法典合同编通则解释》第65条，约定违约金超过造成损失 30% 的，一般可认定为「过分高于造成的损失」，违约方（恶意违约除外）可请求法院或仲裁机构予以适当减少。"], "suggested_citations": [], "disclaimer": "［生成式人工智能辅助生成｜算法备案与可追溯标识］ 本回答由 AI 基于检索法规自动推演生成（当前置信度：B），尚未完成执业律师终审签名，不构成正式法律意见书，仅供法律检索参考。"}, "fact_summary": {"act_date": "2026-11-03", "act_end_date": "", "act_date_source": "assumed_today", "date_granularity": "none", "is_continuous": false, "region": "", "case_types": ["合同"], "extracted_facts": ["[民商事合同纠纷] 已提及「违约具体情形与催告情况」相关线索", "[民商事合同纠纷] 已提及「损失金额与违约金约定」相关线索"], "missing_facts": ["法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）", "确认合同成立/生效时间及约定的履行期限（决定适用《民法典》还是旧《合同法》）"], "clarification_questions": ["请问该争议事实发生的具体时间（或持续起止期间）是什么时候？", "请补充说明：确认合同成立/生效时间及约定的履行期限（决定适用《民法典》还是旧《合同法》）？"], "procedural_notes": ["【诉讼时效】依《民法典》第188条，向人民法院请求保护民事权利的普通诉讼时效期间为 3 年，自知道或者应当知道权利受到损害以及义务人之日起计算。", "【除斥期间】若主张受欺诈/胁迫请求撤销合同（《民法典》第148条、第152条），应当自知道或者应当知道撤销事由之日起 1 年内行使撤销权（该期间为除斥期间，不适用中止、中断）。", "【违约金调整】依《民法典合同编通则解释》第65条，约定违约金超过造成损失 30% 的，一般可认定为「过分高于造成的损失」，违约方（恶意违约除外）可请求法院或仲裁机构予以适当减少。"], "suggested_citations": [], "dynamic_proposal": null}, "compliance_info": {"pii_masked": false, "pii_types": [], "has_conflict": false, "entities": [], "conflicts": []}, "rule_notes": ["事实前提：未提供法律事实发生日，暂按 2026-11-03 现行有效法推演（已降级为 B 级置信度/人工必审）。", "版本定位：《中华人民共和国合同法》MISS — 行为发生日落在版本空档期（旧版已失效、新版未生效），适用依据不明", "版本定位：《中华人民共和国民法典》依 2026-11-03 适用 2021-01-01。", "版本定位：《中华人民共和国行政处罚法》依 2026-11-03 适用 2021-07-15。", "版本定位：《中华人民共和国行政复议法》依 2026-11-03 适用 2024-01-01。", "版本定位：《最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释》依 2026-11-03 适用 2023-12-05。", "时间效力：《中华人民共和国合同法》第107条 — 《中华人民共和国合同法》第107条已于 2020-12-31 失效，行为发生日 2026-11-03 在其失效之后，不适用，已排除。", "效力过滤：已排除 1 条在 2026-11-03（或当前地域）不适用的条文。", "规则汇总：PARTIAL｜mode=llm_assisted｜置信度=B｜人审=must"], "human_approved": false}');
REPLACE INTO session_snapshots (thread_id, updated_at, status, query, act_date, region, confidence, review_level, state_json) VALUES ('348184b8-b5a1-4b6e-b34e-0b7183074c10', '2026-11-04T02:31:46.912994+00:00', 'needs_review', '客户通过手机银行购买高风险理财产品需要做哪些额外测试', '2026-11-04', '', 'B', 'must', '{"query": "客户通过手机银行购买高风险理财产品需要做哪些额外测试", "act_date": "2026-11-04", "region": "", "answer_confidence": "B", "rule_plan": {"mode": "llm_assisted", "confidence": "B", "review": "must", "llm_callable": true, "prompt_constraints": ["只能引用给定候选条文；不得生成任何未出现的条文号、法规名称或文号", "禁止使用“必然/一定/肯定/应当”等确定性表述；改用“在……前提下/倾向于/需进一步确认”", "必须显式说明：规则未覆盖的具体原因、不确定性来源、以及结论成立所需的前提", "必须给出至少一项建议核实或补证事项（如行为发生日期、制定机关、事实细节）", "本结论标记为兜底结果，不得进入自动对外通道，必须经人工审核后方可使用"], "verify_actions": ["向当事人核实法律事实发生的具体日期（或持续起止期间）", "法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）", "确认争议双方的身份关系与法律关系性质凭证", "确认相对人实施违法、违约或损害行为的具体表现与举证凭证"], "reason": "当事人未提供法律事实发生日期，暂按当前日期（2026-11-04）定位现行有效法；若系历史纠纷，适用依据可能不同；行为发生日 2026-11-04 不早于施行日 2021-11-01，且该条现行有效；行为发生日 2026-11-04 不早于施行日 2021-07-15，且该条现行有效；《中华人民共和国行政诉讼法》第12条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-04）适用现行有效规定；行为发生日 2026-11-04 不早于施行日 2021-01-01，且该条现行有效；行为发生日 2026-11-04 不早于施行日 2014-03-15，且该条现行有效；行为发生日 2026-11-04 不早于施行日 2008-05-01，且该条现行有效；行为发生日 2026-11-04 不早于施行日 2024-07-01，且该条现行有效；《中华人民共和国民事诉讼法》第67条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-04）适用现行有效规定；《中华人民共和国行政复议法》第11条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-04）适用现行有效规定"}, "final_output": {"citations": [{"law_name": "中华人民共和国个人信息保护法", "document_number": "主席令第91号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2021-08-20", "effective_date": "2021-11-01", "article_effective_date": "2021-11-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第13条", "paragraph": "", "content": "符合下列情形之一的，个人信息处理者方可处理个人信息：（一）取得个人的同意；（二）为订立、履行个人作为一方当事人的合同所必需，或者按照依法制定的劳动规章制度和依法签订的集体合同实施人力资源管理所必需；（三）为履行法定职责或者法定义务所必需；（四）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需；（五）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息；（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息；（七）法律、行政法规规定的其他情形。", "source": "全国人民代表大会常务委员会", "category": "数据合规", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 19.1609, "rerank_score": 0.049, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国行政处罚法", "document_number": "主席令第70号（2021年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1996-03-17", "effective_date": "2021-07-15", "article_effective_date": "2021-07-15", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第33条", "paragraph": "", "content": "违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "norm_type": "administrative_penalty", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 20.4364, "rerank_score": 0.0489, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国行政诉讼法", "document_number": "主席令第71号（2017年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1989-04-04", "effective_date": "2017-07-01", "article_effective_date": "2015-05-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第12条", "paragraph": "", "content": "人民法院受理公民、法人或者其他组织提起的下列诉讼：（一）对行政拘留、罚款、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、警告等行政处罚不服的；（二）对限制人身自由或者对财产的查封、扣押、冻结等行政强制措施和行政强制执行不服的；（三）申请行政许可，行政机关拒绝或者在法定期限内不予答复，或者对行政机关作出的有关行政许可的其他决定不服的；（四）对行政机关作出的关于确认土地、矿藏、水流、森林、山岭、草原、荒地、滩涂、海域等自然资源的所有权或者使用权的决定不服的；（五）对征收、征用决定及其补偿决定不服的；（六）申请行政机关履行保护人身权、财产权等合法权益的法定职责，行政机关拒绝履行或者不予答复的；（七）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权的；（八）认为行政机关滥用行政权力排除或者限制竞争的；（九）认为行政机关违法集资、摊派费用或者违法要求履行其他义务的；（十）认为行政机关没有依法支付抚恤金、最低生活保障待遇或者社会保险待遇的；（十一）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议的；（十二）认为行政机关侵犯其他人身权、财产权等合法权益的。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "norm_type": "procedural", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 17.6077, "rerank_score": 0.0442, "applicable_at": true, "applicable_note": "适用：程序法遵循「程序从新」原则，适用现行有效程序规定"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第584条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "［引致关联：第584条进一步明确违约损失赔偿额的范围（含可得利益）与可预见规则］", "score": 33.529, "rerank_score": 0.0337, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国消费者权益保护法", "document_number": "主席令第7号（2013年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1993-10-31", "effective_date": "2014-03-15", "article_effective_date": "2014-03-15", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第55条", "paragraph": "", "content": "经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。", "source": "全国人民代表大会常务委员会", "category": "消费", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 28.1293, "rerank_score": 0.0255, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国道路交通安全法", "document_number": "主席令第47号（2011年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2003-10-28", "effective_date": "2011-05-01", "article_effective_date": "2008-05-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第76条", "paragraph": "", "content": "机动车发生交通事故造成人身伤亡、财产损失的，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿；不足的部分，机动车之间发生交通事故的，由有过错的一方承担赔偿责任；双方都有过错的，按照各自过错的比例分担责任。机动车与非机动车驾驶人、行人之间发生交通事故，非机动车驾驶人、行人没有过错的，由机动车一方承担赔偿责任；有证据证明非机动车驾驶人、行人有过错的，根据过错程度适当减轻机动车一方的赔偿责任；机动车一方没有过错的，承担不超过百分之十的赔偿责任。", "source": "全国人民代表大会常务委员会", "category": "交通", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 30.4052, "rerank_score": 0.0245, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "article_effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第3条", "paragraph": "", "content": "公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。有限责任公司的股东以其认缴的出资额为限对公司承担责任；股份有限公司的股东以其认购的股份为限对公司承担责任。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 23.9438, "rerank_score": 0.0234, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民事诉讼法", "document_number": "主席令第106号（2021年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1991-04-09", "effective_date": "2022-01-01", "article_effective_date": "1991-04-09", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第67条", "paragraph": "", "content": "当事人对自己提出的主张，有责任提供证据。当事人及其诉讼代理人因客观原因不能自行收集的证据，或者人民法院认为审理案件需要的证据，人民法院应当调查收集。人民法院应当按照法定程序，全面地、客观地审查核实证据。", "source": "全国人民代表大会常务委员会", "category": "诉讼", "scope": "一般", "norm_type": "procedural", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 16.4477, "rerank_score": 0.0226, "applicable_at": true, "applicable_note": "适用：程序法遵循「程序从新」原则，适用现行有效程序规定"}, {"law_name": "中华人民共和国行政复议法", "document_number": "主席令第9号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1999-04-29", "effective_date": "2024-01-01", "article_effective_date": "2024-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第11条", "paragraph": "", "content": "有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；（二）对行政机关作出的行政强制措施、行政强制执行决定不服；（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；（四）对行政机关作出的征收征用决定及其补偿决定不服；（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；（八）认为行政机关在政府信息公开工作中侵犯其合法权益；（九）认为行政机关滥用行政权力排除或者限制竞争；（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "norm_type": "procedural", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 22.5653, "rerank_score": 0.0217, "applicable_at": true, "applicable_note": "适用：程序法遵循「程序从新」原则，适用现行有效程序规定"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第577条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］", "score": 39.4459, "rerank_score": 0.0193, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "最高人民法院关于审理劳动争议案件适用法律问题的解释（一）", "document_number": "法释〔2020〕26号", "hierarchy": "司法解释", "host_law": "中华人民共和国劳动合同法", "host_hierarchy": "法律", "host_effective_date": "2008-01-01", "promulgation_date": "2020-12-29", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第44条", "paragraph": "", "content": "因用人单位作出的开除、除名、辞退、解除劳动合同、减少劳动报酬、计算劳动者工作年限等决定而发生的劳动争议，用人单位负举证责任。", "source": "最高人民法院", "category": "劳动", "scope": "特别", "norm_type": "judicial_interpretation", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "位阶依附于《劳动合同法》（法律+0.5），明确劳动争议举证责任倒置规则。", "score": 16.588, "rerank_score": 0.0381, "applicable_at": true, "applicable_note": "适用：现行有效"}], "answer": "【一、争议焦点与事实前提】\\n· 时间前提声明：因未提供具体法律事实发生时间，本意见在**假设争议事实发生于现行法有效期内（暂以 2026-11-04 为基准日）**的前提下推演；若事实发生在旧法期间，须按行为时旧法重新定位。\\n· 争议焦点 1：客户通过手机银行购买高风险理财产品需要做哪些额外测试\\n\\n【二、适用法规与效力要旨（大前提）】\\n· 《中华人民共和国个人信息保护法》第13条（法律·现行有效）：符合下列情形之一的，个人信息处理者方可处理个人信息：（一）取得个人的同意；（二）为订立、履行个人作为一方当事人的合同所必需，或者按照依法制定的劳动规章制度和依法签订的集体合同实施人力资源管理所必需；（三）为履行法定职责或者法定义务所必需；（四）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需；（五）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息；（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息；（七）法律、行政法规规定的其他情形。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国行政处罚法》第33条（法律·现行有效）：违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国行政诉讼法》第12条（法律·现行有效）：人民法院受理公民、法人或者其他组织提起的下列诉讼：（一）对行政拘留、罚款、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、警告等行政处罚不服的；（二）对限制人身自由或者对财产的查封、扣押、冻结等行政强制措施和行政强制执行不服的；（三）申请行政许可，行政机关拒绝或者在法定期限内不予答复，或者对行政机关作出的有关行政许可的其他决定不服的；（四）对行政机关作出的关于确认土地、矿藏、水流、森林、山岭、草原、荒地、滩涂、海域等自然资源的所有权或者使用权的决定不服的；（五）对征收、征用决定及其补偿决定不服的；（六）申请行政机关履行保护人身权、财产权等合法权益的法定职责，行政机关拒绝履行或者不予答复的；（七）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权的；（八）认为行政机关滥用行政权力排除或者限制竞争的；（九）认为行政机关违法集资、摊派费用或者违法要求履行其他义务的；（十）认为行政机关没有依法支付抚恤金、最低生活保障待遇或者社会保险待遇的；（十一）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议的；（十二）认为行政机关侵犯其他人身权、财产权等合法权益的。\\n  ↳ 效力说明：适用：程序法遵循「程序从新」原则，适用现行有效程序规定\\n· 《中华人民共和国民法典》第584条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。\\n  ↳ 效力说明：适用：现行有效\\n  ↳ 关联说明：［引致关联：第584条进一步明确违约损失赔偿额的范围（含可得利益）与可预见规则］\\n· 《中华人民共和国消费者权益保护法》第55条（法律·现行有效）：经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国道路交通安全法》第76条（法律·现行有效）：机动车发生交通事故造成人身伤亡、财产损失的，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿；不足的部分，机动车之间发生交通事故的，由有过错的一方承担赔偿责任；双方都有过错的，按照各自过错的比例分担责任。机动车与非机动车驾驶人、行人之间发生交通事故，非机动车驾驶人、行人没有过错的，由机动车一方承担赔偿责任；有证据证明非机动车驾驶人、行人有过错的，根据过错程度适当减轻机动车一方的赔偿责任；机动车一方没有过错的，承担不超过百分之十的赔偿责任。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国公司法》第3条（法律·现行有效）：公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。有限责任公司的股东以其认缴的出资额为限对公司承担责任；股份有限公司的股东以其认购的股份为限对公司承担责任。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国民事诉讼法》第67条（法律·现行有效）：当事人对自己提出的主张，有责任提供证据。当事人及其诉讼代理人因客观原因不能自行收集的证据，或者人民法院认为审理案件需要的证据，人民法院应当调查收集。人民法院应当按照法定程序，全面地、客观地审查核实证据。\\n  ↳ 效力说明：适用：程序法遵循「程序从新」原则，适用现行有效程序规定\\n· 《中华人民共和国行政复议法》第11条（法律·现行有效）：有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；（二）对行政机关作出的行政强制措施、行政强制执行决定不服；（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；（四）对行政机关作出的征收征用决定及其补偿决定不服；（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；（八）认为行政机关在政府信息公开工作中侵犯其合法权益；（九）认为行政机关滥用行政权力排除或者限制竞争；（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。\\n  ↳ 效力说明：适用：程序法遵循「程序从新」原则，适用现行有效程序规定\\n· 《中华人民共和国民法典》第577条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。\\n  ↳ 效力说明：适用：现行有效\\n  ↳ 关联说明：［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］\\n· 《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》第44条（司法解释·现行有效）：因用人单位作出的开除、除名、辞退、解除劳动合同、减少劳动报酬、计算劳动者工作年限等决定而发生的劳动争议，用人单位负举证责任。\\n  ↳ 效力说明：适用：现行有效\\n\\n【规范竞合与法理涵摄推演要求（法律适用关系未配置时的兜底约束）】\\n- 法律解释学涵摄：若涉及跨部门法或多部法律规范竞合且无绝对位阶排他，须严格遵循法律解释学（文义解释、体系解释、立法目的解释），将案件具体事实逐项对应代入规范要件进行涵摄推演；\\n- 审慎抗辩与双向争议提示：明确向用户披露潜在的法律适用分歧点与司法裁决倾向，禁止给出单向绝对化胜诉承诺，提供审慎的诉辩应对策略。\\n\\n【三、涵摄分析与初步结论（小前提推演）】\\n在现有候选依据范围内，结合《中华人民共和国个人信息保护法》第13条、《中华人民共和国行政处罚法》第33条、《中华人民共和国行政诉讼法》第12条、《中华人民共和国民法典》第584条、《中华人民共和国消费者权益保护法》第55条之规定，倾向于按上述条文界定的构成要件与法律后果处理；但鉴于部分事实要件或时空要素尚待核实，上述结论成立需以下列「待核实关键事实」属实为前提，需进一步确认后方可定论。\\n\\n【四、待核实关键事实与补证建议】\\n- 法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）\\n- 确认争议双方的身份关系与法律关系性质凭证\\n- 确认相对人实施违法、违约或损害行为的具体表现与举证凭证\\n- 确认损害结果及具体诉请主张金额的计算依据\\n\\n【五、诉讼/仲裁时效与程序路径提示】\\n- 【诉讼时效】民事权利请求保护普通诉讼时效为 3 年（《民法典》第188条），自知道或者应当知道权利受损及义务人之日起算。\\n\\n【六、建议法务/律师核实引证的补充条文】\\n- 建议核查引证：《中华人民共和国民法典》第188条（待律师确认后一键纳入正式引用库）\\n\\n（受限兜底模式：本结论包含待确认前提，不得进入自动对外通道，必须经执业律师人工审核后方可使用）", "sentence_traces": [{"sentence_idx": 6, "sentence_text": "· 《中华人民共和国个人信息保护法》第13条（法律·现行有效）：符合下列情形之一的，个人信息处理者方可处理个人信息：（一）取得个人的同意；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "符合下列情形之一的，个人信息处理者方可处理个人信息：（一）取得个人的同意", "trace_source": "explicit_anchor"}, {"sentence_idx": 7, "sentence_text": "（二）为订立、履行个人作为一方当事人的合同所必需，或者按照依法制定的劳动规章制度和依法签订的集体合同实施人力资源管理所必需；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "（二）为订立、履行个人作为一方当事人的合同所必需，或者按照依法制定的劳动规章制度和依法签订的集体合同实施人力资源管理所必需", "trace_source": "ngram_overlap"}, {"sentence_idx": 8, "sentence_text": "（三）为履行法定职责或者法定义务所必需；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "（三）为履行法定职责或者法定义务所必需", "trace_source": "ngram_overlap"}, {"sentence_idx": 9, "sentence_text": "（四）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "（四）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需", "trace_source": "ngram_overlap"}, {"sentence_idx": 10, "sentence_text": "（五）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "（五）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息", "trace_source": "ngram_overlap"}, {"sentence_idx": 11, "sentence_text": "（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息", "trace_source": "ngram_overlap"}, {"sentence_idx": 12, "sentence_text": "（七）法律、行政法规规定的其他情形。", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "（七）法律、行政法规规定的其他情形", "trace_source": "ngram_overlap"}, {"sentence_idx": 14, "sentence_text": "· 《中华人民共和国行政处罚法》第33条（法律·现行有效）：违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚", "trace_source": "explicit_anchor"}, {"sentence_idx": 15, "sentence_text": "初次违法且危害后果轻微并及时改正的，可以不予行政处罚。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "初次违法且危害后果轻微并及时改正的，可以不予行政处罚", "trace_source": "ngram_overlap"}, {"sentence_idx": 16, "sentence_text": "当事人有证据足以证明没有主观过错的，不予行政处罚。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "当事人有证据足以证明没有主观过错的，不予行政处罚", "trace_source": "ngram_overlap"}, {"sentence_idx": 17, "sentence_text": "法律、行政法规另有规定的，从其规定。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "法律、行政法规另有规定的，从其规定", "trace_source": "ngram_overlap"}, {"sentence_idx": 18, "sentence_text": "对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育", "trace_source": "ngram_overlap"}, {"sentence_idx": 20, "sentence_text": "· 《中华人民共和国行政诉讼法》第12条（法律·现行有效）：人民法院受理公民、法人或者其他组织提起的下列诉讼：（一）对行政拘留、罚款、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、警告等行政处罚不服的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "人民法院受理公民、法人或者其他组织提起的下列诉讼：（一）对行政拘留、罚款、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、警告等行政处罚不服的", "trace_source": "explicit_anchor"}, {"sentence_idx": 21, "sentence_text": "（二）对限制人身自由或者对财产的查封、扣押、冻结等行政强制措施和行政强制执行不服的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（二）对限制人身自由或者对财产的查封、扣押、冻结等行政强制措施和行政强制执行不服的", "trace_source": "ngram_overlap"}, {"sentence_idx": 22, "sentence_text": "（三）申请行政许可，行政机关拒绝或者在法定期限内不予答复，或者对行政机关作出的有关行政许可的其他决定不服的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（三）申请行政许可，行政机关拒绝或者在法定期限内不予答复，或者对行政机关作出的有关行政许可的其他决定不服的", "trace_source": "ngram_overlap"}, {"sentence_idx": 23, "sentence_text": "（四）对行政机关作出的关于确认土地、矿藏、水流、森林、山岭、草原、荒地、滩涂、海域等自然资源的所有权或者使用权的决定不服的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（四）对行政机关作出的关于确认土地、矿藏、水流、森林、山岭、草原、荒地、滩涂、海域等自然资源的所有权或者使用权的决定不服的", "trace_source": "ngram_overlap"}, {"sentence_idx": 24, "sentence_text": "（五）对征收、征用决定及其补偿决定不服的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（五）对征收、征用决定及其补偿决定不服的", "trace_source": "ngram_overlap"}, {"sentence_idx": 25, "sentence_text": "（六）申请行政机关履行保护人身权、财产权等合法权益的法定职责，行政机关拒绝履行或者不予答复的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（六）申请行政机关履行保护人身权、财产权等合法权益的法定职责，行政机关拒绝履行或者不予答复的", "trace_source": "ngram_overlap"}, {"sentence_idx": 26, "sentence_text": "（七）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（七）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权的", "trace_source": "ngram_overlap"}, {"sentence_idx": 27, "sentence_text": "（八）认为行政机关滥用行政权力排除或者限制竞争的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（八）认为行政机关滥用行政权力排除或者限制竞争的", "trace_source": "ngram_overlap"}, {"sentence_idx": 28, "sentence_text": "（九）认为行政机关违法集资、摊派费用或者违法要求履行其他义务的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（九）认为行政机关违法集资、摊派费用或者违法要求履行其他义务的", "trace_source": "ngram_overlap"}, {"sentence_idx": 29, "sentence_text": "（十）认为行政机关没有依法支付抚恤金、最低生活保障待遇或者社会保险待遇的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（十）认为行政机关没有依法支付抚恤金、最低生活保障待遇或者社会保险待遇的", "trace_source": "ngram_overlap"}, {"sentence_idx": 30, "sentence_text": "（十一）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（十一）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议的", "trace_source": "ngram_overlap"}, {"sentence_idx": 31, "sentence_text": "（十二）认为行政机关侵犯其他人身权、财产权等合法权益的。", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（十二）认为行政机关侵犯其他人身权、财产权等合法权益的", "trace_source": "ngram_overlap"}, {"sentence_idx": 33, "sentence_text": "· 《中华人民共和国民法典》第584条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 1.0, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 34, "sentence_text": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 1.0, "highlight_snippet": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失", "trace_source": "ngram_overlap"}, {"sentence_idx": 36, "sentence_text": "↳ 关联说明：［引致关联：第584条进一步明确违约损失赔偿额的范围（含可得利益）与可预见规则］", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 0.3848, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 37, "sentence_text": "· 《中华人民共和国消费者权益保护法》第55条（法律·现行有效）：经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；", "matched_law": "中华人民共和国消费者权益保护法", "matched_article": "第55条", "confidence_score": 1.0, "highlight_snippet": "经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍", "trace_source": "explicit_anchor"}, {"sentence_idx": 38, "sentence_text": "增加赔偿的金额不足五百元的，为五百元。", "matched_law": "中华人民共和国消费者权益保护法", "matched_article": "第55条", "confidence_score": 1.0, "highlight_snippet": "增加赔偿的金额不足五百元的，为五百元", "trace_source": "ngram_overlap"}, {"sentence_idx": 39, "sentence_text": "法律另有规定的，依照其规定。", "matched_law": "中华人民共和国消费者权益保护法", "matched_article": "第55条", "confidence_score": 1.0, "highlight_snippet": "法律另有规定的，依照其规定", "trace_source": "ngram_overlap"}, {"sentence_idx": 41, "sentence_text": "· 《中华人民共和国道路交通安全法》第76条（法律·现行有效）：机动车发生交通事故造成人身伤亡、财产损失的，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿；", "matched_law": "中华人民共和国道路交通安全法", "matched_article": "第76条", "confidence_score": 1.0, "highlight_snippet": "机动车发生交通事故造成人身伤亡、财产损失的，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿", "trace_source": "explicit_anchor"}, {"sentence_idx": 42, "sentence_text": "不足的部分，机动车之间发生交通事故的，由有过错的一方承担赔偿责任；", "matched_law": "中华人民共和国道路交通安全法", "matched_article": "第76条", "confidence_score": 1.0, "highlight_snippet": "不足的部分，机动车之间发生交通事故的，由有过错的一方承担赔偿责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 43, "sentence_text": "双方都有过错的，按照各自过错的比例分担责任。", "matched_law": "中华人民共和国道路交通安全法", "matched_article": "第76条", "confidence_score": 1.0, "highlight_snippet": "双方都有过错的，按照各自过错的比例分担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 44, "sentence_text": "机动车与非机动车驾驶人、行人之间发生交通事故，非机动车驾驶人、行人没有过错的，由机动车一方承担赔偿责任；", "matched_law": "中华人民共和国道路交通安全法", "matched_article": "第76条", "confidence_score": 1.0, "highlight_snippet": "机动车与非机动车驾驶人、行人之间发生交通事故，非机动车驾驶人、行人没有过错的，由机动车一方承担赔偿责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 45, "sentence_text": "有证据证明非机动车驾驶人、行人有过错的，根据过错程度适当减轻机动车一方的赔偿责任；", "matched_law": "中华人民共和国道路交通安全法", "matched_article": "第76条", "confidence_score": 1.0, "highlight_snippet": "有证据证明非机动车驾驶人、行人有过错的，根据过错程度适当减轻机动车一方的赔偿责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 46, "sentence_text": "机动车一方没有过错的，承担不超过百分之十的赔偿责任。", "matched_law": "中华人民共和国道路交通安全法", "matched_article": "第76条", "confidence_score": 1.0, "highlight_snippet": "机动车一方没有过错的，承担不超过百分之十的赔偿责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 48, "sentence_text": "· 《中华人民共和国公司法》第3条（法律·现行有效）：公司是企业法人，有独立的法人财产，享有法人财产权。", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "公司是企业法人，有独立的法人财产，享有法人财产权", "trace_source": "explicit_anchor"}, {"sentence_idx": 49, "sentence_text": "公司以其全部财产对公司的债务承担责任。", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "公司以其全部财产对公司的债务承担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 50, "sentence_text": "有限责任公司的股东以其认缴的出资额为限对公司承担责任；", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "有限责任公司的股东以其认缴的出资额为限对公司承担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 51, "sentence_text": "股份有限公司的股东以其认购的股份为限对公司承担责任。", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "股份有限公司的股东以其认购的股份为限对公司承担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 53, "sentence_text": "· 《中华人民共和国民事诉讼法》第67条（法律·现行有效）：当事人对自己提出的主张，有责任提供证据。", "matched_law": "中华人民共和国民事诉讼法", "matched_article": "第67条", "confidence_score": 1.0, "highlight_snippet": "当事人对自己提出的主张，有责任提供证据", "trace_source": "explicit_anchor"}, {"sentence_idx": 54, "sentence_text": "当事人及其诉讼代理人因客观原因不能自行收集的证据，或者人民法院认为审理案件需要的证据，人民法院应当调查收集。", "matched_law": "中华人民共和国民事诉讼法", "matched_article": "第67条", "confidence_score": 1.0, "highlight_snippet": "当事人及其诉讼代理人因客观原因不能自行收集的证据，或者人民法院认为审理案件需要的证据，人民法院应当调查收集", "trace_source": "ngram_overlap"}, {"sentence_idx": 55, "sentence_text": "人民法院应当按照法定程序，全面地、客观地审查核实证据。", "matched_law": "中华人民共和国民事诉讼法", "matched_article": "第67条", "confidence_score": 1.0, "highlight_snippet": "人民法院应当按照法定程序，全面地、客观地审查核实证据", "trace_source": "ngram_overlap"}, {"sentence_idx": 57, "sentence_text": "· 《中华人民共和国行政复议法》第11条（法律·现行有效）：有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服", "trace_source": "explicit_anchor"}, {"sentence_idx": 58, "sentence_text": "（二）对行政机关作出的行政强制措施、行政强制执行决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（二）对行政机关作出的行政强制措施、行政强制执行决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 59, "sentence_text": "（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 60, "sentence_text": "（四）对行政机关作出的征收征用决定及其补偿决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（四）对行政机关作出的征收征用决定及其补偿决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 61, "sentence_text": "（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（五）对行政机关作出的赔偿决定或者不予赔偿决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 62, "sentence_text": "（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 63, "sentence_text": "（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议", "trace_source": "ngram_overlap"}, {"sentence_idx": 64, "sentence_text": "（八）认为行政机关在政府信息公开工作中侵犯其合法权益；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（八）认为行政机关在政府信息公开工作中侵犯其合法权益", "trace_source": "ngram_overlap"}, {"sentence_idx": 65, "sentence_text": "（九）认为行政机关滥用行政权力排除或者限制竞争；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（九）认为行政机关滥用行政权力排除或者限制竞争", "trace_source": "ngram_overlap"}, {"sentence_idx": 66, "sentence_text": "（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务", "trace_source": "ngram_overlap"}, {"sentence_idx": 67, "sentence_text": "（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复", "trace_source": "ngram_overlap"}, {"sentence_idx": 68, "sentence_text": "（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付", "trace_source": "ngram_overlap"}, {"sentence_idx": 69, "sentence_text": "（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议", "trace_source": "ngram_overlap"}, {"sentence_idx": 70, "sentence_text": "（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权", "trace_source": "ngram_overlap"}, {"sentence_idx": 71, "