REPLACE INTO session_snapshots (thread_id, updated_at, status, query, act_date, region, confidence, review_level, state_json) VALUES ('9e943cff-e822-4bf1-938e-4237c133d0b4', '2026-11-06T03:17:06.937345+00:00', 'needs_review', '公司转让股权有哪些法律限制？', '2026-11-06', '', 'B', 'must', '{"query": "公司转让股权有哪些法律限制？", "act_date": "2026-11-06", "region": "", "answer_confidence": "B", "rule_plan": {"mode": "llm_assisted", "confidence": "B", "review": "must", "llm_callable": true, "prompt_constraints": ["只能引用给定候选条文；不得生成任何未出现的条文号、法规名称或文号", "禁止使用“必然/一定/肯定/应当”等确定性表述；改用“在……前提下/倾向于/需进一步确认”", "必须显式说明：规则未覆盖的具体原因、不确定性来源、以及结论成立所需的前提", "必须给出至少一项建议核实或补证事项（如行为发生日期、制定机关、事实细节）", "本结论标记为兜底结果，不得进入自动对外通道，必须经人工审核后方可使用"], "verify_actions": ["向当事人核实法律事实发生的具体日期（或持续起止期间）", "法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）", "确认公司设立日期、章程约定的认缴出资期限及争议行为发生日（2024-07-01 新《公司法》施行前后规则不同）", "确认股东认缴出资额、已实缴金额及是否届满认缴期限"], "reason": "当事人未提供法律事实发生日期，暂按当前日期（2026-11-06）定位现行有效法；若系历史纠纷，适用依据可能不同；行为发生日 2026-11-06 不早于施行日 2024-07-01，且该条现行有效；行为发生日 2026-11-06 不早于施行日 2021-11-01，且该条现行有效；行为发生日 2026-11-06 不早于施行日 2021-01-01，且该条现行有效；《中华人民共和国行政复议法》第11条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-06）适用现行有效规定"}, "final_output": {"citations": [{"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "article_effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第20条", "paragraph": "", "content": "公司股东应当遵守法律、行政法规和公司章程，依法行使股东权利，不得滥用股东权利损害公司或者其他股东的利益；不得滥用公司法人独立地位和股东有限责任损害公司债权人的利益。公司股东滥用公司法人独立地位和股东有限责任，逃避债务，严重损害公司债权人利益的，应当对公司债务承担连带责任。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 37.4033, "rerank_score": 0.0981, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "article_effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第47条", "paragraph": "", "content": "有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "［新旧法对照：2018版第26条实行无期限限制的注册资本认缴制；2023修订第47条（2024-07-01施行）改为自公司成立之日起5年内缴足的限期认缴制］ 2023-12-29修订通过、2024-07-01施行；行为发生日早于施行日的不得适用本条（法不溯及既往）。", "score": 38.9318, "rerank_score": 0.091, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "article_effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第3条", "paragraph": "", "content": "公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。有限责任公司的股东以其认缴的出资额为限对公司承担责任；股份有限公司的股东以其认购的股份为限对公司承担责任。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 32.9899, "rerank_score": 0.0889, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "article_effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第210条", "paragraph": "", "content": "公司弥补亏损和提取公积金后所余税后利润，有限责任公司按照股东实缴的出资比例分配利润，全体股东约定不按照出资比例分配利润的除外；股份有限公司按照股东所持有的股份比例分配利润，公司章程另有规定的除外。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 31.4734, "rerank_score": 0.0752, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国个人信息保护法", "document_number": "主席令第91号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2021-08-20", "effective_date": "2021-11-01", "article_effective_date": "2021-11-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第44条", "paragraph": "", "content": "个人对其个人信息的处理享有知情权、决定权，有权限制或者拒绝他人对其个人信息进行处理；法律、行政法规另有规定的除外。", "source": "全国人民代表大会常务委员会", "category": "数据合规", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 25.4714, "rerank_score": 0.0553, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第584条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "［引致关联：第584条进一步明确违约损失赔偿额的范围（含可得利益）与可预见规则］", "score": 46.432, "rerank_score": 0.051, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国行政复议法", "document_number": "主席令第9号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1999-04-29", "effective_date": "2024-01-01", "article_effective_date": "2024-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第11条", "paragraph": "", "content": "有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；（二）对行政机关作出的行政强制措施、行政强制执行决定不服；（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；（四）对行政机关作出的征收征用决定及其补偿决定不服；（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；（八）认为行政机关在政府信息公开工作中侵犯其合法权益；（九）认为行政机关滥用行政权力排除或者限制竞争；（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "norm_type": "procedural", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 39.4696, "rerank_score": 0.0446, "applicable_at": true, "applicable_note": "适用：程序法遵循「程序从新」原则，适用现行有效程序规定"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第577条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］", "score": 54.6259, "rerank_score": 0.0387, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第1191条", "paragraph": "", "content": "用人单位的工作人员因执行工作任务造成他人损害，由用人单位承担侵权责任。用人单位承担侵权责任后，可以向有故意或者重大过失的工作人员追偿。劳务派遣期间，被派遣的工作人员因执行工作任务造成他人损害的，由接受劳务派遣的用工单位承担侵权责任；劳务派遣单位有过错的，承担相应的责任。", "source": "全国人民代表大会", "category": "侵权", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 31.4403, "rerank_score": 0.0255, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "最高人民法院关于适用《中华人民共和国民法典》时间效力的若干规定", "document_number": "法释〔2020〕15号", "hierarchy": "司法解释", "host_law": "中华人民共和国民法典", "host_hierarchy": "法律", "host_effective_date": "2021-01-01", "promulgation_date": "2020-12-29", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第1条", "paragraph": "", "content": "民法典施行后的法律事实引起的民事纠纷案件，适用民法典的规定。民法典施行前的法律事实引起的民事纠纷案件，适用当时的法律、司法解释的规定，但是法律、司法解释另有规定的除外。民法典施行前产生的民事关系，持续至民法典施行后，该民事关系产生的民事纠纷案件，适用民法典的规定，但是法律、司法解释另有规定的除外。", "source": "最高人民法院", "category": "民事", "scope": "一般", "norm_type": "judicial_interpretation", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "明确法不溯及既往原则与持续性法律事实跨法从新规则。", "score": 33.809, "rerank_score": 0.0615, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "最高人民法院关于审理劳动争议案件适用法律问题的解释（一）", "document_number": "法释〔2020〕26号", "hierarchy": "司法解释", "host_law": "中华人民共和国劳动合同法", "host_hierarchy": "法律", "host_effective_date": "2008-01-01", "promulgation_date": "2020-12-29", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第44条", "paragraph": "", "content": "因用人单位作出的开除、除名、辞退、解除劳动合同、减少劳动报酬、计算劳动者工作年限等决定而发生的劳动争议，用人单位负举证责任。", "source": "最高人民法院", "category": "劳动", "scope": "特别", "norm_type": "judicial_interpretation", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "位阶依附于《劳动合同法》（法律+0.5），明确劳动争议举证责任倒置规则。", "score": 23.002, "rerank_score": 0.0483, "applicable_at": true, "applicable_note": "适用：现行有效"}], "answer": "【一、争议焦点与事实前提】\\n· 时间前提声明：因未提供具体法律事实发生时间，本意见在**假设争议事实发生于现行法有效期内（暂以 2026-11-06 为基准日）**的前提下推演；若事实发生在旧法期间，须按行为时旧法重新定位。\\n· 争议焦点 1：公司转让股权有哪些法律限制\\n\\n【二、适用法规与效力要旨（大前提）】\\n· 《中华人民共和国公司法》第20条（法律·现行有效）：公司股东应当遵守法律、行政法规和公司章程，依法行使股东权利，不得滥用股东权利损害公司或者其他股东的利益；不得滥用公司法人独立地位和股东有限责任损害公司债权人的利益。公司股东滥用公司法人独立地位和股东有限责任，逃避债务，严重损害公司债权人利益的，应当对公司债务承担连带责任。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国公司法》第47条（法律·现行有效）：有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。\\n  ↳ 效力说明：适用：现行有效\\n  ↳ 关联说明：［新旧法对照：2018版第26条实行无期限限制的注册资本认缴制；2023修订第47条（2024-07-01施行）改为自公司成立之日起5年内缴足的限期认缴制］ 2023-12-29修订通过、2024-07-01施行；行为发生日早于施行日的不得适用本条（法不溯及既往）。\\n· 《中华人民共和国公司法》第3条（法律·现行有效）：公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。有限责任公司的股东以其认缴的出资额为限对公司承担责任；股份有限公司的股东以其认购的股份为限对公司承担责任。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国公司法》第210条（法律·现行有效）：公司弥补亏损和提取公积金后所余税后利润，有限责任公司按照股东实缴的出资比例分配利润，全体股东约定不按照出资比例分配利润的除外；股份有限公司按照股东所持有的股份比例分配利润，公司章程另有规定的除外。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国个人信息保护法》第44条（法律·现行有效）：个人对其个人信息的处理享有知情权、决定权，有权限制或者拒绝他人对其个人信息进行处理；法律、行政法规另有规定的除外。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国民法典》第584条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。\\n  ↳ 效力说明：适用：现行有效\\n  ↳ 关联说明：［引致关联：第584条进一步明确违约损失赔偿额的范围（含可得利益）与可预见规则］\\n· 《中华人民共和国行政复议法》第11条（法律·现行有效）：有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；（二）对行政机关作出的行政强制措施、行政强制执行决定不服；（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；（四）对行政机关作出的征收征用决定及其补偿决定不服；（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；（八）认为行政机关在政府信息公开工作中侵犯其合法权益；（九）认为行政机关滥用行政权力排除或者限制竞争；（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。\\n  ↳ 效力说明：适用：程序法遵循「程序从新」原则，适用现行有效程序规定\\n· 《中华人民共和国民法典》第577条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。\\n  ↳ 效力说明：适用：现行有效\\n  ↳ 关联说明：［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］\\n· 《中华人民共和国民法典》第1191条（法律·现行有效）：用人单位的工作人员因执行工作任务造成他人损害，由用人单位承担侵权责任。用人单位承担侵权责任后，可以向有故意或者重大过失的工作人员追偿。劳务派遣期间，被派遣的工作人员因执行工作任务造成他人损害的，由接受劳务派遣的用工单位承担侵权责任；劳务派遣单位有过错的，承担相应的责任。\\n  ↳ 效力说明：适用：现行有效\\n· 《最高人民法院关于适用《中华人民共和国民法典》时间效力的若干规定》第1条（司法解释·现行有效）：民法典施行后的法律事实引起的民事纠纷案件，适用民法典的规定。民法典施行前的法律事实引起的民事纠纷案件，适用当时的法律、司法解释的规定，但是法律、司法解释另有规定的除外。民法典施行前产生的民事关系，持续至民法典施行后，该民事关系产生的民事纠纷案件，适用民法典的规定，但是法律、司法解释另有规定的除外。\\n  ↳ 效力说明：适用：现行有效\\n· 《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》第44条（司法解释·现行有效）：因用人单位作出的开除、除名、辞退、解除劳动合同、减少劳动报酬、计算劳动者工作年限等决定而发生的劳动争议，用人单位负举证责任。\\n  ↳ 效力说明：适用：现行有效\\n\\n【规范竞合与法理涵摄推演要求（法律适用关系未配置时的兜底约束）】\\n- 法律解释学涵摄：若涉及跨部门法或多部法律规范竞合且无绝对位阶排他，须严格遵循法律解释学（文义解释、体系解释、立法目的解释），将案件具体事实逐项对应代入规范要件进行涵摄推演；\\n- 审慎抗辩与双向争议提示：明确向用户披露潜在的法律适用分歧点与司法裁决倾向，禁止给出单向绝对化胜诉承诺，提供审慎的诉辩应对策略。\\n\\n【三、涵摄分析与初步结论（小前提推演）】\\n在现有候选依据范围内，结合《中华人民共和国公司法》第20条、《中华人民共和国公司法》第47条、《中华人民共和国公司法》第3条、《中华人民共和国公司法》第210条、《中华人民共和国个人信息保护法》第44条之规定，倾向于按上述条文界定的构成要件与法律后果处理；但鉴于部分事实要件或时空要素尚待核实，上述结论成立需以下列「待核实关键事实」属实为前提，需进一步确认后方可定论。\\n\\n【四、待核实关键事实与补证建议】\\n- 法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）\\n- 确认公司设立日期、章程约定的认缴出资期限及争议行为发生日（2024-07-01 新《公司法》施行前后规则不同）\\n- 确认股东认缴出资额、已实缴金额及是否届满认缴期限\\n- 若主张股东对公司债务承担连带责任或出资加速到期，需确认公司是否已不能清偿到期债务或存在财产混同\\n\\n【五、诉讼/仲裁时效与程序路径提示】\\n- 【新旧法衔接】2023年修订《公司法》自 2024-07-01 起施行，规定有限责任公司认缴出资额须自成立之日起 5 年内缴足（第47条），存量公司适用国务院过渡期规定。\\n- 【出资加速到期】依新《公司法》第54条，公司不能清偿到期债务的，公司或者已到期债权的债权人有权要求已认缴出资但未届出资期限的股东提前缴纳出资。\\n\\n（受限兜底模式：本结论包含待确认前提，不得进入自动对外通道，必须经执业律师人工审核后方可使用）", "sentence_traces": [{"sentence_idx": 6, "sentence_text": "· 《中华人民共和国公司法》第20条（法律·现行有效）：公司股东应当遵守法律、行政法规和公司章程，依法行使股东权利，不得滥用股东权利损害公司或者其他股东的利益；", "matched_law": "中华人民共和国公司法", "matched_article": "第20条", "confidence_score": 1.0, "highlight_snippet": "公司股东应当遵守法律、行政法规和公司章程，依法行使股东权利，不得滥用股东权利损害公司或者其他股东的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 7, "sentence_text": "不得滥用公司法人独立地位和股东有限责任损害公司债权人的利益。", "matched_law": "中华人民共和国公司法", "matched_article": "第20条", "confidence_score": 1.0, "highlight_snippet": "不得滥用公司法人独立地位和股东有限责任损害公司债权人的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 8, "sentence_text": "公司股东滥用公司法人独立地位和股东有限责任，逃避债务，严重损害公司债权人利益的，应当对公司债务承担连带责任。", "matched_law": "中华人民共和国公司法", "matched_article": "第20条", "confidence_score": 1.0, "highlight_snippet": "公司股东滥用公司法人独立地位和股东有限责任，逃避债务，严重损害公司债权人利益的，应当对公司债务承担连带责任", "trace_source": "explicit_anchor"}, {"sentence_idx": 10, "sentence_text": "· 《中华人民共和国公司法》第47条（法律·现行有效）：有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。", "matched_law": "中华人民共和国公司法", "matched_article": "第47条", "confidence_score": 1.0, "highlight_snippet": "有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足", "trace_source": "explicit_anchor"}, {"sentence_idx": 11, "sentence_text": "法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。", "matched_law": "中华人民共和国公司法", "matched_article": "第47条", "confidence_score": 1.0, "highlight_snippet": "法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定", "trace_source": "ngram_overlap"}, {"sentence_idx": 14, "sentence_text": "2023修订第47条（2024-07-01施行）改为自公司成立之日起5年内缴足的限期认缴制］ 2023-12-29修订通过、2024-07-01施行；", "matched_law": "中华人民共和国公司法", "matched_article": "第47条", "confidence_score": 0.4284, "highlight_snippet": "有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足", "trace_source": "explicit_anchor"}, {"sentence_idx": 16, "sentence_text": "· 《中华人民共和国公司法》第3条（法律·现行有效）：公司是企业法人，有独立的法人财产，享有法人财产权。", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "公司是企业法人，有独立的法人财产，享有法人财产权", "trace_source": "explicit_anchor"}, {"sentence_idx": 17, "sentence_text": "公司以其全部财产对公司的债务承担责任。", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "公司以其全部财产对公司的债务承担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 18, "sentence_text": "有限责任公司的股东以其认缴的出资额为限对公司承担责任；", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "有限责任公司的股东以其认缴的出资额为限对公司承担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 19, "sentence_text": "股份有限公司的股东以其认购的股份为限对公司承担责任。", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "股份有限公司的股东以其认购的股份为限对公司承担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 21, "sentence_text": "· 《中华人民共和国公司法》第210条（法律·现行有效）：公司弥补亏损和提取公积金后所余税后利润，有限责任公司按照股东实缴的出资比例分配利润，全体股东约定不按照出资比例分配利润的除外；", "matched_law": "中华人民共和国公司法", "matched_article": "第210条", "confidence_score": 1.0, "highlight_snippet": "公司弥补亏损和提取公积金后所余税后利润，有限责任公司按照股东实缴的出资比例分配利润，全体股东约定不按照出资比例分配利润的除外", "trace_source": "explicit_anchor"}, {"sentence_idx": 22, "sentence_text": "股份有限公司按照股东所持有的股份比例分配利润，公司章程另有规定的除外。", "matched_law": "中华人民共和国公司法", "matched_article": "第210条", "confidence_score": 1.0, "highlight_snippet": "股份有限公司按照股东所持有的股份比例分配利润，公司章程另有规定的除外", "trace_source": "ngram_overlap"}, {"sentence_idx": 24, "sentence_text": "· 《中华人民共和国个人信息保护法》第44条（法律·现行有效）：个人对其个人信息的处理享有知情权、决定权，有权限制或者拒绝他人对其个人信息进行处理；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第44条", "confidence_score": 1.0, "highlight_snippet": "个人对其个人信息的处理享有知情权、决定权，有权限制或者拒绝他人对其个人信息进行处理", "trace_source": "explicit_anchor"}, {"sentence_idx": 25, "sentence_text": "法律、行政法规另有规定的除外。", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第44条", "confidence_score": 1.0, "highlight_snippet": "法律、行政法规另有规定的除外", "trace_source": "ngram_overlap"}, {"sentence_idx": 27, "sentence_text": "· 《中华人民共和国民法典》第584条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 1.0, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 28, "sentence_text": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 1.0, "highlight_snippet": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失", "trace_source": "ngram_overlap"}, {"sentence_idx": 30, "sentence_text": "↳ 关联说明：［引致关联：第584条进一步明确违约损失赔偿额的范围（含可得利益）与可预见规则］", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 0.3848, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 31, "sentence_text": "· 《中华人民共和国行政复议法》第11条（法律·现行有效）：有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服", "trace_source": "explicit_anchor"}, {"sentence_idx": 32, "sentence_text": "（二）对行政机关作出的行政强制措施、行政强制执行决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（二）对行政机关作出的行政强制措施、行政强制执行决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 33, "sentence_text": "（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 34, "sentence_text": "（四）对行政机关作出的征收征用决定及其补偿决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（四）对行政机关作出的征收征用决定及其补偿决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 35, "sentence_text": "（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（五）对行政机关作出的赔偿决定或者不予赔偿决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 36, "sentence_text": "（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 37, "sentence_text": "（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议", "trace_source": "ngram_overlap"}, {"sentence_idx": 38, "sentence_text": "（八）认为行政机关在政府信息公开工作中侵犯其合法权益；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（八）认为行政机关在政府信息公开工作中侵犯其合法权益", "trace_source": "ngram_overlap"}, {"sentence_idx": 39, "sentence_text": "（九）认为行政机关滥用行政权力排除或者限制竞争；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（九）认为行政机关滥用行政权力排除或者限制竞争", "trace_source": "ngram_overlap"}, {"sentence_idx": 40, "sentence_text": "（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务", "trace_source": "ngram_overlap"}, {"sentence_idx": 41, "sentence_text": "（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复", "trace_source": "ngram_overlap"}, {"sentence_idx": 42, "sentence_text": "（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付", "trace_source": "ngram_overlap"}, {"sentence_idx": 43, "sentence_text": "（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议", "trace_source": "ngram_overlap"}, {"sentence_idx": 44, "sentence_text": "（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；", "matched_law": "中华人民共和国行政复议法", "matched_article": "