REPLACE INTO session_snapshots (thread_id, updated_at, status, query, act_date, region, confidence, review_level, state_json) VALUES ('8cb77171-4b6b-4b54-8935-f60c639f3797', '2026-11-06T03:27:39.081669+00:00', 'needs_review', '如果是国有独资企业给我们行做担保，银行在审批时有哪些特殊注意事项？', '2026-11-06', '', 'B', 'must', '{"query": "如果是国有独资企业给我们行做担保，银行在审批时有哪些特殊注意事项？", "act_date": "2026-11-06", "region": "", "answer_confidence": "B", "rule_plan": {"mode": "llm_assisted", "confidence": "B", "review": "must", "llm_callable": true, "prompt_constraints": ["只能引用给定候选条文；不得生成任何未出现的条文号、法规名称或文号", "禁止使用“必然/一定/肯定/应当”等确定性表述；改用“在……前提下/倾向于/需进一步确认”", "必须显式说明：规则未覆盖的具体原因、不确定性来源、以及结论成立所需的前提", "必须给出至少一项建议核实或补证事项（如行为发生日期、制定机关、事实细节）", "本结论标记为兜底结果，不得进入自动对外通道，必须经人工审核后方可使用"], "verify_actions": ["向当事人核实法律事实发生的具体日期（或持续起止期间）", "法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）", "确认争议双方的身份关系与法律关系性质凭证", "确认相对人实施违法、违约或损害行为的具体表现与举证凭证"], "reason": "当事人未提供法律事实发生日期，暂按当前日期（2026-11-06）定位现行有效法；若系历史纠纷，适用依据可能不同；行为发生日 2026-11-06 不早于施行日 2024-07-01，且该条现行有效；行为发生日 2026-11-06 不早于施行日 2021-01-01，且该条现行有效；《中华人民共和国行政诉讼法》第12条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-06）适用现行有效规定；行为发生日 2026-11-06 不早于施行日 2021-07-15，且该条现行有效；行为发生日 2026-11-06 不早于施行日 2014-03-15，且该条现行有效；《中华人民共和国行政复议法》第11条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-06）适用现行有效规定；行为发生日 2026-11-06 不早于施行日 2023-12-05，且该条现行有效"}, "final_output": {"citations": [{"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "article_effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第3条", "paragraph": "", "content": "公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。有限责任公司的股东以其认缴的出资额为限对公司承担责任；股份有限公司的股东以其认购的股份为限对公司承担责任。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 53.6, "rerank_score": 0.0916, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第584条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "［引致关联：第584条进一步明确违约损失赔偿额的范围（含可得利益）与可预见规则］", "score": 50.2176, "rerank_score": 0.0681, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "article_effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第20条", "paragraph": "", "content": "公司股东应当遵守法律、行政法规和公司章程，依法行使股东权利，不得滥用股东权利损害公司或者其他股东的利益；不得滥用公司法人独立地位和股东有限责任损害公司债权人的利益。公司股东滥用公司法人独立地位和股东有限责任，逃避债务，严重损害公司债权人利益的，应当对公司债务承担连带责任。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 25.8713, "rerank_score": 0.0577, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第985条", "paragraph": "", "content": "得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付；（二）债务到期之前的清偿；（三）明知无给付义务而进行的债务清偿。", "source": "全国人民代表大会", "category": "民事", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 26.3411, "rerank_score": 0.0495, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第985条", "paragraph": "第（一）项", "content": "得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付。", "source": "全国人民代表大会", "category": "民事", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "款项级引用演示：不当得利返还的除外情形之一。", "score": 25.6163, "rerank_score": 0.0476, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国行政诉讼法", "document_number": "主席令第71号（2017年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1989-04-04", "effective_date": "2017-07-01", "article_effective_date": "2015-05-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第12条", "paragraph": "", "content": "人民法院受理公民、法人或者其他组织提起的下列诉讼：（一）对行政拘留、罚款、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、警告等行政处罚不服的；（二）对限制人身自由或者对财产的查封、扣押、冻结等行政强制措施和行政强制执行不服的；（三）申请行政许可，行政机关拒绝或者在法定期限内不予答复，或者对行政机关作出的有关行政许可的其他决定不服的；（四）对行政机关作出的关于确认土地、矿藏、水流、森林、山岭、草原、荒地、滩涂、海域等自然资源的所有权或者使用权的决定不服的；（五）对征收、征用决定及其补偿决定不服的；（六）申请行政机关履行保护人身权、财产权等合法权益的法定职责，行政机关拒绝履行或者不予答复的；（七）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权的；（八）认为行政机关滥用行政权力排除或者限制竞争的；（九）认为行政机关违法集资、摊派费用或者违法要求履行其他义务的；（十）认为行政机关没有依法支付抚恤金、最低生活保障待遇或者社会保险待遇的；（十一）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议的；（十二）认为行政机关侵犯其他人身权、财产权等合法权益的。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "norm_type": "procedural", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 36.2886, "rerank_score": 0.0453, "applicable_at": true, "applicable_note": "适用：程序法遵循「程序从新」原则，适用现行有效程序规定"}, {"law_name": "中华人民共和国行政处罚法", "document_number": "主席令第70号（2021年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1996-03-17", "effective_date": "2021-07-15", "article_effective_date": "2021-07-15", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第33条", "paragraph": "", "content": "违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "norm_type": "administrative_penalty", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 34.3897, "rerank_score": 0.0452, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国消费者权益保护法", "document_number": "主席令第7号（2013年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1993-10-31", "effective_date": "2014-03-15", "article_effective_date": "2014-03-15", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第26条", "paragraph": "", "content": "经营者在经营活动中使用格式条款的，应当以显著方式提请消费者注意与消费者有重大利害关系的内容，并按照消费者的要求予以说明。经营者不得以格式条款、通知、声明、店堂告示等方式，作出排除或者限制消费者权利、减轻或者免除经营者责任、加重消费者责任等对消费者不公平、不合理的规定。含有前述内容的，其内容无效。", "source": "全国人民代表大会常务委员会", "category": "消费", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 20.6176, "rerank_score": 0.0421, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "article_effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第59条", "paragraph": "", "content": "股东会行使下列职权：（一）选举和更换董事、监事，决定有关董事、监事的报酬事项；（二）审议批准董事会的报告；（三）审议批准监事会的报告；（四）审议批准公司的利润分配方案和弥补亏损方案；（五）对公司增加或者减少注册资本作出决议；（六）对发行公司债券作出决议；（七）对公司合并、分立、解散、清算或者变更公司形式作出决议；（八）修改公司章程；（九）公司章程规定的其他职权。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 35.2732, "rerank_score": 0.0401, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国行政复议法", "document_number": "主席令第9号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1999-04-29", "effective_date": "2024-01-01", "article_effective_date": "2024-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第11条", "paragraph": "", "content": "有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；（二）对行政机关作出的行政强制措施、行政强制执行决定不服；（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；（四）对行政机关作出的征收征用决定及其补偿决定不服；（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；（八）认为行政机关在政府信息公开工作中侵犯其合法权益；（九）认为行政机关滥用行政权力排除或者限制竞争；（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "norm_type": "procedural", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 44.2163, "rerank_score": 0.0372, "applicable_at": true, "applicable_note": "适用：程序法遵循「程序从新」原则，适用现行有效程序规定"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第577条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］", "score": 59.0795, "rerank_score": 0.0324, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第153条", "paragraph": "", "content": "违反法律、行政法规的强制性规定的民事法律行为无效。但是，该强制性规定不导致该民事法律行为无效的除外。违背公序良俗的民事法律行为无效。", "source": "全国人民代表大会", "category": "民事", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 21.4421, "rerank_score": 0.0204, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "最高人民法院关于适用《中华人民共和国民法典》时间效力的若干规定", "document_number": "法释〔2020〕15号", "hierarchy": "司法解释", "host_law": "中华人民共和国民法典", "host_hierarchy": "法律", "host_effective_date": "2021-01-01", "promulgation_date": "2020-12-29", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第1条", "paragraph": "", "content": "民法典施行后的法律事实引起的民事纠纷案件，适用民法典的规定。民法典施行前的法律事实引起的民事纠纷案件，适用当时的法律、司法解释的规定，但是法律、司法解释另有规定的除外。民法典施行前产生的民事关系，持续至民法典施行后，该民事关系产生的民事纠纷案件，适用民法典的规定，但是法律、司法解释另有规定的除外。", "source": "最高人民法院", "category": "民事", "scope": "一般", "norm_type": "judicial_interpretation", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "明确法不溯及既往原则与持续性法律事实跨法从新规则。", "score": 31.7649, "rerank_score": 0.0567, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "最高人民法院关于审理劳动争议案件适用法律问题的解释（一）", "document_number": "法释〔2020〕26号", "hierarchy": "司法解释", "host_law": "中华人民共和国劳动合同法", "host_hierarchy": "法律", "host_effective_date": "2008-01-01", "promulgation_date": "2020-12-29", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第44条", "paragraph": "", "content": "因用人单位作出的开除、除名、辞退、解除劳动合同、减少劳动报酬、计算劳动者工作年限等决定而发生的劳动争议，用人单位负举证责任。", "source": "最高人民法院", "category": "劳动", "scope": "特别", "norm_type": "judicial_interpretation", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "位阶依附于《劳动合同法》（法律+0.5），明确劳动争议举证责任倒置规则。", "score": 18.2368, "rerank_score": 0.0456, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释", "document_number": "法释〔2023〕13号", "hierarchy": "司法解释", "host_law": "中华人民共和国民法典", "host_hierarchy": "法律", "host_effective_date": "2021-01-01", "promulgation_date": "2023-12-04", "effective_date": "2023-12-05", "article_effective_date": "2023-12-05", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第3条", "paragraph": "", "content": "当事人对合同是否成立存在争议，人民法院能够确定当事人姓名或者名称、标的和数量的，一般应当认定合同成立。但是，法律另有规定或者当事人另有约定的除外。", "source": "最高人民法院", "category": "合同", "scope": "", "norm_type": "judicial_interpretation", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "位阶依附于《民法典》；原文据最高人民法院公告核实。", "score": 20.1169, "rerank_score": 0.0228, "applicable_at": true, "applicable_note": "适用：现行有效"}], "answer": "【一、争议焦点与事实前提】\\n· 时间前提声明：因未提供具体法律事实发生时间，本意见在**假设争议事实发生于现行法有效期内（暂以 2026-11-06 为基准日）**的前提下推演；若事实发生在旧法期间，须按行为时旧法重新定位。\\n· 争议焦点 1：如果是国有独资企业给我们行做担保，银行在审批时有哪些特殊注意事项\\n\\n【二、适用法规与效力要旨（大前提）】\\n· 《中华人民共和国公司法》第3条（法律·现行有效）：公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。有限责任公司的股东以其认缴的出资额为限对公司承担责任；股份有限公司的股东以其认购的股份为限对公司承担责任。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国民法典》第584条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。\\n  ↳ 效力说明：适用：现行有效\\n  ↳ 关联说明：［引致关联：第584条进一步明确违约损失赔偿额的范围（含可得利益）与可预见规则］\\n· 《中华人民共和国公司法》第20条（法律·现行有效）：公司股东应当遵守法律、行政法规和公司章程，依法行使股东权利，不得滥用股东权利损害公司或者其他股东的利益；不得滥用公司法人独立地位和股东有限责任损害公司债权人的利益。公司股东滥用公司法人独立地位和股东有限责任，逃避债务，严重损害公司债权人利益的，应当对公司债务承担连带责任。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国民法典》第985条（法律·现行有效）：得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付；（二）债务到期之前的清偿；（三）明知无给付义务而进行的债务清偿。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国民法典》第985条第（一）项（法律·现行有效）：得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国行政诉讼法》第12条（法律·现行有效）：人民法院受理公民、法人或者其他组织提起的下列诉讼：（一）对行政拘留、罚款、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、警告等行政处罚不服的；（二）对限制人身自由或者对财产的查封、扣押、冻结等行政强制措施和行政强制执行不服的；（三）申请行政许可，行政机关拒绝或者在法定期限内不予答复，或者对行政机关作出的有关行政许可的其他决定不服的；（四）对行政机关作出的关于确认土地、矿藏、水流、森林、山岭、草原、荒地、滩涂、海域等自然资源的所有权或者使用权的决定不服的；（五）对征收、征用决定及其补偿决定不服的；（六）申请行政机关履行保护人身权、财产权等合法权益的法定职责，行政机关拒绝履行或者不予答复的；（七）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权的；（八）认为行政机关滥用行政权力排除或者限制竞争的；（九）认为行政机关违法集资、摊派费用或者违法要求履行其他义务的；（十）认为行政机关没有依法支付抚恤金、最低生活保障待遇或者社会保险待遇的；（十一）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议的；（十二）认为行政机关侵犯其他人身权、财产权等合法权益的。\\n  ↳ 效力说明：适用：程序法遵循「程序从新」原则，适用现行有效程序规定\\n· 《中华人民共和国行政处罚法》第33条（法律·现行有效）：违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国消费者权益保护法》第26条（法律·现行有效）：经营者在经营活动中使用格式条款的，应当以显著方式提请消费者注意与消费者有重大利害关系的内容，并按照消费者的要求予以说明。经营者不得以格式条款、通知、声明、店堂告示等方式，作出排除或者限制消费者权利、减轻或者免除经营者责任、加重消费者责任等对消费者不公平、不合理的规定。含有前述内容的，其内容无效。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国公司法》第59条（法律·现行有效）：股东会行使下列职权：（一）选举和更换董事、监事，决定有关董事、监事的报酬事项；（二）审议批准董事会的报告；（三）审议批准监事会的报告；（四）审议批准公司的利润分配方案和弥补亏损方案；（五）对公司增加或者减少注册资本作出决议；（六）对发行公司债券作出决议；（七）对公司合并、分立、解散、清算或者变更公司形式作出决议；（八）修改公司章程；（九）公司章程规定的其他职权。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国行政复议法》第11条（法律·现行有效）：有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；（二）对行政机关作出的行政强制措施、行政强制执行决定不服；（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；（四）对行政机关作出的征收征用决定及其补偿决定不服；（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；（八）认为行政机关在政府信息公开工作中侵犯其合法权益；（九）认为行政机关滥用行政权力排除或者限制竞争；（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。\\n  ↳ 效力说明：适用：程序法遵循「程序从新」原则，适用现行有效程序规定\\n· 《中华人民共和国民法典》第577条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。\\n  ↳ 效力说明：适用：现行有效\\n  ↳ 关联说明：［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］\\n· 《中华人民共和国民法典》第153条（法律·现行有效）：违反法律、行政法规的强制性规定的民事法律行为无效。但是，该强制性规定不导致该民事法律行为无效的除外。违背公序良俗的民事法律行为无效。\\n  ↳ 效力说明：适用：现行有效\\n· 《最高人民法院关于适用《中华人民共和国民法典》时间效力的若干规定》第1条（司法解释·现行有效）：民法典施行后的法律事实引起的民事纠纷案件，适用民法典的规定。民法典施行前的法律事实引起的民事纠纷案件，适用当时的法律、司法解释的规定，但是法律、司法解释另有规定的除外。民法典施行前产生的民事关系，持续至民法典施行后，该民事关系产生的民事纠纷案件，适用民法典的规定，但是法律、司法解释另有规定的除外。\\n  ↳ 效力说明：适用：现行有效\\n· 《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》第44条（司法解释·现行有效）：因用人单位作出的开除、除名、辞退、解除劳动合同、减少劳动报酬、计算劳动者工作年限等决定而发生的劳动争议，用人单位负举证责任。\\n  ↳ 效力说明：适用：现行有效\\n· 《最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释》第3条（司法解释·现行有效）：当事人对合同是否成立存在争议，人民法院能够确定当事人姓名或者名称、标的和数量的，一般应当认定合同成立。但是，法律另有规定或者当事人另有约定的除外。\\n  ↳ 效力说明：适用：现行有效\\n\\n【规范竞合与法理涵摄推演要求（法律适用关系未配置时的兜底约束）】\\n- 法律解释学涵摄：若涉及跨部门法或多部法律规范竞合且无绝对位阶排他，须严格遵循法律解释学（文义解释、体系解释、立法目的解释），将案件具体事实逐项对应代入规范要件进行涵摄推演；\\n- 审慎抗辩与双向争议提示：明确向用户披露潜在的法律适用分歧点与司法裁决倾向，禁止给出单向绝对化胜诉承诺，提供审慎的诉辩应对策略。\\n\\n【三、涵摄分析与初步结论（小前提推演）】\\n在现有候选依据范围内，结合《中华人民共和国公司法》第3条、《中华人民共和国民法典》第584条、《中华人民共和国公司法》第20条、《中华人民共和国民法典》第985条、《中华人民共和国民法典》第985条第（一）项之规定，倾向于按上述条文界定的构成要件与法律后果处理；但鉴于部分事实要件或时空要素尚待核实，上述结论成立需以下列「待核实关键事实」属实为前提，需进一步确认后方可定论。\\n\\n【四、待核实关键事实与补证建议】\\n- 法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）\\n- 确认争议双方的身份关系与法律关系性质凭证\\n- 确认相对人实施违法、违约或损害行为的具体表现与举证凭证\\n- 确认损害结果及具体诉请主张金额的计算依据\\n\\n【五、诉讼/仲裁时效与程序路径提示】\\n- 【诉讼时效】民事权利请求保护普通诉讼时效为 3 年（《民法典》第188条），自知道或者应当知道权利受损及义务人之日起算。\\n\\n【六、建议法务/律师核实引证的补充条文】\\n- 建议核查引证：《中华人民共和国民法典》第188条（待律师确认后一键纳入正式引用库）\\n\\n（受限兜底模式：本结论包含待确认前提，不得进入自动对外通道，必须经执业律师人工审核后方可使用）", "sentence_traces": [{"sentence_idx": 6, "sentence_text": "· 《中华人民共和国公司法》第3条（法律·现行有效）：公司是企业法人，有独立的法人财产，享有法人财产权。", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "公司是企业法人，有独立的法人财产，享有法人财产权", "trace_source": "explicit_anchor"}, {"sentence_idx": 7, "sentence_text": "公司以其全部财产对公司的债务承担责任。", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "公司以其全部财产对公司的债务承担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 8, "sentence_text": "有限责任公司的股东以其认缴的出资额为限对公司承担责任；", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "有限责任公司的股东以其认缴的出资额为限对公司承担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 9, "sentence_text": "股份有限公司的股东以其认购的股份为限对公司承担责任。", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "股份有限公司的股东以其认购的股份为限对公司承担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 11, "sentence_text": "· 《中华人民共和国民法典》第584条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 1.0, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 12, "sentence_text": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 1.0, "highlight_snippet": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失", "trace_source": "ngram_overlap"}, {"sentence_idx": 14, "sentence_text": "↳ 关联说明：［引致关联：第584条进一步明确违约损失赔偿额的范围（含可得利益）与可预见规则］", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 0.3848, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 15, "sentence_text": "· 《中华人民共和国公司法》第20条（法律·现行有效）：公司股东应当遵守法律、行政法规和公司章程，依法行使股东权利，不得滥用股东权利损害公司或者其他股东的利益；", "matched_law": "中华人民共和国公司法", "matched_article": "第20条", "confidence_score": 1.0, "highlight_snippet": "公司股东应当遵守法律、行政法规和公司章程，依法行使股东权利，不得滥用股东权利损害公司或者其他股东的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 16, "sentence_text": "不得滥用公司法人独立地位和股东有限责任损害公司债权人的利益。", "matched_law": "中华人民共和国公司法", "matched_article": "第20条", "confidence_score": 1.0, "highlight_snippet": "不得滥用公司法人独立地位和股东有限责任损害公司债权人的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 17, "sentence_text": "公司股东滥用公司法人独立地位和股东有限责任，逃避债务，严重损害公司债权人利益的，应当对公司债务承担连带责任。", "matched_law": "中华人民共和国公司法", "matched_article": "第20条", "confidence_score": 1.0, "highlight_snippet": "公司股东滥用公司法人独立地位和股东有限责任，逃避债务，严重损害公司债权人利益的，应当对公司债务承担连带责任", "trace_source": "explicit_anchor"}, {"sentence_idx": 19, "sentence_text": "· 《中华人民共和国民法典》第985条（法律·现行有效）：得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付；", "matched_law": "中华人民共和国民法典", "matched_article": "第985条", "confidence_score": 1.0, "highlight_snippet": "得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付", "trace_source": "explicit_anchor"}, {"sentence_idx": 20, "sentence_text": "（二）债务到期之前的清偿；", "matched_law": "中华人民共和国民法典", "matched_article": "第985条", "confidence_score": 1.0, "highlight_snippet": "（二）债务到期之前的清偿", "trace_source": "ngram_overlap"}, {"sentence_idx": 21, "sentence_text": "（三）明知无给付义务而进行的债务清偿。", "matched_law": "中华人民共和国民法典", "matched_article": "第985条", "confidence_score": 1.0, "highlight_snippet": "（三）明知无给付义务而进行的债务清偿", "trace_source": "ngram_overlap"}, {"sentence_idx": 23, "sentence_text": "· 《中华人民共和国民法典》第985条第（一）项（法律·现行有效）：得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付。", "matched_law": "中华人民共和国民法典", "matched_article": "第985条", "confidence_score": 1.0, "highlight_snippet": "得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但有下列情形之一的除外：（一）为履行道德义务进行的给付", "trace_source": "explicit_anchor"}, {"sentence_idx": 25, "sentence_text": "· 《中华人民共和国行政诉讼法》第12条（法律·现行有效）：人民法院受理公民、法人或者其他组织提起的下列诉讼：（一）对行政拘留、罚款、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、警告等行政处罚不服的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "人民法院受理公民、法人或者其他组织提起的下列诉讼：（一）对行政拘留、罚款、暂扣或者吊销许可证和执照、责令停产停业、没收违法所得、没收非法财物、警告等行政处罚不服的", "trace_source": "explicit_anchor"}, {"sentence_idx": 26, "sentence_text": "（二）对限制人身自由或者对财产的查封、扣押、冻结等行政强制措施和行政强制执行不服的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（二）对限制人身自由或者对财产的查封、扣押、冻结等行政强制措施和行政强制执行不服的", "trace_source": "ngram_overlap"}, {"sentence_idx": 27, "sentence_text": "（三）申请行政许可，行政机关拒绝或者在法定期限内不予答复，或者对行政机关作出的有关行政许可的其他决定不服的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（三）申请行政许可，行政机关拒绝或者在法定期限内不予答复，或者对行政机关作出的有关行政许可的其他决定不服的", "trace_source": "ngram_overlap"}, {"sentence_idx": 28, "sentence_text": "（四）对行政机关作出的关于确认土地、矿藏、水流、森林、山岭、草原、荒地、滩涂、海域等自然资源的所有权或者使用权的决定不服的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（四）对行政机关作出的关于确认土地、矿藏、水流、森林、山岭、草原、荒地、滩涂、海域等自然资源的所有权或者使用权的决定不服的", "trace_source": "ngram_overlap"}, {"sentence_idx": 29, "sentence_text": "（五）对征收、征用决定及其补偿决定不服的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（五）对征收、征用决定及其补偿决定不服的", "trace_source": "ngram_overlap"}, {"sentence_idx": 30, "sentence_text": "（六）申请行政机关履行保护人身权、财产权等合法权益的法定职责，行政机关拒绝履行或者不予答复的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（六）申请行政机关履行保护人身权、财产权等合法权益的法定职责，行政机关拒绝履行或者不予答复的", "trace_source": "ngram_overlap"}, {"sentence_idx": 31, "sentence_text": "（七）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（七）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权的", "trace_source": "ngram_overlap"}, {"sentence_idx": 32, "sentence_text": "（八）认为行政机关滥用行政权力排除或者限制竞争的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（八）认为行政机关滥用行政权力排除或者限制竞争的", "trace_source": "ngram_overlap"}, {"sentence_idx": 33, "sentence_text": "（九）认为行政机关违法集资、摊派费用或者违法要求履行其他义务的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（九）认为行政机关违法集资、摊派费用或者违法要求履行其他义务的", "trace_source": "ngram_overlap"}, {"sentence_idx": 34, "sentence_text": "（十）认为行政机关没有依法支付抚恤金、最低生活保障待遇或者社会保险待遇的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（十）认为行政机关没有依法支付抚恤金、最低生活保障待遇或者社会保险待遇的", "trace_source": "ngram_overlap"}, {"sentence_idx": 35, "sentence_text": "（十一）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议的；", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（十一）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议的", "trace_source": "ngram_overlap"}, {"sentence_idx": 36, "sentence_text": "（十二）认为行政机关侵犯其他人身权、财产权等合法权益的。", "matched_law": "中华人民共和国行政诉讼法", "matched_article": "第12条", "confidence_score": 1.0, "highlight_snippet": "（十二）认为行政机关侵犯其他人身权、财产权等合法权益的", "trace_source": "ngram_overlap"}, {"sentence_idx": 38, "sentence_text": "· 《中华人民共和国行政处罚法》第33条（法律·现行有效）：违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚", "trace_source": "explicit_anchor"}, {"sentence_idx": 39, "sentence_text": "初次违法且危害后果轻微并及时改正的，可以不予行政处罚。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "初次违法且危害后果轻微并及时改正的，可以不予行政处罚", "trace_source": "ngram_overlap"}, {"sentence_idx": 40, "sentence_text": "当事人有证据足以证明没有主观过错的，不予行政处罚。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "当事人有证据足以证明没有主观过错的，不予行政处罚", "trace_source": "ngram_overlap"}, {"sentence_idx": 41, "sentence_text": "法律、行政法规另有规定的，从其规定。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "法律、行政法规另有规定的，从其规定", "trace_source": "ngram_overlap"}, {"sentence_idx": 42, "sentence_text": "对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育", "trace_source": "ngram_overlap"}, {"sentence_idx": 44, "sentence_text": "· 《中华人民共和国消费者权益保护法》第26条（法律·现行有效）：经营者在经营活动中使用格式条款的，应当以显著方式提请消费者注意与消费者有重大利害关系的内容，并按照消费者的要求予以说明。", "matched_law": "中华人民共和国消费者权益保护法", "matched_article": "第26条", "confidence_score": 1.0, "highlight_snippet": "经营者在经营活动中使用格式条款的，应当以显著方式提请消费者注意与消费者有重大利害关系的内容，并按照消费者的要求予以说明", "trace_source": "explicit_anchor"}, {"sentence_idx": 45, "sentence_text": "经营者不得以格式条款、通知、声明、店堂告示等方式，作出排除或者限制消费者权利、减轻或者免除经营者责任、加重消费者责任等对消费者不公平、不合理的规定。", "matched_law": "中华人民共和国消费者权益保护法", "matched_article": "第26条", "confidence_score": 1.0, "highlight_snippet": "经营者不得以格式条款、通知、声明、店堂告示等方式，作出排除或者限制消费者权利、减轻或者免除经营者责任、加重消费者责任等对消费者不公平、不合理的规定", "trace_source": "ngram_overlap"}, {"sentence_idx": 46, "sentence_text": "含有前述内容的，其内容无效。", "matched_law": "中华人民共和国消费者权益保护法", "matched_article": "第26条", "confidence_score": 1.0, "highlight_snippet": "含有前述内容的，其内容无效", "trace_source": "ngram_overlap"}, {"sentence_idx": 48, "sentence_text": "· 《中华人民共和国公司法》第59条（法律·现行有效）：股东会行使下列职权：（一）选举和更换董事、监事，决定有关董事、监事的报酬事项；", "matched_law": "中华人民共和国公司法", "matched_article": "第59条", "confidence_score": 1.0, "highlight_snippet": "股东会行使下列职权：（一）选举和更换董事、监事，决定有关董事、监事的报酬事项", "trace_source": "explicit_anchor"}, {"sentence_idx": 49, "sentence_text": "（二）审议批准董事会的报告；", "matched_law": "中华人民共和国公司法", "matched_article": "第59条", "confidence_score": 1.0, "highlight_snippet": "（二）审议批准董事会的报告", "trace_source": "ngram_overlap"}, {"sentence_idx": 50, "sentence_text": 