REPLACE INTO session_snapshots (thread_id, updated_at, status, query, act_date, region, confidence, review_level, state_json) VALUES ('ceb007d6-4206-4b60-a0a9-d91974a30512', '2026-11-06T04:43:29.857797+00:00', 'needs_review', '开立基本账户时微企设固定场所，银行如何识别诈骗行为隐患？', '2026-11-06', '', 'B', 'must', '{"query": "开立基本账户时微企设固定场所，银行如何识别诈骗行为隐患？", "act_date": "2026-11-06", "region": "", "answer_confidence": "B", "rule_plan": {"mode": "llm_assisted", "confidence": "B", "review": "must", "llm_callable": true, "prompt_constraints": ["只能引用给定候选条文；不得生成任何未出现的条文号、法规名称或文号", "禁止使用“必然/一定/肯定/应当”等确定性表述；改用“在……前提下/倾向于/需进一步确认”", "必须显式说明：规则未覆盖的具体原因、不确定性来源、以及结论成立所需的前提", "必须给出至少一项建议核实或补证事项（如行为发生日期、制定机关、事实细节）", "本结论标记为兜底结果，不得进入自动对外通道，必须经人工审核后方可使用"], "verify_actions": ["向当事人核实法律事实发生的具体日期（或持续起止期间）", "法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）", "确认争议双方的身份关系与法律关系性质凭证", "确认相对人实施违法、违约或损害行为的具体表现与举证凭证"], "reason": "当事人未提供法律事实发生日期，暂按当前日期（2026-11-06）定位现行有效法；若系历史纠纷，适用依据可能不同；行为发生日 2026-11-06 不早于施行日 2021-01-01，且该条现行有效；行为发生日 2026-11-06 不早于施行日 2021-11-01，且该条现行有效；行为发生日 2026-11-06 不早于施行日 2008-01-01，且该条现行有效；行为发生日 2026-11-06 不早于施行日 2024-07-01，且该条现行有效；《中华人民共和国行政复议法》第11条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-06）适用现行有效规定；行为发生日 2026-11-06 不早于施行日 2021-07-15，且该条现行有效；行为发生日 2026-11-06 不早于施行日 1996-10-01，且该条现行有效"}, "final_output": {"citations": [{"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第1191条", "paragraph": "", "content": "用人单位的工作人员因执行工作任务造成他人损害，由用人单位承担侵权责任。用人单位承担侵权责任后，可以向有故意或者重大过失的工作人员追偿。劳务派遣期间，被派遣的工作人员因执行工作任务造成他人损害的，由接受劳务派遣的用工单位承担侵权责任；劳务派遣单位有过错的，承担相应的责任。", "source": "全国人民代表大会", "category": "侵权", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 28.9976, "rerank_score": 0.0567, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国个人信息保护法", "document_number": "主席令第91号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2021-08-20", "effective_date": "2021-11-01", "article_effective_date": "2021-11-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第13条", "paragraph": "", "content": "符合下列情形之一的，个人信息处理者方可处理个人信息：（一）取得个人的同意；（二）为订立、履行个人作为一方当事人的合同所必需，或者按照依法制定的劳动规章制度和依法签订的集体合同实施人力资源管理所必需；（三）为履行法定职责或者法定义务所必需；（四）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需；（五）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息；（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息；（七）法律、行政法规规定的其他情形。", "source": "全国人民代表大会常务委员会", "category": "数据合规", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 28.1024, "rerank_score": 0.0537, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国劳动合同法", "document_number": "主席令第73号（2012年修正）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2007-06-29", "effective_date": "2013-07-01", "article_effective_date": "2008-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第46条", "paragraph": "", "content": "有下列情形之一的，用人单位应当向劳动者支付经济补偿：（一）劳动者依照本法第三十八条规定解除劳动合同的；（二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的；（三）用人单位依照本法第四十条规定解除劳动合同的；（四）用人单位依照本法第四十一条第一款规定解除劳动合同的；（五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的。", "source": "全国人民代表大会常务委员会", "category": "劳动", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "与第38条（被迫解除）、第47条（经济补偿标准）构成完整引致链。", "score": 34.3831, "rerank_score": 0.0478, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "article_effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第47条", "paragraph": "", "content": "有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "［新旧法对照：2018版第26条实行无期限限制的注册资本认缴制；2023修订第47条（2024-07-01施行）改为自公司成立之日起5年内缴足的限期认缴制］ 2023-12-29修订通过、2024-07-01施行；行为发生日早于施行日的不得适用本条（法不溯及既往）。", "score": 24.3859, "rerank_score": 0.0406, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国行政复议法", "document_number": "主席令第9号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1999-04-29", "effective_date": "2024-01-01", "article_effective_date": "2024-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第11条", "paragraph": "", "content": "有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；（二）对行政机关作出的行政强制措施、行政强制执行决定不服；（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；（四）对行政机关作出的征收征用决定及其补偿决定不服；（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；（八）认为行政机关在政府信息公开工作中侵犯其合法权益；（九）认为行政机关滥用行政权力排除或者限制竞争；（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "norm_type": "procedural", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 41.7944, "rerank_score": 0.0383, "applicable_at": true, "applicable_note": "适用：程序法遵循「程序从新」原则，适用现行有效程序规定"}, {"law_name": "中华人民共和国行政处罚法", "document_number": "主席令第70号（2021年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1996-03-17", "effective_date": "2021-07-15", "article_effective_date": "2021-07-15", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第33条", "paragraph": "", "content": "违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "norm_type": "administrative_penalty", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 36.3276, "rerank_score": 0.0383, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第584条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 35.4056, "rerank_score": 0.0363, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第577条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］", "score": 55.1515, "rerank_score": 0.022, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国行政处罚法", "document_number": "主席令第70号（2021年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "1996-03-17", "effective_date": "2021-07-15", "article_effective_date": "1996-10-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第4条", "paragraph": "", "content": "公民、法人或者其他组织违反行政管理秩序的行为，应当给予行政处罚的，依照本法由法律、法规、规章规定，并由行政机关依照本法规定的程序实施。设定和实施行政处罚必须以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当。对违法行为给予行政处罚的规定必须公布；未经公布的，不得作为行政处罚的依据。", "source": "全国人民代表大会常务委员会", "category": "行政", "scope": "一般", "norm_type": "administrative_penalty", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 15.7652, "rerank_score": 0.0197, "applicable_at": true, "applicable_note": "适用：现行有效"}], "answer": "【一、争议焦点与事实前提】\\n· 时间前提声明：因未提供具体法律事实发生时间，本意见在**假设争议事实发生于现行法有效期内（暂以 2026-11-06 为基准日）**的前提下推演；若事实发生在旧法期间，须按行为时旧法重新定位。\\n· 争议焦点 1：开立基本账户时微企设固定场所，银行如何识别诈骗行为隐患\\n\\n【二、适用法规与效力要旨（大前提）】\\n· 《中华人民共和国民法典》第1191条（法律·现行有效）：用人单位的工作人员因执行工作任务造成他人损害，由用人单位承担侵权责任。用人单位承担侵权责任后，可以向有故意或者重大过失的工作人员追偿。劳务派遣期间，被派遣的工作人员因执行工作任务造成他人损害的，由接受劳务派遣的用工单位承担侵权责任；劳务派遣单位有过错的，承担相应的责任。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国个人信息保护法》第13条（法律·现行有效）：符合下列情形之一的，个人信息处理者方可处理个人信息：（一）取得个人的同意；（二）为订立、履行个人作为一方当事人的合同所必需，或者按照依法制定的劳动规章制度和依法签订的集体合同实施人力资源管理所必需；（三）为履行法定职责或者法定义务所必需；（四）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需；（五）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息；（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息；（七）法律、行政法规规定的其他情形。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国劳动合同法》第46条（法律·现行有效）：有下列情形之一的，用人单位应当向劳动者支付经济补偿：（一）劳动者依照本法第三十八条规定解除劳动合同的；（二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的；（三）用人单位依照本法第四十条规定解除劳动合同的；（四）用人单位依照本法第四十一条第一款规定解除劳动合同的；（五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国公司法》第47条（法律·现行有效）：有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。\\n  ↳ 效力说明：适用：现行有效\\n  ↳ 关联说明：［新旧法对照：2018版第26条实行无期限限制的注册资本认缴制；2023修订第47条（2024-07-01施行）改为自公司成立之日起5年内缴足的限期认缴制］ 2023-12-29修订通过、2024-07-01施行；行为发生日早于施行日的不得适用本条（法不溯及既往）。\\n· 《中华人民共和国行政复议法》第11条（法律·现行有效）：有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；（二）对行政机关作出的行政强制措施、行政强制执行决定不服；（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；（四）对行政机关作出的征收征用决定及其补偿决定不服；（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；（八）认为行政机关在政府信息公开工作中侵犯其合法权益；（九）认为行政机关滥用行政权力排除或者限制竞争；（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。\\n  ↳ 效力说明：适用：程序法遵循「程序从新」原则，适用现行有效程序规定\\n· 《中华人民共和国行政处罚法》第33条（法律·现行有效）：违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国民法典》第584条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国民法典》第577条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。\\n  ↳ 效力说明：适用：现行有效\\n  ↳ 关联说明：［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］\\n· 《中华人民共和国行政处罚法》第4条（法律·现行有效）：公民、法人或者其他组织违反行政管理秩序的行为，应当给予行政处罚的，依照本法由法律、法规、规章规定，并由行政机关依照本法规定的程序实施。设定和实施行政处罚必须以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当。对违法行为给予行政处罚的规定必须公布；未经公布的，不得作为行政处罚的依据。\\n  ↳ 效力说明：适用：现行有效\\n\\n【规范竞合与法理涵摄推演要求（法律适用关系未配置时的兜底约束）】\\n- 法律解释学涵摄：若涉及跨部门法或多部法律规范竞合且无绝对位阶排他，须严格遵循法律解释学（文义解释、体系解释、立法目的解释），将案件具体事实逐项对应代入规范要件进行涵摄推演；\\n- 审慎抗辩与双向争议提示：明确向用户披露潜在的法律适用分歧点与司法裁决倾向，禁止给出单向绝对化胜诉承诺，提供审慎的诉辩应对策略。\\n\\n【三、涵摄分析与初步结论（小前提推演）】\\n在现有候选依据范围内，结合《中华人民共和国民法典》第1191条、《中华人民共和国个人信息保护法》第13条、《中华人民共和国劳动合同法》第46条、《中华人民共和国公司法》第47条、《中华人民共和国行政复议法》第11条之规定，倾向于按上述条文界定的构成要件与法律后果处理；但鉴于部分事实要件或时空要素尚待核实，上述结论成立需以下列「待核实关键事实」属实为前提，需进一步确认后方可定论。\\n\\n【四、待核实关键事实与补证建议】\\n- 法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）\\n- 确认争议双方的身份关系与法律关系性质凭证\\n- 确认相对人实施违法、违约或损害行为的具体表现与举证凭证\\n- 确认损害结果及具体诉请主张金额的计算依据\\n\\n【五、诉讼/仲裁时效与程序路径提示】\\n- 【诉讼时效】民事权利请求保护普通诉讼时效为 3 年（《民法典》第188条），自知道或者应当知道权利受损及义务人之日起算。\\n\\n【六、建议法务/律师核实引证的补充条文】\\n- 建议核查引证：《中华人民共和国民法典》第188条（待律师确认后一键纳入正式引用库）\\n\\n（受限兜底模式：本结论包含待确认前提，不得进入自动对外通道，必须经执业律师人工审核后方可使用）", "sentence_traces": [{"sentence_idx": 6, "sentence_text": "· 《中华人民共和国民法典》第1191条（法律·现行有效）：用人单位的工作人员因执行工作任务造成他人损害，由用人单位承担侵权责任。", "matched_law": "中华人民共和国民法典", "matched_article": "第1191条", "confidence_score": 1.0, "highlight_snippet": "用人单位的工作人员因执行工作任务造成他人损害，由用人单位承担侵权责任", "trace_source": "explicit_anchor"}, {"sentence_idx": 7, "sentence_text": "用人单位承担侵权责任后，可以向有故意或者重大过失的工作人员追偿。", "matched_law": "中华人民共和国民法典", "matched_article": "第1191条", "confidence_score": 1.0, "highlight_snippet": "用人单位承担侵权责任后，可以向有故意或者重大过失的工作人员追偿", "trace_source": "ngram_overlap"}, {"sentence_idx": 8, "sentence_text": "劳务派遣期间，被派遣的工作人员因执行工作任务造成他人损害的，由接受劳务派遣的用工单位承担侵权责任；", "matched_law": "中华人民共和国民法典", "matched_article": "第1191条", "confidence_score": 1.0, "highlight_snippet": "劳务派遣期间，被派遣的工作人员因执行工作任务造成他人损害的，由接受劳务派遣的用工单位承担侵权责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 9, "sentence_text": "劳务派遣单位有过错的，承担相应的责任。", "matched_law": "中华人民共和国民法典", "matched_article": "第1191条", "confidence_score": 1.0, "highlight_snippet": "劳务派遣单位有过错的，承担相应的责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 11, "sentence_text": "· 《中华人民共和国个人信息保护法》第13条（法律·现行有效）：符合下列情形之一的，个人信息处理者方可处理个人信息：（一）取得个人的同意；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "符合下列情形之一的，个人信息处理者方可处理个人信息：（一）取得个人的同意", "trace_source": "explicit_anchor"}, {"sentence_idx": 12, "sentence_text": "（二）为订立、履行个人作为一方当事人的合同所必需，或者按照依法制定的劳动规章制度和依法签订的集体合同实施人力资源管理所必需；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "（二）为订立、履行个人作为一方当事人的合同所必需，或者按照依法制定的劳动规章制度和依法签订的集体合同实施人力资源管理所必需", "trace_source": "ngram_overlap"}, {"sentence_idx": 13, "sentence_text": "（三）为履行法定职责或者法定义务所必需；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "（三）为履行法定职责或者法定义务所必需", "trace_source": "ngram_overlap"}, {"sentence_idx": 14, "sentence_text": "（四）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "（四）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需", "trace_source": "ngram_overlap"}, {"sentence_idx": 15, "sentence_text": "（五）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "（五）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息", "trace_source": "ngram_overlap"}, {"sentence_idx": 16, "sentence_text": "（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息", "trace_source": "ngram_overlap"}, {"sentence_idx": 17, "sentence_text": "（七）法律、行政法规规定的其他情形。", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 1.0, "highlight_snippet": "（七）法律、行政法规规定的其他情形", "trace_source": "ngram_overlap"}, {"sentence_idx": 19, "sentence_text": "· 《中华人民共和国劳动合同法》第46条（法律·现行有效）：有下列情形之一的，用人单位应当向劳动者支付经济补偿：（一）劳动者依照本法第三十八条规定解除劳动合同的；", "matched_law": "中华人民共和国劳动合同法", "matched_article": "第46条", "confidence_score": 1.0, "highlight_snippet": "有下列情形之一的，用人单位应当向劳动者支付经济补偿：（一）劳动者依照本法第三十八条规定解除劳动合同的", "trace_source": "explicit_anchor"}, {"sentence_idx": 20, "sentence_text": "（二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的；", "matched_law": "中华人民共和国劳动合同法", "matched_article": "第46条", "confidence_score": 1.0, "highlight_snippet": "（二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的", "trace_source": "ngram_overlap"}, {"sentence_idx": 21, "sentence_text": "（三）用人单位依照本法第四十条规定解除劳动合同的；", "matched_law": "中华人民共和国劳动合同法", "matched_article": "第46条", "confidence_score": 1.0, "highlight_snippet": "（三）用人单位依照本法第四十条规定解除劳动合同的", "trace_source": "ngram_overlap"}, {"sentence_idx": 22, "sentence_text": "（四）用人单位依照本法第四十一条第一款规定解除劳动合同的；", "matched_law": "中华人民共和国劳动合同法", "matched_article": "第46条", "confidence_score": 1.0, "highlight_snippet": "（四）用人单位依照本法第四十一条第一款规定解除劳动合同的", "trace_source": "ngram_overlap"}, {"sentence_idx": 23, "sentence_text": "（五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的。", "matched_law": "中华人民共和国劳动合同法", "matched_article": "第46条", "confidence_score": 1.0, "highlight_snippet": "（五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的", "trace_source": "ngram_overlap"}, {"sentence_idx": 25, "sentence_text": "· 《中华人民共和国公司法》第47条（法律·现行有效）：有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。", "matched_law": "中华人民共和国公司法", "matched_article": "第47条", "confidence_score": 1.0, "highlight_snippet": "有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足", "trace_source": "explicit_anchor"}, {"sentence_idx": 26, "sentence_text": "法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。", "matched_law": "中华人民共和国公司法", "matched_article": "第47条", "confidence_score": 1.0, "highlight_snippet": "法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定", "trace_source": "ngram_overlap"}, {"sentence_idx": 29, "sentence_text": "2023修订第47条（2024-07-01施行）改为自公司成立之日起5年内缴足的限期认缴制］ 2023-12-29修订通过、2024-07-01施行；", "matched_law": "中华人民共和国公司法", "matched_article": "第47条", "confidence_score": 0.4284, "highlight_snippet": "有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足", "trace_source": "explicit_anchor"}, {"sentence_idx": 31, "sentence_text": "· 《中华人民共和国行政复议法》第11条（法律·现行有效）：有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服", "trace_source": "explicit_anchor"}, {"sentence_idx": 32, "sentence_text": "（二）对行政机关作出的行政强制措施、行政强制执行决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（二）对行政机关作出的行政强制措施、行政强制执行决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 33, "sentence_text": "（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（三）对行政机关作出的确认自然资源所有权或者使用权的决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 34, "sentence_text": "（四）对行政机关作出的征收征用决定及其补偿决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（四）对行政机关作出的征收征用决定及其补偿决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 35, "sentence_text": "（五）对行政机关作出的赔偿决定或者不予赔偿决定不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（五）对行政机关作出的赔偿决定或者不予赔偿决定不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 36, "sentence_text": "（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（六）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服", "trace_source": "ngram_overlap"}, {"sentence_idx": 37, "sentence_text": "（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（七）认为行政机关不依法履行、未按照约定履行或者违法变更、解除政府特许经营协议、土地房屋征收补偿协议等协议", "trace_source": "ngram_overlap"}, {"sentence_idx": 38, "sentence_text": "（八）认为行政机关在政府信息公开工作中侵犯其合法权益；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（八）认为行政机关在政府信息公开工作中侵犯其合法权益", "trace_source": "ngram_overlap"}, {"sentence_idx": 39, "sentence_text": "（九）认为行政机关滥用行政权力排除或者限制竞争；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（九）认为行政机关滥用行政权力排除或者限制竞争", "trace_source": "ngram_overlap"}, {"sentence_idx": 40, "sentence_text": "（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十）认为行政机关违法集资、摊派费用或者违法要求履行其他义务", "trace_source": "ngram_overlap"}, {"sentence_idx": 41, "sentence_text": "（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十一）申请行政机关履行保护人身权利、财产权利、受教育权利等合法权益的法定职责，行政机关拒绝履行、未依法履行或者不予答复", "trace_source": "ngram_overlap"}, {"sentence_idx": 42, "sentence_text": "（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十二）申请行政机关依法给付抚恤金、社会保险待遇或者最低生活保障等社会保障，行政机关没有依法给付", "trace_source": "ngram_overlap"}, {"sentence_idx": 43, "sentence_text": "（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十三）认为行政机关不依法履行、未按照约定履行或者违法变更、解除行政协议", "trace_source": "ngram_overlap"}, {"sentence_idx": 44, "sentence_text": "（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权；", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十四）认为行政机关侵犯其经营自主权或者农村土地承包经营权、农村土地经营权", "trace_source": "ngram_overlap"}, {"sentence_idx": 45, "sentence_text": "（十五）认为行政机关侵犯其他人身权、财产权等合法权益的。", "matched_law": "中华人民共和国行政复议法", "matched_article": "第11条", "confidence_score": 1.0, "highlight_snippet": "（十五）认为行政机关侵犯其他人身权、财产权等合法权益的", "trace_source": "ngram_overlap"}, {"sentence_idx": 47, "sentence_text": "· 《中华人民共和国行政处罚法》第33条（法律·现行有效）：违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚", "trace_source": "explicit_anchor"}, {"sentence_idx": 48, "sentence_text": "初次违法且危害后果轻微并及时改正的，可以不予行政处罚。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "初次违法且危害后果轻微并及时改正的，可以不予行政处罚", "trace_source": "ngram_overlap"}, {"sentence_idx": 49, "sentence_text": "当事人有证据足以证明没有主观过错的，不予行政处罚。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "当事人有证据足以证明没有主观过错的，不予行政处罚", "trace_source": "ngram_overlap"}, {"sentence_idx": 50, "sentence_text": "法律、行政法规另有规定的，从其规定。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "法律、行政法规另有规定的，从其规定", "trace_source": "ngram_overlap"}, {"sentence_idx": 51, "sentence_text": "对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第33条", "confidence_score": 1.0, "highlight_snippet": "对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育", "trace_source": "ngram_overlap"}, {"sentence_idx": 53, "sentence_text": "· 《中华人民共和国民法典》第584条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 1.0, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 54, "sentence_text": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 1.0, "highlight_snippet": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失", "trace_source": "ngram_overlap"}, {"sentence_idx": 56, "sentence_text": "· 《中华人民共和国民法典》第577条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。", "matched_law": "中华人民共和国民法典", "matched_article": "第577条", "confidence_score": 1.0, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任", "trace_source": "explicit_anchor"}, {"sentence_idx": 58, "sentence_text": "↳ 关联说明：［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］", "matched_law": "中华人民共和国民法典", "matched_article": "第577条", "confidence_score": 0.3707, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任", "trace_source": "explicit_anchor"}, {"sentence_idx": 59, "sentence_text": "· 《中华人民共和国行政处罚法》第4条（法律·现行有效）：公民、法人或者其他组织违反行政管理秩序的行为，应当给予行政处罚的，依照本法由法律、法规、规章规定，并由行政机关依照本法规定的程序实施。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第4条", "confidence_score": 1.0, "highlight_snippet": "公民、法人或者其他组织违反行政管理秩序的行为，应当给予行政处罚的，依照本法由法律、法规、规章规定，并由行政机关依照本法规定的程序实施", "trace_source": "explicit_anchor"}, {"sentence_idx": 60, "sentence_text": "设定和实施行政处罚必须以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第4条", "confidence_score": 1.0, "highlight_snippet": "设定和实施行政处罚必须以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当", "trace_source": "ngram_overlap"}, {"sentence_idx": 61, "sentence_text": "对违法行为给予行政处罚的规定必须公布；", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第4条", "confidence_score": 1.0, "highlight_snippet": "对违法行为给予行政处罚的规定必须公布", "trace_source": "ngram_overlap"}, {"sentence_idx": 62, "sentence_text": "未经公布的，不得作为行政处罚的依据。", "matched_law": "中华人民共和国行政处罚法", "matched_article": "第4条", "confidence_score": 1.0, "highlight_snippet": "未经公布的，不得作为行政处罚的依据", "trace_source": "ngram_overlap"}, {"sentence_idx": 68, "sentence_text": "在现有候选依据范围内，结合《中华人民共和国民法典》第1191条、《中华人民共和国个人信息保护法》第13条、《中华人民共和国劳动合同法》第46条、《中华人民共和国公司法》第47条、《中华人民共和国行政复议法》第11条之规定，倾向于按上述条文界定的构成要件与法律后果处理；", "matched_law": "中华人民共和国个人信息保护法", "matched_article": "第13条", "confidence_score": 0.3743, "highlight_snippet": "（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息", "trace_source": "explicit_anchor"}, {"sentence_idx": 76, "sentence_text": "- 【诉讼时效】民事权利请求保护普通诉讼时效为 3 年（《民法典》第188条），自知道或者应当知道权利受损及义务人之日起算。", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 0.3724, "highlight_snippet": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失", "trace_source": "explicit_anchor"}, {"sentence_idx": 78, "sentence_text": "- 建议核查引证：《中华人民共和国民法典》第188条（待律师确认后一键纳入正式引用库）", "matched_law": "中华人民共和国民法典", "matched_article": "第1191条", "confidence_score": 0.35, "highlight_snippet": "用人单位的工作人员因执行工作任务造成他人损害，由用人单位承担侵权责任", "trace_source": "explicit_anchor"}], "stru