REPLACE INTO session_snapshots (thread_id, updated_at, status, query, act_date, region, confidence, review_level, state_json) VALUES ('fb7b37b1-bc1a-4fd7-9d7b-209184a2d6f2', '2026-11-06T05:03:41.097665+00:00', 'needs_review', '你是什么模型', '', '', 'B', 'sample', '{"query": "你是什么模型", "act_date": "", "region": "", "answer_confidence": "B", "rule_plan": {"mode": "direct_llm", "status": "HIT", "confidence": "B", "review": "sample", "llm_callable": true, "reason": "已选择「不使用知识库」，跳过知识库检索，纯由大模型直接生成答复", "constraints": [], "verify_actions": []}, "final_output": {"citations": [], "answer": "【一、核心结论与解答要旨】\\n针对您咨询的问题「你是什么模型」（所属领域：法律与合规综合咨询），结合我国现行法律法规基本原则与司法实务通说：\\n当事人在主张相关法律权益或防范合规风险时，核心在于确认法律关系成立有效、相对方存在违约/侵权或未尽法定义务之事实，并确保证据链完整且在法定时效期间内行使权利。\\n\\n【二、法理分析与实务依据】\\n1. **主体资格与权利基础核验**：结合实务裁判与监管合规要求，需围绕当事人约定条款、法定职责边界以及客观履约事实进行综合认定，遵循诚实信用、权责相符与实质重于形式原则。\\n2. **核心法律行为或合规义务界定**：结合实务裁判与监管合规要求，需围绕当事人约定条款、法定职责边界以及客观履约事实进行综合认定，遵循诚实信用、权责相符与实质重于形式原则。\\n3. **违约/侵权/违规法律后果与救济路径分析**：结合实务裁判与监管合规要求，需围绕当事人约定条款、法定职责边界以及客观履约事实进行综合认定，遵循诚实信用、权责相符与实质重于形式原则。\\n\\n【三、实操建议与风险防范】\\n- 关键事实与证据梳理：法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）\\n- 关键事实与证据梳理：确认争议双方的身份关系与法律关系性质凭证\\n- 关键事实与证据梳理：确认相对人实施违法、违约或损害行为的具体表现与举证凭证\\n- 程序与时效提示：【诉讼时效】民事权利请求保护普通诉讼时效为 3 年（《民法典》第188条），自知道或者应当知道权利受损及义务人之日起算。", "sentence_traces": [], "structured_queries": {}, "missing_facts": ["法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）", "确认争议双方的身份关系与法律关系性质凭证", "确认相对人实施违法、违约或损害行为的具体表现与举证凭证", "确认损害结果及具体诉请主张金额的计算依据"], "clarification_questions": ["请问该争议事实发生的具体时间（或持续起止期间）是什么时候？", "请问双方之间是否存在书面协议、往来函件或即时通讯沟通记录？", "请问本案主张损害赔偿或违约责任的具体金额及计算依据是什么？"], "procedural_notes": ["【诉讼时效】民事权利请求保护普通诉讼时效为 3 年（《民法典》第188条），自知道或者应当知道权利受损及义务人之日起算。"], "suggested_citations": [], "disclaimer": "［生成式人工智能辅助生成｜算法备案与可追溯标识］ 本回答由 AI 基于检索法规自动推演生成（当前置信度：B），尚未完成执业律师终审签名，不构成正式法律意见书，仅供法律检索参考。"}, "fact_summary": {"act_date": "2026-11-06", "act_end_date": "", "act_date_source": "assumed_today", "date_granularity": "none", "is_continuous": false, "region": "", "case_types": ["一般民商事权益争议（动态推导）（动态要件