REPLACE INTO session_snapshots (thread_id, updated_at, status, query, act_date, region, confidence, review_level, state_json) VALUES ('27a6eb9a-9629-49d5-8880-ecb1e6620870', '2026-11-06T05:07:43.377777+00:00', 'needs_review', '你是什么模型', '', '', 'B', 'sample', '{"query": "你是什么模型", "act_date": "", "region": "", "answer_confidence": "B", "rule_plan": {"mode": "direct_llm", "status": "HIT", "confidence": "B", "review": "sample", "llm_callable": true, "reason": "已选择「不使用知识库」，跳过知识库检索，纯由大模型直接生成答复", "constraints": [], "verify_actions": []}, "final_output": {"citations": [], "answer": "【一、核心结论与解答要旨】\\n我是 **AI法盾·法律合规智能工作台** 的智能法律顾问助手。\\n\\n· **当前生效模型架构**：接入通义千问系列（当前选用：`qwen-plus`）及本地大模型增强引擎；\\n· **当前运行工作模式**：**「不使用知识库」自由对话模式**。在此模式下，系统已跳过本地知识库切片检索，直接基于预训练海量法律与合规常识、法理逻辑与自然语言理解能力，针对您提出的问题直接进行结构化分析与解答；\\n· **主要能力边界**：支持法律法规咨询、合同条款权责审查、劳动与商事争议要点拆解、行政合规要点提示等。\\n\\n【二、法理分析与实务依据】\\n1. **主体资格与权利基础核验**：结合实务裁判与监管合规要求，需围绕当事人约定条款、法定职责边界以及客观履约事实进行综合认定，遵循诚实信用、权责相符与实质重于形式原则。\\n2. **核心法律行为或合规义务界定**：结合实务裁判与监管合规要求，需围绕当事人约定条款、法定职责边界以及客观履约事实进行综合认定，遵循诚实信用、权责相符与实质重于形式原则。\\n3. **违约/侵权/违规法律后果与救济路径分析**：结合实务裁判与监管合规要求，需围绕当事人约定条款、法定职责边界以及客观履约事实进行综合认定，遵循诚实信用、权责相符与实质重于形式原则。\\n\\n【三、实操建议与风险防范】\\n- 建议妥善收集并留存书面合同、业务凭证、往来沟通记录及资金流水等原始证据材料。\\n- 注意在法定诉讼时效（一般民事权益保护诉讼时效为3年）或监管规定时限内及时采取救济措施。", "sentence_traces": [], "structured_queries": {}, "missing_facts": [], "clarification_questions": [], "procedural_notes": [], "suggested_citations": [], "disclaimer": "［生成式人工智能辅助生成｜算法备案与可追溯标识］ 本回答由 AI 基于检索法规自动推演生成（当前置信度：B），尚未完成执业律师终审签名，不构成正式法律意见书，仅供法律检索参考。"}, "fact_summary": {"act_date": "2026-11-06", "act_end_date": "", "act_date_source": "assumed_today", "date_granularity": "none", "is_continuous": false, "region": "", "case_types": ["通用问答与咨询"], "extracted_facts": [], "missing_facts": [], "clarification_questions": [], "procedural_notes": []}, "compliance_info": {"pii_masked": false, "pii_types": [], "has_conflict": false, "entities": [], "conflicts": []}, "rule_notes": ["模式说明：已选中「不使用知识库」，跳过知识库检索，纯由大模型直接生成答复。"], "human_approved": false}');
REPLACE INTO session_snapshots (thread_id, updated_at, status, query, act_date, region, confidence, review_level, state_json) VALUES ('717b7417-d009-45a6-ba8b-39707d62962a', '2026-11-06T05:31:26.739045+00:00', 'needs_review', '你是什么模型？', '2026-11-06', '', 'B', 'must', '{"query": "你是什么模型？", "act_date": "2026-11-06", "region": "", "answer_confidence": "B", "rule_plan": {"mode": "llm_assisted", "confidence": "B", "review": "must", "llm_callable": true, "prompt_constraints": ["只能引用给定候选条文；不得生成任何未出现的条文号、法规名称或文号", "禁止使用“必然/一定/肯定/应当”等确定性表述；改用“在……前提下/倾向于/需进一步确认”", "必须显式说明：规则未覆盖的具体原因、不确定性来源、以及结论成立所需的前提", "必须给出至少一项建议核实或补证事项（如行为发生日期、制定机关、事实细节）", "本结论标记为兜底结果，不得进入自动对外通道，必须经人工审核后方可使用"], "verify_actions": ["向当事人核实法律事实发生的具体日期（或持续起止期间）", "法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）"], "reason": "当事人未提供法律事实发生日期，暂按当前日期（2026-11-06）定位现行有效法；若系历史纠纷，适用依据可能不同；行为发生日 2026-11-06 不早于施行日 2024-07-01，且该条现行有效；《中华人民共和国劳动争议调解仲裁法》第27条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-06）适用现行有效规定；行为发生日 2026-11-06 不早于施行日 2021-01-01，且该条现行有效；行为发生日 2026-11-06 不早于施行日 2023-12-05，且该条现行有效"}, "final_output": {"citations": [{"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023年修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "article_effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第3条", "paragraph": "", "content": "公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。有限责任公司的股东以其认缴的出资额为限对公司承担责任；股份有限公司的股东以其认购的股份为限对公司承担责任。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 4.2466, "rerank_score": 0.0683, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国劳动争议调解仲裁法", "document_number": "主席令第80号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2007-12-29", "effective_date": "2008-05-01", "article_effective_date": "2008-05-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第27条", "paragraph": "", "content": "劳动争议申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出。", "source": "全国人民代表大会常务委员会", "category": "劳动", "scope": "特别", "norm_type": "procedural", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "劳动争议仲裁时效核心条文。", "score": 4.2108, "rerank_score": 0.0643, "applicable_at": true, "applicable_note": "适用：程序法遵循「程序从新」原则，适用现行有效程序规定"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第584条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 28.236, "rerank_score": 0.0341, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第153条", "paragraph": "", "content": "违反法律、行政法规的强制性规定的民事法律行为无效。但是，该强制性规定不导致该民事法律行为无效的除外。违背公序良俗的民事法律行为无效。", "source": "全国人民代表大会", "category": "民事", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "", "score": 20.4883, "rerank_score": 0.0248, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国民法典", "document_number": "主席令第45号", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2020-05-28", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第577条", "paragraph": "", "content": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。", "source": "全国人民代表大会", "category": "合同", "scope": "一般", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］", "score": 54.6548, "rerank_score": 0.0, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "中华人民共和国公司法", "document_number": "主席令第15号（2023修订）", "hierarchy": "法律", "host_law": "", "host_hierarchy": "", "host_effective_date": "", "promulgation_date": "2023-12-29", "effective_date": "2024-07-01", "article_effective_date": "2024-07-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第47条", "paragraph": "", "content": "有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。", "source": "全国人民代表大会常务委员会", "category": "公司", "scope": "特别", "norm_type": "substantive", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "［新旧法对照：2018版第26条实行无期限限制的注册资本认缴制；2023修订第47条（2024-07-01施行）改为自公司成立之日起5年内缴足的限期认缴制］ 2023-12-29修订通过、2024-07-01施行；行为发生日早于施行日的不得适用本条（法不溯及既往）。", "score": 18.0891, "rerank_score": 0.0, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释", "document_number": "法释〔2023〕13号", "hierarchy": "司法解释", "host_law": "中华人民共和国民法典", "host_hierarchy": "法律", "host_effective_date": "2021-01-01", "promulgation_date": "2023-12-04", "effective_date": "2023-12-05", "article_effective_date": "2023-12-05", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第3条", "paragraph": "", "content": "当事人对合同是否成立存在争议，人民法院能够确定当事人姓名或者名称、标的和数量的，一般应当认定合同成立。但是，法律另有规定或者当事人另有约定的除外。", "source": "最高人民法院", "category": "合同", "scope": "", "norm_type": "judicial_interpretation", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "位阶依附于《民法典》；原文据最高人民法院公告核实。", "score": 22.2623, "rerank_score": 0.0384, "applicable_at": true, "applicable_note": "适用：现行有效"}, {"law_name": "最高人民法院关于适用《中华人民共和国民法典》时间效力的若干规定", "document_number": "法释〔2020〕15号", "hierarchy": "司法解释", "host_law": "中华人民共和国民法典", "host_hierarchy": "法律", "host_effective_date": "2021-01-01", "promulgation_date": "2020-12-29", "effective_date": "2021-01-01", "article_effective_date": "2021-01-01", "effective_to": "", "validity": "现行有效", "superseded_by": "", "article": "第1条", "paragraph": "", "content": "民法典施行后的法律事实引起的民事纠纷案件，适用民法典的规定。民法典施行前的法律事实引起的民事纠纷案件，适用当时的法律、司法解释的规定，但是法律、司法解释另有规定的除外。民法典施行前产生的民事关系，持续至民法典施行后，该民事关系产生的民事纠纷案件，适用民法典的规定，但是法律、司法解释另有规定的除外。", "source": "最高人民法院", "category": "民事", "scope": "一般", "norm_type": "judicial_interpretation", "partially_invalid": false, "invalid_parts": "", "trial": false, "verified": true, "note": "明确法不溯及既往原则与持续性法律事实跨法从新规则。", "score": 29.5874, "rerank_score": 0.0259, "applicable_at": true, "applicable_note": "适用：现行有效"}], "answer": "【系统提示：外部大模型 (qwen-plus) 调用异常，已自动切换为确定性规则骨架生成，必须经执业律师复核】\\n\\n【一、争议焦点与事实前提】\\n· 时间前提声明：因未提供具体法律事实发生时间，本意见在**假设争议事实发生于现行法有效期内（暂以 2026-11-06 为基准日）**的前提下推演；若事实发生在旧法期间，须按行为时旧法重新定位。\\n· 争议焦点 1：你是什么模型\\n\\n【二、适用法规与效力要旨（大前提）】\\n· 《中华人民共和国公司法》第3条（法律·现行有效）：公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。有限责任公司的股东以其认缴的出资额为限对公司承担责任；股份有限公司的股东以其认购的股份为限对公司承担责任。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国劳动争议调解仲裁法》第27条（法律·现行有效）：劳动争议申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出。\\n  ↳ 效力说明：适用：程序法遵循「程序从新」原则，适用现行有效程序规定\\n· 《中华人民共和国民法典》第584条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国民法典》第153条（法律·现行有效）：违反法律、行政法规的强制性规定的民事法律行为无效。但是，该强制性规定不导致该民事法律行为无效的除外。违背公序良俗的民事法律行为无效。\\n  ↳ 效力说明：适用：现行有效\\n· 《中华人民共和国民法典》第577条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。\\n  ↳ 效力说明：适用：现行有效\\n  ↳ 关联说明：［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］\\n· 《中华人民共和国公司法》第47条（法律·现行有效）：有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。\\n  ↳ 效力说明：适用：现行有效\\n  ↳ 关联说明：［新旧法对照：2018版第26条实行无期限限制的注册资本认缴制；2023修订第47条（2024-07-01施行）改为自公司成立之日起5年内缴足的限期认缴制］ 2023-12-29修订通过、2024-07-01施行；行为发生日早于施行日的不得适用本条（法不溯及既往）。\\n· 《最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释》第3条（司法解释·现行有效）：当事人对合同是否成立存在争议，人民法院能够确定当事人姓名或者名称、标的和数量的，一般应当认定合同成立。但是，法律另有规定或者当事人另有约定的除外。\\n  ↳ 效力说明：适用：现行有效\\n· 《最高人民法院关于适用《中华人民共和国民法典》时间效力的若干规定》第1条（司法解释·现行有效）：民法典施行后的法律事实引起的民事纠纷案件，适用民法典的规定。民法典施行前的法律事实引起的民事纠纷案件，适用当时的法律、司法解释的规定，但是法律、司法解释另有规定的除外。民法典施行前产生的民事关系，持续至民法典施行后，该民事关系产生的民事纠纷案件，适用民法典的规定，但是法律、司法解释另有规定的除外。\\n  ↳ 效力说明：适用：现行有效\\n\\n【规范竞合与法理涵摄推演要求（法律适用关系未配置时的兜底约束）】\\n- 法律解释学涵摄：若涉及跨部门法或多部法律规范竞合且无绝对位阶排他，须严格遵循法律解释学（文义解释、体系解释、立法目的解释），将案件具体事实逐项对应代入规范要件进行涵摄推演；\\n- 审慎抗辩与双向争议提示：明确向用户披露潜在的法律适用分歧点与司法裁决倾向，禁止给出单向绝对化胜诉承诺，提供审慎的诉辩应对策略。\\n\\n【三、涵摄分析与初步结论（小前提推演）】\\n在现有候选依据范围内，结合《中华人民共和国公司法》第3条、《中华人民共和国劳动争议调解仲裁法》第27条、《中华人民共和国民法典》第584条、《中华人民共和国民法典》第153条、《中华人民共和国民法典》第577条之规定，倾向于按上述条文界定的构成要件与法律后果处理；但鉴于部分事实要件或时空要素尚待核实，上述结论成立需以下列「待核实关键事实」属实为前提，需进一步确认后方可定论。\\n\\n【四、待核实关键事实与补证建议】\\n- 法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）\\n\\n【五、诉讼/仲裁时效与程序路径提示】\\n- 【通用时效提示】民事权利普通诉讼时效为 3 年（《民法典》第188条）；劳动争议申请仲裁时效为 1 年；行政复议期限一般为 60 日、行政诉讼期限一般为 6 个月。\\n\\n（受限兜底模式：本结论包含待确认前提，不得进入自动对外通道，必须经执业律师人工审核后方可使用）", "sentence_traces": [{"sentence_idx": 7, "sentence_text": "· 《中华人民共和国公司法》第3条（法律·现行有效）：公司是企业法人，有独立的法人财产，享有法人财产权。", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "公司是企业法人，有独立的法人财产，享有法人财产权", "trace_source": "explicit_anchor"}, {"sentence_idx": 8, "sentence_text": "公司以其全部财产对公司的债务承担责任。", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "公司以其全部财产对公司的债务承担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 9, "sentence_text": "有限责任公司的股东以其认缴的出资额为限对公司承担责任；", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "有限责任公司的股东以其认缴的出资额为限对公司承担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 10, "sentence_text": "股份有限公司的股东以其认购的股份为限对公司承担责任。", "matched_law": "中华人民共和国公司法", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "股份有限公司的股东以其认购的股份为限对公司承担责任", "trace_source": "ngram_overlap"}, {"sentence_idx": 12, "sentence_text": "· 《中华人民共和国劳动争议调解仲裁法》第27条（法律·现行有效）：劳动争议申请仲裁的时效期间为一年。", "matched_law": "中华人民共和国劳动争议调解仲裁法", "matched_article": "第27条", "confidence_score": 1.0, "highlight_snippet": "劳动争议申请仲裁的时效期间为一年", "trace_source": "explicit_anchor"}, {"sentence_idx": 13, "sentence_text": "仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。", "matched_law": "中华人民共和国劳动争议调解仲裁法", "matched_article": "第27条", "confidence_score": 1.0, "highlight_snippet": "仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算", "trace_source": "ngram_overlap"}, {"sentence_idx": 14, "sentence_text": "劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；", "matched_law": "中华人民共和国劳动争议调解仲裁法", "matched_article": "第27条", "confidence_score": 1.0, "highlight_snippet": "劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制", "trace_source": "ngram_overlap"}, {"sentence_idx": 15, "sentence_text": "但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出。", "matched_law": "中华人民共和国劳动争议调解仲裁法", "matched_article": "第27条", "confidence_score": 1.0, "highlight_snippet": "但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出", "trace_source": "ngram_overlap"}, {"sentence_idx": 17, "sentence_text": "· 《中华人民共和国民法典》第584条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 1.0, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益", "trace_source": "explicit_anchor"}, {"sentence_idx": 18, "sentence_text": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。", "matched_law": "中华人民共和国民法典", "matched_article": "第584条", "confidence_score": 1.0, "highlight_snippet": "但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失", "trace_source": "ngram_overlap"}, {"sentence_idx": 20, "sentence_text": "· 《中华人民共和国民法典》第153条（法律·现行有效）：违反法律、行政法规的强制性规定的民事法律行为无效。", "matched_law": "中华人民共和国民法典", "matched_article": "第153条", "confidence_score": 1.0, "highlight_snippet": "违反法律、行政法规的强制性规定的民事法律行为无效", "trace_source": "explicit_anchor"}, {"sentence_idx": 21, "sentence_text": "但是，该强制性规定不导致该民事法律行为无效的除外。", "matched_law": "中华人民共和国民法典", "matched_article": "第153条", "confidence_score": 1.0, "highlight_snippet": "但是，该强制性规定不导致该民事法律行为无效的除外", "trace_source": "ngram_overlap"}, {"sentence_idx": 22, "sentence_text": "违背公序良俗的民事法律行为无效。", "matched_law": "中华人民共和国民法典", "matched_article": "第153条", "confidence_score": 1.0, "highlight_snippet": "违背公序良俗的民事法律行为无效", "trace_source": "ngram_overlap"}, {"sentence_idx": 24, "sentence_text": "· 《中华人民共和国民法典》第577条（法律·现行有效）：当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。", "matched_law": "中华人民共和国民法典", "matched_article": "第577条", "confidence_score": 1.0, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任", "trace_source": "explicit_anchor"}, {"sentence_idx": 26, "sentence_text": "↳ 关联说明：［新旧法对照：《合同法》第107条于2021-01-01被《民法典》第577条替代，违约责任构成要件与救济方式保持延续］", "matched_law": "中华人民共和国民法典", "matched_article": "第577条", "confidence_score": 0.3707, "highlight_snippet": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任", "trace_source": "explicit_anchor"}, {"sentence_idx": 27, "sentence_text": "· 《中华人民共和国公司法》第47条（法律·现行有效）：有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。", "matched_law": "中华人民共和国公司法", "matched_article": "第47条", "confidence_score": 1.0, "highlight_snippet": "有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足", "trace_source": "explicit_anchor"}, {"sentence_idx": 28, "sentence_text": "法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定。", "matched_law": "中华人民共和国公司法", "matched_article": "第47条", "confidence_score": 1.0, "highlight_snippet": "法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额另有规定的，从其规定", "trace_source": "ngram_overlap"}, {"sentence_idx": 31, "sentence_text": "2023修订第47条（2024-07-01施行）改为自公司成立之日起5年内缴足的限期认缴制］ 2023-12-29修订通过、2024-07-01施行；", "matched_law": "中华人民共和国公司法", "matched_article": "第47条", "confidence_score": 0.4284, "highlight_snippet": "有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额，全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足", "trace_source": "explicit_anchor"}, {"sentence_idx": 33, "sentence_text": "· 《最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释》第3条（司法解释·现行有效）：当事人对合同是否成立存在争议，人民法院能够确定当事人姓名或者名称、标的和数量的，一般应当认定合同成立。", "matched_law": "最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "当事人对合同是否成立存在争议，人民法院能够确定当事人姓名或者名称、标的和数量的，一般应当认定合同成立", "trace_source": "explicit_anchor"}, {"sentence_idx": 34, "sentence_text": "但是，法律另有规定或者当事人另有约定的除外。", "matched_law": "最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释", "matched_article": "第3条", "confidence_score": 1.0, "highlight_snippet": "但是，法律另有规定或者当事人另有约定的除外", "trace_source": "ngram_overlap"}, {"sentence_idx": 36, "sentence_text": "· 《最高人民法院关于适用《中华人民共和国民法典》时间效力的若干规定》第1条（司法解释·现行有效）：民法典施行后的法律事实引起的民事纠纷案件，适用民法典的规定。", "matched_law": "最高人民法院关于适用《中华人民共和国民法典》时间效力的若干规定", "matched_article": "第1条", "confidence_score": 1.0, "highlight_snippet": "民法典施行后的法律事实引起的民事纠纷案件，适用民法典的规定", "trace_source": "explicit_anchor"}, {"sentence_idx": 37, "sentence_text": "民法典施行前的法律事实引起的民事纠纷案件，适用当时的法律、司法解释的规定，但是法律、司法解释另有规定的除外。", "matched_law": "最高人民法院关于适用《中华人民共和国民法典》时间效力的若干规定", "matched_article": "第1条", "confidence_score": 1.0, "highlight_snippet": "民法典施行前的法律事实引起的民事纠纷案件，适用当时的法律、司法解释的规定，但是法律、司法解释另有规定的除外", "trace_source": "explicit_anchor"}, {"sentence_idx": 38, "sentence_text": "民法典施行前产生的民事关系，持续至民法典施行后，该民事关系产生的民事纠纷案件，适用民法典的规定，但是法律、司法解释另有规定的除外。", "matched_law": "最高人民法院关于适用《中华人民共和国民法典》时间效力的若干规定", "matched_article": "第1条", "confidence_score": 1.0, "highlight_snippet": "民法典施行前产生的民事关系，持续至民法典施行后，该民事关系产生的民事纠纷案件，适用民法典的规定，但是法律、司法解释另有规定的除外", "trace_source": "explicit_anchor"}, {"sentence_idx": 44, "sentence_text": "在现有候选依据范围内，结合《中华人民共和国公司法》第3条、《中华人民共和国劳动争议调解仲裁法》第27条、《中华人民共和国民法典》第584条、《中华人民共和国民法典》第153条、《中华人民共和国民法典》第577条之规定，倾向于按上述条文界定的构成要件与法律后果处理；", "matched_law": "中华人民共和国劳动争议调解仲裁法", "matched_article": "第27条", "confidence_score": 0.3711, "highlight_snippet": "劳动争议申请仲裁的时效期间为一年", "trace_source": "explicit_anchor"}, {"sentence_idx": 49, "sentence_text": "- 【通用时效提示】民事权利普通诉讼时效为 3 年（《民法典》第188条）；", "matched_law": "中华人民共和国民法典", "matched_article": "第153条", "confidence_score": 0.3553, "highlight_snippet": "违背公序良俗的民事法律行为无效", "trace_source": "explicit_anchor"}, {"sentence_idx": 50, "sentence_text": "劳动争议申请仲裁时效为 1 年；", "matched_law": "中华人民共和国劳动争议调解仲裁法", "matched_article": "第27条", "confidence_score": 0.3178, "highlight_snippet": "劳动争议申请仲裁的时效期间为一年", "trace_source": "ngram_overlap"}], "structured_queries": {"focus": ["你是什么模型 构成要件 适用规定"], "exception": ["你是什么模型 除外情形 免责事由 不适用", "你是什么模型 禁止性规定 排除适用"], "consequence": ["你是什么模型 法律后果 法律责任 效力认定", "你是什么模型 违约损害赔偿 追偿与补救措施"]}, "missing_facts": ["法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）"], "clarification_questions": ["请问该争议事实发生的具体时间（或持续起止期间）是什么时候？"], "procedural_notes": ["【通用时效提示】民事权利普通诉讼时效为 3 年（《民法典》第188条）；劳动争议申请仲裁时效为 1 年；行政复议期限一般为 60 日、行政诉讼期限一般为 6 个月。"], "suggested_citations": [], "disclaimer": "［生成式人工智能辅助生成｜算法备案与可追溯标识］ 本回答由 AI 基于检索法规自动推演生成（当前置信度：B），尚未完成执业律师终审签名，不构成正式法律意见书，仅供法律检索参考。"}, "fact_summary": {"act_date": "2026-11-06", "act_end_date": "", "act_date_source": "assumed_today", "date_granularity": "none", "is_continuous": false, "region": "", "case_types": [], "extracted_facts": [], "missing_facts": ["法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）"], "clarification_questions": ["请问该争议事实发生的具体时间（或持续起止期间）是什么时候？"], "procedural_notes": ["【通用时效提示】民事权利普通诉讼时效为 3 年（《民法典》第188条）；劳动争议申请仲裁时效为 1 年；行政复议期限一般为 60 日、行政诉讼期限一般为 6 个月。"], "suggested_citations": [], "dyn