REPLACE INTO session_snapshots (thread_id, updated_at, status, query, act_date, region, confidence, review_level, state_json) VALUES ('5574e641-9470-47b6-b81f-39da65deaf07', '2026-11-06T10:07:45.721578+00:00', 'needs_review', '那如果遇到劳动合同纠纷，你能怎么帮我？', '', '', 'A', 'sample', '{"query": "那如果遇到劳动合同纠纷，你能怎么帮我？", "act_date": "", "region": "", "answer_confidence": "A", "rule_plan": {"mode": "direct_llm", "status": "DIRECT_LLM", "confidence": "A", "review": "sample", "llm_callable": true, "reason": "已选择「不使用知识库」，直接提交大模型回答，不走任何法律助手的规则和输出框架", "constraints": [], "verify_actions": []}, "final_output": {"citations": [], "answer": "结合我们刚才讨论的上下文，针对您的进一步提问「那如果遇到劳动合同纠纷，你能怎么帮我？」：\\n\\n在前面交流的基础上，建议关注以下几个核心方向：\\n1. **关键要点对齐**：承接上文的讨论背景，细化明确当前阶段的具体诉求与各方权责；\\n2. **落地操作建议**：根据实际情况制定切实可行的执行方案，注意把握推进节点并做好过程记录；\\n3. **风险防范措施**：提前排查潜在的分歧点或阻碍，准备好相应的应对备选方案。\\n\\n若您需要针对其中的特定细节进行方案细化或起草文案，请随时告诉我！", "sentence_traces": [], "structured_queries": {}, "missing_facts": [], "clarification_questions": [], "procedural_notes": [], "suggested_citations": [], "disclaimer": ""}, "fact_summary": {"act_date": "2026-11-06", "act_end_date": "", "act_date_source": "assumed_today", "date_granularity": "none", "is_continuous": false, "region": "", "case_types": ["通用问答与咨询"], "extracted_facts": [], "missing_facts": [], "clarification_questions": [], "procedural_notes": []}, "compliance_info": {"pii_masked": false, "pii_types": [], "has_conflict": false, "entities": [], "conflicts": []}, "rule_notes": ["模式说明：已选中「不使用知识库」，直接将输入框内容提交给大模型回答（不走法律助手的规则和输出框架）。", "LLM调用回退说明：调用外部大模型接口 (https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions, model=qwen-turbo) 失败: HTTP Error 429: Too Many Requests"], "human_approved": false}');
