INSERT INTO rule_gaps (thread_id, timestamp, mode, confidence, review_level, reason, verify_actions_json, query) VALUES ('thread-test-dynamic-construct', '2026-11-03T11:10:30.314259+00:00', 'llm_assisted', 'B', 'must', '行为发生时间仅精确到year（按 2024-06-01 推算），需确认具体日期以防跨新旧法分界点；行为发生日 2024-06-01 不早于施行日 2008-01-01，且该条现行有效；《中华人民共和国劳动争议调解仲裁法》第27条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-03）适用现行有效规定；持续性法律事实自 2024-06-01 持续至 2026-11-03（跨越新法施行日 2024-07-01），依《民法典时间效力规定》第1条第3款等持续性事实规则，适用新法《中华人民共和国公司法》第4条；《中华人民共和国行政诉讼法》第12条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-03）适用现行有效规定；行为发生日 2024-06-01 不早于施行日 2021-01-01，且该条现行有效；《中华人民共和国行政复议法》第11条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-03）适用现行有效规定；行为发生日 2024-06-01 不早于施行日 2002-05-01，且该条现行有效；地域效力待核实：《上海市劳动合同条例》系上海地方性法规，仅在行为地/用工地/履行地位于上海时方可适用；《上海市劳动合同条例》第1条未经权威来源核验（verified=false），不得作为正式对外依据；行为发生日 2024-06-01 不早于施行日 1995-01-01，且该条现行有效；《工资支付暂行规定》第7条未经权威来源核验（verified=false），不得作为正式对外依据', '["向当事人确认法律事实发生的具体年月日", "核实案件用工地/合同履行地/行为发生地是否位于上海", "对照官方权威文本核验《上海市劳动合同条例》第1条条文原文与现行有效性", "对照官方权威文本核验《工资支付暂行规定》第7条条文原文与现行有效性", "法律事实发生的具体日期（当前仅精确到年/月，若跨新旧法施行日需精确到日）", "确认是否已签订书面劳动合同，以及未签合同持续的月数", "确认目前仍在职还是已解除劳动关系，以及解除通知的送达时间（关系到1年仲裁时效起算）"]', '2024年包工头带领工人完成厂房主体结构施工，总承包方至今拖欠500万工程款拒不结算且未验收');
INSERT INTO rule_gaps (thread_id, timestamp, mode, confidence, review_level, reason, verify_actions_json, query) VALUES ('dyn-test-1', '2026-11-03T11:10:57.973590+00:00', 'llm_assisted', 'B', 'must', '当事人未提供法律事实发生日期，暂按当前日期（2026-11-03）定位现行有效法；若系历史纠纷，适用依据可能不同；行为发生日 2026-11-03 不早于施行日 2008-01-01，且该条现行有效；行为发生日 2026-11-03 不早于施行日 2021-01-01，且该条现行有效；《中华人民共和国行政复议法》第11条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-03）适用现行有效规定；行为发生日 2026-11-03 不早于施行日 1995-01-01，且该条现行有效；《工资支付暂行规定》第7条未经权威来源核验（verified=false），不得作为正式对外依据；上位法优于下位法：《中华人民共和国劳动合同法》（法律）优先于《工资支付暂行规定》（部门规章）', '["向当事人核实法律事实发生的具体日期（或持续起止期间）", "对照官方权威文本核验《工资支付暂行规定》第7条条文原文与现行有效性", "法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）", "确认施工合同效力（是否存在未取得建设工程施工许可证、转包、借用资质挂靠或违法分包情形）", "确认工程是否已竣工验收合格及工程价款结算审价凭证"]', '包工头承包厂房主体结构施工，发包人迟延支付500万工程进度款拒不审价');
