INSERT INTO rule_gaps (thread_id, timestamp, mode, confidence, review_level, reason, verify_actions_json, query) VALUES ('rule_engine', '2026-11-03T14:11:18.376501+00:00', 'llm_assisted', 'B', 'must', '行为发生日 2025-05-01 不早于施行日 2021-01-01，且该条现行有效；《中华人民共和国劳动争议调解仲裁法》第27条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-03）适用现行有效规定；行为发生日 2025-05-01 不早于施行日 1994-01-01，且该条现行有效；《中华人民共和国民事诉讼法》第67条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-03）适用现行有效规定；《中华人民共和国行政诉讼法》第89条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-03）适用现行有效规定；行为发生日 2025-05-01 不早于施行日 2008-01-01，且该条现行有效；《中华人民共和国行政诉讼法》第70条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-03）适用现行有效规定；行为发生日 2025-05-01 不早于施行日 2023-12-05，且该条现行有效；行为发生日 2025-05-01 不早于施行日 2002-05-01，且该条现行有效；地域效力待核实：《上海市劳动合同条例》系上海地方性法规，仅在行为地/用工地/履行地位于上海时方可适用；《上海市劳动合同条例》第1条未经权威来源核验（verified=false），不得作为正式对外依据', '["核实案件用工地/合同履行地/行为发生地是否位于上海", "对照官方权威文本核验《上海市劳动合同条例》第1条条文原文与现行有效性", "确认争议双方的身份关系与法律关系性质凭证", "确认相对人实施违法、违约或损害行为的具体表现与举证凭证", "确认损害结果及具体诉请主张金额的计算依据"]', '向人民法院请求保护民事权利的三年诉讼时效期间怎么起算？劳动争议申请仲裁的时效期间是多久？');
INSERT INTO rule_gaps (thread_id, timestamp, mode, confidence, review_level, reason, verify_actions_json, query) VALUES ('rule_engine', '2026-11-03T14:11:18.617677+00:00', 'llm_assisted', 'B', 'must', '当事人未提供法律事实发生日期，暂按当前日期（2026-11-03）定位现行有效法；若系历史纠纷，适用依据可能不同；行为发生日 2026-11-03 不早于施行日 2021-01-01，且该条现行有效；行为发生日 2026-11-03 不早于施行日 2023-12-05，且该条现行有效；司法解释依附于被解释法律：最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释系对《中华人民共和国民法典》的解释，适用时以《中华人民共和国民法典》为准并参照该解释细化', '["向当事人核实法律事实发生的具体日期（或持续起止期间）", "法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）", "确认合同成立/生效时间及约定的履行期限（决定适用《民法典》还是旧《合同法》）"]', '对方违约不履行合同义务，我能否要求继续履行并赔偿损失？');
