INSERT INTO rule_gaps (thread_id, timestamp, mode, confidence, review_level, reason, verify_actions_json, query) VALUES ('rule_engine', '2026-11-07T08:01:15.929192+00:00', 'llm_assisted', 'B', 'must', '当事人未提供法律事实发生日期，暂按当前日期（2026-11-07）定位现行有效法；若系历史纠纷，适用依据可能不同；行为发生日 2026-11-07 不早于施行日 2021-01-01，且该条现行有效；《中华人民共和国行政复议法》第11条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-07）适用现行有效规定；《中华人民共和国行政诉讼法》第12条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-07）适用现行有效规定；行为发生日 2026-11-07 不早于施行日 2023-12-05，且该条现行有效；司法解释依附于被解释法律：最高人民法院关于适用《中华人民共和国民法典》合同编通则若干问题的解释系对《中华人民共和国民法典》的解释，适用时以《中华人民共和国民法典》为准并参照该解释细化', '["向当事人核实法律事实发生的具体日期（或持续起止期间）", "法律事实发生的具体日期（决定适用现行法还是行为时旧法，以及是否超过诉讼/仲裁时效）", "确认合同成立/生效时间及约定的履行期限（决定适用《民法典》还是旧《合同法》）"]', '对方违约不履行合同义务，我能否要求继续履行并赔偿损失？');
INSERT INTO rule_gaps (thread_id, timestamp, mode, confidence, review_level, reason, verify_actions_json, query) VALUES ('rule_engine', '2026-11-07T08:01:16.242278+00:00', 'llm_assisted', 'B', 'expert', '利益冲突预警：检测到涉案主体「北京澜舟科技有限公司」与「澜舟科技有限公司」（本所常年法律顾问客户）高度关联，请承办律师依《律师法》第39条完成利益冲突审查后再出具正式意见。；行为发生日 2025-05-01 不早于施行日 2021-01-01，且该条现行有效；行为发生日 2025-05-01 不早于施行日 2024-07-01，且该条现行有效；《中华人民共和国行政诉讼法》第12条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-07）适用现行有效规定；《中华人民共和国行政复议法》第11条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-07）适用现行有效规定；行为发生日 2025-05-01 不早于施行日 2023-12-05，且该条现行有效', '["由律所合伙人/风控主管完成《律师法》第39条利益冲突检索与豁免审批", "确认合同成立/生效时间及约定的履行期限（决定适用《民法典》还是旧《合同法》）", "确认合同约定的违约金计算标准及守约方实际遭受的直接损失与可得利益损失", "确认公司设立日期、章程约定的认缴出资期限及争议行为发生日（2024-07-01 新《公司法》施行前后规则不同）"]', '我方拟起诉北京澜舟科技有限公司不履行合同义务，身份证110***********8888');
INSERT INTO rule_gaps (thread_id, timestamp, mode, confidence, review_level, reason, verify_actions_json, query) VALUES ('thread-test-dynamic-construct', '2026-11-07T08:01:16.901368+00:00', 'llm_assisted', 'B', 'must', '行为发生时间仅精确到year（按 2024-06-01 推算），需确认具体日期以防跨新旧法分界点；行为发生日 2024-06-01 不早于施行日 2008-01-01，且该条现行有效；行为发生日 2024-06-01 落在该条有效区间（2018-10-26 ~ 2024-06-30）内，适用行为时的旧法；《中华人民共和国行政诉讼法》第12条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-07）适用现行有效规定；行为发生日 2024-06-01 不早于施行日 2021-01-01，且该条现行有效；行为发生日 2024-06-01 不早于施行日 2021-07-15，且该条现行有效；《中华人民共和国行政复议法》第11条系程序法规范，遵循「程序从新」原则，按当前审理/咨询时点（2026-11-07）适用现行有效规定；行为发生日 2024-06-01 不早于施行日 2023-12-05，且该条现行有效', '["向当事人确认法律事实发生的具体年月日", "确认现行替代依据，并核对新旧法的衔接适用规则", "法律事实发生的具体日期（当前仅精确到年/月，若跨新旧法施行日需精确到日）", "确认施工合同效力（是否存在未取得建设工程施工许可证、转包、借用资质挂靠或违法分包情形）", "确认工程是否已竣工验收合格及工程价款结算审价凭证"]', '2024年包工头承包厂房主体结构施工，发包人迟延支付500万工程进度款拒不审价');
